insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('puree-carotte-pomme-de-terre', 'Purée carotte et pomme de terre', 'Le grand classique des premières purées : douce, orange et rassurante.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18']::text[], 6, 18, array['smooth','mashed']::text[], 4, 'portions bébé', 10, 20, array[]::text[], array['puree','vegetables','budget','freezer','batch','family','classic']::text[], array['Pour la famille : la même purée, salée à part après avoir servi le bébé.','Plus tard, ajoutez 10 g de poulet ou de poisson blanc cuit à cœur, mixé.']::text[], 'Réfrigérateur : 48 h dans un pot fermé. Congélateur : 1 mois en portions (bacs à glaçons) ; décongeler au réfrigérateur, réchauffer une seule fois et vérifier la température.', 'Se congèle très bien : 1 mois en portions (bacs à glaçons) ; décongeler au réfrigérateur, réchauffer une seule fois.', array['Sans sel ni sucre ajoutés.','Les quantités sont indicatives : suivez l’appétit de votre enfant et les conseils de son médecin.']::text[], 'Carotte et pomme de terre : un mélange doux et nourrissant pour découvrir les légumes ; le lait reste l’aliment principal la première année.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-19', 'to_review') on conflict (slug) do nothing;
