insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'puree-carotte-pomme-de-terre' and owner_id is null), 2, 'potato', 'pomme de terre', 150, 'g', '1 pomme de terre moyenne', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'puree-carotte-pomme-de-terre' and owner_id is null), 3, 'rapeseed_oil', 'huile de colza', 2, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'puree-carotte-pomme-de-terre' and owner_id is null), 1, 'Lavez et épluchez les carottes et la pomme de terre, puis coupez-les en morceaux réguliers.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'puree-carotte-pomme-de-terre' and owner_id is null), 2, 'Faites cuire les légumes 20 minutes à la vapeur, jusqu’à ce qu’ils s’écrasent facilement à la fourchette.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'puree-carotte-pomme-de-terre' and owner_id is null), 3, 'Mixez finement pour une purée lisse, ou écrasez à la fourchette pour une texture écrasée, selon ce que votre bébé accepte.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'puree-carotte-pomme-de-terre' and owner_id is null), 4, 'Ajoutez une demi-cuillère à café d’huile de colza par portion au moment de servir.') on conflict do nothing;
