insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-poulet-roti-pommes-de-terre-haricots-verts', 'Poulet rôti, pommes de terre et haricots verts', 'Le repas du dimanche par excellence : une volaille dorée, des pommes de terre fondantes et des haricots verts croquants.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 15, 50, array[]::text[], array['protein','vegetables','classic','family']::text[], array['Avec un poulet entier d’environ 1,5 kg, comptez 1 h 15 de cuisson à 200 °C et vérifiez le jus à la jointure de la cuisse.','Remplacez les haricots verts par des carottes, rôties avec les pommes de terre.']::text[], 'Réfrigérateur : 2 jours dans une boîte fermée, la viande retirée de l’os ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', 'Le poulet cuit, retiré de l’os, se congèle jusqu’à 3 mois ; décongelez-le une nuit au réfrigérateur et réchauffez-le bien à cœur. Les pommes de terre rôties et les haricots verts supportent mal la congélation.', array['Grossesse : le poulet doit être cuit à cœur, sans aucune trace rosée près de l’os.','Utilisez une planche et un couteau réservés à la viande crue, puis lavez-les à l’eau chaude savonneuse avant de toucher aux légumes.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Un repas complet et classique : la volaille apporte des protéines, les pommes de terre un féculent et les haricots verts des fibres.', 2, array[]::text[], 'hot', '{"child":"Retirez la peau, coupez la viande en petits morceaux et écrasez les pommes de terre pour les plus petits."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 1, 'chicken_thigh', 'cuisses de poulet', 4, 'u', 'environ 1 kg', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 2, 'potato', 'pomme de terre', 800, 'g', 'à chair ferme', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 3, 'green_beans', 'haricots verts', 400, 'g', 'frais ou surgelés', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 4, 'garlic', 'ail', 3, 'u', 'gousses', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 5, 'thyme', 'thym', 1, 'cc', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 6, 'olive_oil', 'huile d''olive', 3, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Épluchez les pommes de terre, coupez-les en quartiers et mettez-les dans un grand plat avec les gousses d’ail en chemise, 2 cuillères à soupe d’huile d’olive et le thym.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 2, 'Posez les cuisses de poulet par-dessus, badigeonnez-les avec le reste d’huile et enfournez pour 45 minutes, en arrosant la viande à mi-cuisson avec le jus du plat.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 3, 'Pendant ce temps, équeutez et lavez les haricots verts, puis faites-les cuire 10 à 12 minutes à la vapeur : ils doivent rester légèrement croquants.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 4, 'Vérifiez la cuisson du poulet en piquant la partie la plus épaisse, près de l’os : le jus doit couler clair et la chair ne doit plus être rosée. Sinon, prolongez de 5 à 10 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 5, 'Servez le poulet bien doré avec les pommes de terre rôties et les haricots verts.') on conflict do nothing;
insert into public.recipe_photos (recipe_id, kind, source, author, license, url, rights, generated, alt) values ((select id from public.recipes where slug = 'gr-poulet-roti-pommes-de-terre-haricots-verts' and owner_id is null), 'generated', 'Toi & Moi', 'Illustration générée par programme pour l’application Toi & Moi', 'Création propre de l’application (aucune œuvre de tiers)', null, 'Utilisation libre dans l’application, y compris commerciale', true, 'Illustration générée de « Poulet rôti, pommes de terre et haricots verts » (ce n’est pas une photographie)') on conflict do nothing;
