insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-hachis-parmentier', 'Hachis parmentier bien gratiné', 'Une purée maison onctueuse sur une viande hachée bien cuite : le plat réconfortant qui met tout le monde d’accord.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 6, null, 25, 45, array['milk']::text[], array['protein','iron','classic','family','batch','freezer']::text[], array['Pour changer, remplacez une partie des pommes de terre par de la patate douce ou du potiron.','Restes de pot-au-feu ou de bœuf bouilli : hachez-les finement à la place de la viande crue.']::text[], 'Réfrigérateur : 2 jours, couvert ; réchauffez une seule fois au four, jusqu’à ce que le centre soit brûlant.', 'Se congèle très bien, en plat ou en parts, jusqu’à 3 mois ; décongelez une nuit au réfrigérateur puis réchauffez au four à 180 °C jusqu’à ce que le centre soit brûlant.', array['Grossesse : la viande hachée doit être cuite à cœur, sans aucune trace rosée, avant d’être mise au four.','Utilisez une planche et un couteau réservés à la viande crue, puis lavez-les à l’eau chaude savonneuse avant de toucher aux légumes.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).','Lait, crème et fromages au lait pasteurisé uniquement.']::text[], 'Viande, féculent et légumes réunis dans un plat familial : le bœuf apporte des protéines et du fer, les pommes de terre l’énergie du repas.', 2, array[]::text[], 'hot', '{"child":"Servez une part tiédie ; c’est souvent le plat préféré des enfants, tel quel."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-hachis-parmentier' and owner_id is null), 1, 'ground_beef', 'bœuf haché 5 % MG', 600, 'g', null, false) on conflict do nothing;
