insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-hachis-parmentier' and owner_id is null), 9, 'parsley', 'persil', 2, 'cs', 'ciselé', true) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-hachis-parmentier' and owner_id is null), 1, 'Épluchez les pommes de terre, coupez-les en morceaux et faites-les cuire 20 minutes dans une grande casserole d’eau bouillante, jusqu’à ce qu’elles soient bien tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-hachis-parmentier' and owner_id is null), 2, 'Pendant ce temps, épluchez et hachez finement les oignons et les carottes, puis faites-les revenir 5 minutes dans une sauteuse avec la moitié du beurre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-hachis-parmentier' and owner_id is null), 3, 'Ajoutez le bœuf haché et faites-le cuire 10 minutes à feu moyen en l’émiettant, jusqu’à ce qu’il soit entièrement cuit, sans aucune partie rosée. Ajoutez le persil lavé et ciselé.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-hachis-parmentier' and owner_id is null), 4, 'Préchauffez le four à 200 °C. Égouttez les pommes de terre et écrasez-les au presse-purée avec le lait chaud, le reste du beurre et la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-hachis-parmentier' and owner_id is null), 5, 'Étalez la viande dans un plat, couvrez de purée, parsemez d’emmental et enfournez 25 minutes, jusqu’à ce que le dessus soit bien doré et le centre brûlant.') on conflict do nothing;
