insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-saumon-pommes-de-terre-vapeur', 'Saumon bien cuit, pommes de terre vapeur et sauce ciboulette', 'Un pavé de saumon cuit au four, des pommes de terre vapeur et une sauce fraîche au fromage blanc : simple et plein de saveurs.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 15, 25, array['fish','milk']::text[], array['protein','classic','family']::text[], array['Remplacez le saumon par de la truite, cuite de la même façon.','Ajoutez des haricots verts ou des courgettes vapeur pour une assiette plus verte.']::text[], 'Réfrigérateur : 24 h pour le saumon cuit, dans une boîte fermée ; réchauffez-le une seule fois, bien chaud. Préparez la sauce au dernier moment.', 'Le saumon cuit se congèle jusqu’à 2 mois ; décongelez-le au réfrigérateur et réchauffez-le bien chaud. La sauce au fromage blanc et les pommes de terre vapeur ne se congèlent pas.', array['Grossesse : poisson frais uniquement, jamais cru, mariné ni fumé ; il doit être cuit à cœur, avec une chair opaque jusqu’au centre.','Passez les doigts sur la chair avant de servir et retirez la moindre arête.','Fromage blanc au lait pasteurisé, gardé au réfrigérateur jusqu’au service.','Repères poisson : deux fois par semaine, dont un poisson gras, en variant les espèces au fil des semaines.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Le saumon est un poisson gras, source d’oméga 3 ; avec les pommes de terre et la sauce au fromage blanc, le repas est complet.', 2, array[]::text[], 'hot', '{"child":"Émiettez le saumon en vérifiant l’absence d’arêtes et écrasez les pommes de terre avec un peu de sauce."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-saumon-pommes-de-terre-vapeur' and owner_id is null), 1, 'salmon', 'pavé de saumon frais', 4, 'u', '4 pavés d’environ 120 g, sans peau', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-saumon-pommes-de-terre-vapeur' and owner_id is null), 2, 'potato', 'pomme de terre', 800, 'g', 'à chair ferme', false) on conflict do nothing;
