insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-saumon-pommes-de-terre-vapeur' and owner_id is null), 6, 'olive_oil', 'huile d''olive', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-saumon-pommes-de-terre-vapeur' and owner_id is null), 1, 'Lavez les pommes de terre, coupez-les en deux et faites-les cuire 20 à 25 minutes à la vapeur, jusqu’à ce que la pointe d’un couteau s’y enfonce sans résistance.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-saumon-pommes-de-terre-vapeur' and owner_id is null), 2, 'Préchauffez le four à 180 °C. Posez les pavés de saumon dans un plat, arrosez-les d’huile d’olive et d’un filet de jus de citron, puis enfournez 15 à 18 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-saumon-pommes-de-terre-vapeur' and owner_id is null), 3, 'Vérifiez la cuisson : la chair du saumon doit être opaque jusqu’au centre et se détacher en lamelles à la fourchette. Sinon, prolongez de quelques minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-saumon-pommes-de-terre-vapeur' and owner_id is null), 4, 'Mélangez le fromage blanc avec la ciboulette lavée et ciselée et le reste du jus de citron.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-saumon-pommes-de-terre-vapeur' and owner_id is null), 5, 'Servez le saumon avec les pommes de terre vapeur et la sauce bien fraîche.') on conflict do nothing;
