insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-gratin-dauphinois', 'Gratin dauphinois fondant', 'Des pommes de terre cuites doucement dans le lait et la crème, dorées au four : l’accompagnement qui fait plaisir à toute la table.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 6, null, 20, 75, array['milk']::text[], array['vegetarian','calcium','classic','family']::text[], array['Servez-le avec un rôti, une volaille ou un poisson blanc, et une salade verte bien lavée.','Version plus légère : remplacez la crème par la même quantité de lait.']::text[], 'Réfrigérateur : 2 jours, couvert ; réchauffez une seule fois au four, jusqu’à ce que ce soit bien chaud au centre.', 'Se congèle, mais les pommes de terre deviennent un peu farineuses : jusqu’à 2 mois, en parts ; décongelez au réfrigérateur et réchauffez au four jusqu’à ce que ce soit bien chaud.', array['Lait, crème et fromages au lait pasteurisé uniquement. Servez le gratin bien chaud.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).','Restes : refroidis rapidement, couverts au réfrigérateur, puis réchauffés une seule fois jusqu’à être bien chauds à cœur (listériose).']::text[], 'Un accompagnement classique et réconfortant ; le lait et la crème apportent du calcium. À associer à une viande ou un poisson et à des légumes.', 2, array[]::text[], 'hot', '{"child":"Laissez tiédir et coupez en petits morceaux."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-gratin-dauphinois' and owner_id is null), 1, 'potato', 'pomme de terre', 1200, 'g', 'à chair ferme', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-gratin-dauphinois' and owner_id is null), 2, 'milk', 'lait demi-écrémé (pasteurisé ou UHT)', 500, 'ml', null, false) on conflict do nothing;
