insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-gratin-dauphinois' and owner_id is null), 6, 'butter', 'beurre', 10, 'g', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-gratin-dauphinois' and owner_id is null), 1, 'Préchauffez le four à 160 °C. Lavez et épluchez les pommes de terre, puis coupez-les en rondelles fines d’environ 3 mm, sans les rincer ensuite pour garder leur amidon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-gratin-dauphinois' and owner_id is null), 2, 'Frottez un plat à gratin avec la gousse d’ail coupée en deux, puis beurrez-le généreusement avec le beurre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-gratin-dauphinois' and owner_id is null), 3, 'Dans une grande casserole, portez à frémissement le lait avec la crème et la muscade. Ajoutez les rondelles de pommes de terre et laissez cuire 10 minutes à feu doux, en remuant délicatement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-gratin-dauphinois' and owner_id is null), 4, 'Versez le tout dans le plat et enfournez pour 1 heure, jusqu’à ce que le dessus soit bien doré et que la lame d’un couteau traverse les pommes de terre sans résistance.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-gratin-dauphinois' and owner_id is null), 5, 'Laissez reposer 10 minutes avant de servir.') on conflict do nothing;
