insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-soupe-legumes-maison', 'Soupe de légumes maison', 'La bonne soupe de légumes d’autrefois, douce et veloutée, qui réchauffe les soirs de semaine.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 6, null, 20, 30, array[]::text[], array['vegetarian','vegetables','fiber','budget','batch','freezer','classic','family']::text[], array['Changez les légumes selon la saison : potiron, navet ou céleri en hiver, haricots verts en été.','Pour un repas complet, servez avec du pain complet et un morceau de fromage à pâte dure au lait pasteurisé.']::text[], 'Réfrigérateur : 3 jours dans une bouteille ou une boîte fermée ; réchauffez seulement la quantité nécessaire, jusqu’à ébullition.', 'Se congèle très bien en portions, jusqu’à 3 mois ; décongelez une nuit au réfrigérateur ou directement à feu doux, puis portez à ébullition.', array['Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).','Restes : refroidis rapidement, couverts au réfrigérateur, puis réchauffés une seule fois jusqu’à être bien chauds à cœur (listériose).']::text[], 'Une soupe simple pour faire le plein de légumes et de fibres, à compléter avec du pain et un produit laitier.', 2, array[]::text[], 'hot', '{"baby":"Dès le début de la diversification : prélevez une louche avant de saler et mixez très finement."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-soupe-legumes-maison' and owner_id is null), 1, 'carrot', 'carotte', 3, 'u', null, false) on conflict do nothing;
