insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-soupe-legumes-maison' and owner_id is null), 6, 'olive_oil', 'huile d''olive', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-soupe-legumes-maison' and owner_id is null), 1, 'Lavez soigneusement tous les légumes. Épluchez les carottes, les pommes de terre et l’oignon ; fendez le poireau en deux et rincez-le entre les feuilles pour retirer la terre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-soupe-legumes-maison' and owner_id is null), 2, 'Coupez les carottes, le poireau, les pommes de terre, la courgette et l’oignon en morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-soupe-legumes-maison' and owner_id is null), 3, 'Dans une grande casserole, faites revenir l’oignon et le poireau 5 minutes dans l’huile d’olive, sans les colorer.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-soupe-legumes-maison' and owner_id is null), 4, 'Ajoutez le reste des légumes, couvrez d’eau à hauteur (environ 1,5 litre) et laissez cuire 25 minutes à frémissement, jusqu’à ce que tout soit très tendre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-soupe-legumes-maison' and owner_id is null), 5, 'Mixez finement et ajustez l’épaisseur avec un peu d’eau chaude si besoin. Salez légèrement au moment de servir.') on conflict do nothing;
