insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-lentilles-carottes', 'Lentilles vertes mijotées aux carottes', 'Un plat de ménage tout simple, fondant et parfumé au thym, qui cale bien et ne coûte presque rien.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 10, 35, array[]::text[], array['vegetarian','iron','fiber','b9','budget','batch','classic','family']::text[], array['Servez avec du riz ou du pain complet pour un repas végétarien complet.','Version non végétarienne : accompagnez d’une saucisse de volaille ou d’un morceau de poulet cuit à cœur.']::text[], 'Réfrigérateur : 3 jours dans une boîte fermée ; réchauffez une seule fois avec un peu d’eau, jusqu’à ce que ce soit bien chaud.', 'Se congèle très bien jusqu’à 3 mois ; décongelez une nuit au réfrigérateur et réchauffez à feu doux avec un peu d’eau.', array['Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).','Restes : refroidis rapidement, couverts au réfrigérateur, puis réchauffés une seule fois jusqu’à être bien chauds à cœur (listériose).']::text[], 'Les lentilles sont des légumineuses, sources de protéines végétales, de fibres et de folates (vitamine B9).', 2, array[]::text[], 'hot', '{"baby":"Vers 8 mois : mixez quelques cuillères de lentilles et de carottes avant d’ajouter l’huile et le sel."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
