insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-lentilles-carottes' and owner_id is null), 2, 'carrot', 'carotte', 3, 'u', null, false) on conflict do nothing;
