insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-lentilles-carottes' and owner_id is null), 7, 'parsley', 'persil', 1, 'cs', 'ciselé', true) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lentilles-carottes' and owner_id is null), 1, 'Rincez les lentilles vertes à l’eau froide. Lavez et épluchez les carottes et l’oignon, puis coupez les carottes en rondelles et l’oignon en petits dés.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lentilles-carottes' and owner_id is null), 2, 'Dans une cocotte, faites revenir l’oignon 3 minutes dans 1 cuillère à soupe d’huile d’olive.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lentilles-carottes' and owner_id is null), 3, 'Ajoutez les lentilles, les carottes, la feuille de laurier et le thym, puis couvrez de trois fois leur volume d’eau froide.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lentilles-carottes' and owner_id is null), 4, 'Portez à ébullition et laissez cuire 25 à 30 minutes à frémissement, jusqu’à ce que les lentilles soient tendres mais encore entières.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lentilles-carottes' and owner_id is null), 5, 'Égouttez si besoin, retirez le laurier, arrosez du reste d’huile d’olive et parsemez de persil lavé et ciselé.') on conflict do nothing;
