insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-omelette-courgette-poivron', 'Omelette bien cuite à la courgette et au poivron', 'Une omelette dorée et généreuse, garnie de légumes fondants, prête en moins de trente minutes.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 2, null, 10, 15, array['eggs']::text[], array['vegetarian','protein','quick','classic','family']::text[], array['Ajoutez quelques champignons ou des épinards selon ce que vous avez.','Servez avec une salade bien lavée et du pain complet.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; mangez-la froide ou réchauffée jusqu’à ce qu’elle soit bien chaude.', 'Ne se congèle pas : l’omelette devient caoutchouteuse et rend de l’eau. Préparez-la au moment du repas.', array['Grossesse : l’omelette doit être bien cuite et entièrement prise, sans partie baveuse.','Lavez-vous les mains après avoir cassé les œufs.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Les œufs apportent des protéines de qualité ; les légumes ajoutent couleur, fibres et vitamines.', 2, array[]::text[], 'hot', '{"child":"Coupez l’omelette en petits carrés faciles à attraper."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-omelette-courgette-poivron' and owner_id is null), 1, 'egg', 'œuf', 4, 'u', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-omelette-courgette-poivron' and owner_id is null), 2, 'zucchini', 'courgette', 1, 'u', null, false) on conflict do nothing;
