insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-omelette-courgette-poivron' and owner_id is null), 6, 'chives', 'ciboulette', 1, 'cs', 'ciselée', true) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-omelette-courgette-poivron' and owner_id is null), 1, 'Lavez la courgette, le poivron et la ciboulette. Coupez la courgette et le poivron en petits dés et émincez l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-omelette-courgette-poivron' and owner_id is null), 2, 'Faites revenir les légumes 8 minutes dans l’huile d’olive, à feu moyen, jusqu’à ce qu’ils soient tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-omelette-courgette-poivron' and owner_id is null), 3, 'Battez les œufs en omelette avec la ciboulette ciselée et versez-les sur les légumes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-omelette-courgette-poivron' and owner_id is null), 4, 'Laissez cuire 5 minutes à feu doux, couvercle posé, puis retournez l’omelette à l’aide d’une assiette et poursuivez 2 minutes : elle doit être entièrement prise, sans aucune partie baveuse.') on conflict do nothing;
