insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-pates-saumon-creme', 'Pâtes au saumon bien cuit et petits pois', 'Des pâtes crémeuses au saumon et aux petits pois, un plat du soir rapide que les enfants adorent aussi.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 10, 20, array['gluten','fish','milk']::text[], array['protein','quick','classic','family']::text[], array['Remplacez le saumon par de la truite ou du cabillaud, cuits de la même façon.','Ajoutez une poignée d’épinards en fin de cuisson.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud.', 'La sauce au saumon, sans les pâtes, se congèle jusqu’à 1 mois ; décongelez-la au réfrigérateur et réchauffez-la jusqu’à frémissement. Les pâtes se préparent au moment.', array['Grossesse : poisson frais uniquement, jamais cru, mariné ni fumé ; il doit être cuit à cœur, avec une chair opaque jusqu’au centre.','Jamais de saumon fumé pendant la grossesse : utilisez uniquement du saumon frais, bien cuit.','Lait, crème et fromages au lait pasteurisé uniquement.','Repères poisson : deux fois par semaine, dont un poisson gras, en variant les espèces au fil des semaines.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Pâtes, poisson gras et légumes dans une même assiette : un plat complet, à accompagner d’un fruit.', 2, array[]::text[], 'hot', '{"child":"Coupez les pâtes et émiettez le saumon pour les plus petits."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-pates-saumon-creme' and owner_id is null), 1, 'pasta', 'pâtes', 320, 'g', 'tagliatelles ou penne', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-pates-saumon-creme' and owner_id is null), 2, 'salmon', 'pavé de saumon frais', 2, 'u', '2 pavés d’environ 130 g, sans peau', false) on conflict do nothing;
