insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-pates-saumon-creme' and owner_id is null), 1, 'Faites cuire les pâtes dans une grande casserole d’eau bouillante selon le temps indiqué sur le paquet, en ajoutant les petits pois 5 minutes avant la fin.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-pates-saumon-creme' and owner_id is null), 2, 'Pendant ce temps, coupez le saumon en cubes de 2 cm et faites-le cuire 6 à 8 minutes dans une poêle antiadhésive, à feu moyen, en le retournant : il doit être opaque jusqu’au centre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-pates-saumon-creme' and owner_id is null), 3, 'Ajoutez la crème et le jus du citron, puis laissez frémir 2 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-pates-saumon-creme' and owner_id is null), 4, 'Égouttez les pâtes et les petits pois, mélangez-les à la sauce au saumon et parsemez de ciboulette lavée et ciselée.') on conflict do nothing;
