insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-quiche-poireaux', 'Quiche aux poireaux bien cuite', 'Une quiche dorée aux poireaux fondants, aussi bonne chaude que tiède avec une salade.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 6, null, 20, 45, array['gluten','eggs','milk']::text[], array['vegetarian','calcium','classic','family']::text[], array['Variez la garniture : courgettes, brocoli ou champignons bien revenus.','Servez avec une grande salade verte bien lavée.']::text[], 'Réfrigérateur : 2 jours, couverte ; réchauffez une seule fois jusqu’à ce qu’elle soit bien chaude au centre.', 'Se congèle cuite, entière ou en parts, jusqu’à 2 mois ; décongelez au réfrigérateur et réchauffez au four à 180 °C jusqu’à ce que le centre soit bien chaud.', array['Grossesse : la quiche doit être bien cuite, l’appareil aux œufs entièrement pris jusqu’au centre.','Lait, crème et fromages au lait pasteurisé uniquement.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Les œufs, le lait et le fromage apportent protéines et calcium ; les poireaux, des fibres.', 2, array[]::text[], 'hot', '{"child":"Coupez une part en bâtonnets tièdes, faciles à prendre avec les doigts."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
