insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-quiche-poireaux' and owner_id is null), 1, 'Préchauffez le four à 180 °C. Fendez les poireaux en deux, lavez-les soigneusement entre les feuilles, puis émincez-les finement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-quiche-poireaux' and owner_id is null), 2, 'Faites fondre les poireaux 10 minutes dans le beurre, à feu doux et à couvert, jusqu’à ce qu’ils soient tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-quiche-poireaux' and owner_id is null), 3, 'Étalez la pâte brisée dans un moule, piquez le fond à la fourchette et répartissez les poireaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-quiche-poireaux' and owner_id is null), 4, 'Battez les œufs avec la crème, le lait et la muscade, versez sur les poireaux et parsemez d’emmental.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-quiche-poireaux' and owner_id is null), 5, 'Enfournez 35 minutes : la quiche doit être dorée et l’appareil entièrement pris au centre (la lame d’un couteau ressort sèche). Sinon, prolongez de 5 minutes.') on conflict do nothing;
