insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-blanquette-veau', 'Blanquette de veau à l’ancienne et riz blanc', 'Le grand classique mijoté, avec sa sauce blanche onctueuse, ses carottes et ses champignons.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 6, null, 25, 110, array['gluten','milk']::text[], array['protein','classic','family','batch','freezer']::text[], array['Remplacez le veau par des hauts de cuisse de poulet : 45 minutes de mijotage suffisent.','Servez avec des pommes de terre vapeur à la place du riz.']::text[], 'Réfrigérateur : 2 jours pour la blanquette, dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud.', 'La blanquette, sans le riz, se congèle jusqu’à 3 mois ; décongelez-la une nuit au réfrigérateur et réchauffez-la doucement, en fouettant la sauce si elle a tranché.', array['Grossesse : la viande doit être cuite à cœur ; après 1 h 30 de mijotage, elle est très tendre et sans partie rosée.','Lait, crème et fromages au lait pasteurisé uniquement.','Riz cuit : refroidi en moins de 2 heures, gardé 24 h au réfrigérateur et réchauffé une seule fois, bien chaud.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Le veau apporte des protéines, le riz l’énergie du repas et les carottes et champignons des légumes : un plat complet.', 3, array[]::text[], 'hot', '{"child":"Effilochez la viande et mélangez-la au riz nappé de sauce."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
