insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-blanquette-veau' and owner_id is null), 11, 'rice', 'riz', 360, 'g', 'poids cru', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-blanquette-veau' and owner_id is null), 1, 'Mettez les morceaux de veau dans une cocotte, couvrez d’eau froide, portez à ébullition et retirez l’écume.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-blanquette-veau' and owner_id is null), 2, 'Ajoutez les carottes épluchées et coupées en tronçons, l’oignon épluché, le laurier et le thym. Laissez mijoter 1 h 30 à couvert, à feu doux, jusqu’à ce que la viande soit très tendre et cuite à cœur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-blanquette-veau' and owner_id is null), 3, 'Pendant ce temps, nettoyez les champignons, coupez-les en quartiers et faites-les cuire 10 minutes dans une petite casserole avec une louche du liquide de cuisson de la viande. Faites cuire le riz selon le temps indiqué sur le paquet.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-blanquette-veau' and owner_id is null), 4, 'Égouttez la viande et les carottes en gardant 60 cl de liquide de cuisson. Dans la cocotte, faites fondre le beurre, ajoutez la farine et remuez 2 minutes, puis versez le liquide en fouettant et laissez épaissir 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-blanquette-veau' and owner_id is null), 5, 'Hors du feu, ajoutez la crème et le jus du citron, puis remettez la viande, les carottes et les champignons. Réchauffez doucement 5 minutes sans faire bouillir et servez avec le riz.') on conflict do nothing;
