insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-chili-con-carne', 'Chili con carne doux et riz blanc', 'Un chili familial, généreux et doux en épices, qui mijote tout seul et se réchauffe encore mieux le lendemain.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 6, null, 15, 50, array[]::text[], array['protein','iron','fiber','family','batch','freezer']::text[], array['Version végétarienne : remplacez le bœuf par 200 g de lentilles vertes cuites et doublez le poivron.','Pour les grands amateurs d’épices, ajoutez du piment à table, dans l’assiette.']::text[], 'Réfrigérateur : 3 jours pour le chili, dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud.', 'Le chili, sans le riz, se congèle très bien jusqu’à 3 mois ; décongelez-le une nuit au réfrigérateur et réchauffez-le à feu doux jusqu’à frémissement.', array['Grossesse : la viande hachée doit être cuite à cœur, sans aucune trace rosée.','Utilisez une planche et un couteau réservés à la viande crue, puis lavez-les à l’eau chaude savonneuse avant de toucher aux légumes.','Riz cuit : refroidi en moins de 2 heures, gardé 24 h au réfrigérateur et réchauffé une seule fois, bien chaud.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Viande, légumineuses et légumes dans un même plat : un repas riche en protéines et en fibres, doux en épices pour toute la famille.', 2, array[]::text[], 'hot', '{"child":"Écrasez légèrement les haricots rouges à la fourchette pour les plus petits."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
