insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-chili-con-carne' and owner_id is null), 1, 'Épluchez et hachez les oignons et l’ail ; lavez le poivron et coupez-le en petits dés.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-chili-con-carne' and owner_id is null), 2, 'Dans une cocotte, faites revenir les oignons, l’ail et le poivron 5 minutes dans l’huile d’olive.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-chili-con-carne' and owner_id is null), 3, 'Ajoutez le bœuf haché et faites-le cuire 8 minutes en l’émiettant, jusqu’à ce qu’il ne reste aucune partie rosée. Ajoutez le cumin et le paprika.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-chili-con-carne' and owner_id is null), 4, 'Versez les tomates concassées et les haricots rouges rincés, mélangez et laissez mijoter 30 minutes à couvert, en remuant de temps en temps.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-chili-con-carne' and owner_id is null), 5, 'Pendant ce temps, faites cuire le riz selon le temps indiqué sur le paquet. Servez le chili bien chaud avec le riz.') on conflict do nothing;
