insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-curry-pois-chiches-epinards' and owner_id is null), 9, 'rice', 'riz', 280, 'g', 'poids cru', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-curry-pois-chiches-epinards' and owner_id is null), 1, 'Épluchez et émincez l’oignon et l’ail, puis faites-les revenir 5 minutes dans l’huile de colza, dans une sauteuse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-curry-pois-chiches-epinards' and owner_id is null), 2, 'Ajoutez le curry et remuez 1 minute, puis versez les tomates concassées, le lait de coco et les pois chiches rincés.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-curry-pois-chiches-epinards' and owner_id is null), 3, 'Ajoutez les épinards encore surgelés et laissez mijoter 15 minutes à feu doux, en remuant de temps en temps.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-curry-pois-chiches-epinards' and owner_id is null), 4, 'Pendant ce temps, faites cuire le riz selon le temps indiqué sur le paquet, puis servez avec le curry bien chaud.') on conflict do nothing;
