insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-riz-cantonais-poulet', 'Riz cantonais maison au poulet', 'Le riz sauté préféré des enfants, version maison avec du poulet, des œufs brouillés bien cuits et des petits légumes.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 15, 25, array['eggs']::text[], array['protein','quick','family']::text[], array['Remplacez le poulet par des dés de blanc de dinde cuits à cœur.','Ajoutez quelques gouttes de sauce soja réduite en sel à table, pour les adultes.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée, refroidi en moins de 2 heures ; réchauffez une seule fois, jusqu’à ce que ce soit brûlant.', 'Se congèle jusqu’à 1 mois, en portions ; décongelez au réfrigérateur et réchauffez à la poêle jusqu’à ce que ce soit brûlant. Ne recongelez pas.', array['Grossesse : œufs brouillés bien pris et secs, poulet cuit à cœur sans trace rosée.','Riz cuit : refroidi en moins de 2 heures, gardé 24 h au réfrigérateur et réchauffé une seule fois, bien chaud.','Utilisez une planche et un couteau réservés à la viande crue, puis lavez-les à l’eau chaude savonneuse avant de toucher aux légumes.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Féculent, volaille, œufs et légumes dans une même poêle : un plat complet et rapide.', 2, array[]::text[], 'hot', '{"child":"Servez dans un bol avec une cuillère ; c’est un plat que les enfants mangent facilement seuls."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-riz-cantonais-poulet' and owner_id is null), 1, 'rice', 'riz', 280, 'g', 'poids cru', false) on conflict do nothing;
