insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-riz-cantonais-poulet' and owner_id is null), 4, 'frozen_peas', 'petits pois surgelés', 150, 'g', null, false) on conflict do nothing;
