insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-riz-cantonais-poulet' and owner_id is null), 7, 'rapeseed_oil', 'huile de colza', 2, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-riz-cantonais-poulet' and owner_id is null), 1, 'Faites cuire le riz selon le temps indiqué sur le paquet, égouttez-le et étalez-le sur un plat pour qu’il refroidisse vite (ou utilisez du riz cuit la veille, gardé au réfrigérateur).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-riz-cantonais-poulet' and owner_id is null), 2, 'Coupez le poulet en petits dés ; épluchez la carotte et l’oignon et taillez-les en petits dés.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-riz-cantonais-poulet' and owner_id is null), 3, 'Battez les œufs et faites-les cuire 3 minutes dans une grande poêle avec un filet d’huile, en remuant, jusqu’à obtenir des œufs brouillés bien pris et secs. Réservez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-riz-cantonais-poulet' and owner_id is null), 4, 'Dans la même poêle, faites sauter le poulet, la carotte et l’oignon 8 minutes avec le reste d’huile, jusqu’à ce que le poulet soit cuit à cœur, sans partie rosée. Ajoutez les petits pois et poursuivez 3 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-riz-cantonais-poulet' and owner_id is null), 5, 'Ajoutez le riz et les œufs, puis faites sauter le tout 5 minutes à feu vif en remuant, jusqu’à ce que le riz soit bien chaud.') on conflict do nothing;
