insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-compote-pommes-cannelle', 'Compote de pommes maison à la cannelle', 'Une compote rustique, juste parfumée à la cannelle, sans sucre ajouté : la douceur vient des pommes.', array['pregnancy','family']::text[], array['dessert','snack']::text[], array[]::text[], null, null, array['mashed','smooth']::text[], 4, null, 15, 20, array[]::text[], array['vegetarian','compote','budget','batch','freezer','classic','family']::text[], array['Mélangez moitié pommes, moitié poires, ou ajoutez une poignée de fruits rouges en fin de cuisson.','Servez avec un yaourt nature pour un goûter complet.']::text[], 'Réfrigérateur : 4 jours dans un bocal propre et fermé.', 'Se congèle très bien en pots, jusqu’à 3 mois ; décongelez au réfrigérateur et consommez sous 48 heures.', array['Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Un dessert fruité sans sucre ajouté, source de fibres ; une bonne façon de terminer le repas.', 2, array[]::text[], 'cold', '{"baby":"Dès le début de la diversification : sans cannelle, mixée très finement."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-compote-pommes-cannelle' and owner_id is null), 1, 'apple', 'pomme', 1000, 'g', 'environ 6 pommes douces (golden, gala)', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-compote-pommes-cannelle' and owner_id is null), 2, 'cinnamon', 'cannelle', 1, 'pincee', null, true) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-compote-pommes-cannelle' and owner_id is null), 1, 'Lavez, épluchez et épépinez les pommes, puis coupez-les en morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-compote-pommes-cannelle' and owner_id is null), 2, 'Mettez-les dans une casserole avec 10 cl d’eau et la cannelle, couvrez et laissez cuire 15 à 20 minutes à feu doux, en remuant de temps en temps.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-compote-pommes-cannelle' and owner_id is null), 3, 'Écrasez à la fourchette pour une compote rustique, ou mixez pour une texture lisse. Servez tiède ou froide.') on conflict do nothing;
