insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-crumble-pommes', 'Crumble aux pommes tout doré', 'Des pommes fondantes sous une pâte sablée croustillante : le dessert de famille qui embaume la cuisine.', array['pregnancy','family']::text[], array['dessert']::text[], array[]::text[], null, null, array['regular']::text[], 6, null, 20, 35, array['gluten','milk']::text[], array['vegetarian','classic','family']::text[], array['Remplacez la moitié des pommes par des poires, des prunes ou des fruits rouges selon la saison.','Ajoutez 30 g de flocons d’avoine à la pâte pour plus de croquant.']::text[], 'Réfrigérateur : 2 jours, couvert ; réchauffez quelques minutes au four avant de servir.', 'Se congèle cru ou cuit, jusqu’à 3 mois ; faites cuire le crumble cru sans le décongeler (10 minutes de plus), ou réchauffez le crumble cuit au four à 160 °C.', array['Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).','Dessert sucré : à garder pour les jours de fête ou à partager en petite part.']::text[], 'Un dessert gourmand : les pommes apportent des fibres, la pâte du beurre et du sucre ; une petite part suffit.', 2, array[]::text[], 'hot', '{"child":"Une petite part tiède, sans ajout de sucre à table."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
