insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-crumble-pommes' and owner_id is null), 1, 'Préchauffez le four à 180 °C. Lavez, épluchez et épépinez les pommes, coupez-les en dés et répartissez-les dans un plat avec la cannelle.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-crumble-pommes' and owner_id is null), 2, 'Dans un saladier, mélangez la farine et le sucre, ajoutez le beurre froid coupé en dés et travaillez du bout des doigts jusqu’à obtenir un sable grossier.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-crumble-pommes' and owner_id is null), 3, 'Parsemez ce mélange sur les pommes, sans tasser.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-crumble-pommes' and owner_id is null), 4, 'Enfournez 35 minutes, jusqu’à ce que le dessus soit bien doré et les pommes fondantes. Servez tiède.') on conflict do nothing;
