insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-cabillaud-four-puree', 'Dos de cabillaud au four et purée maison', 'Un poisson blanc nacré, une purée onctueuse au beurre : le repas tout doux que l’on aime retrouver.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 20, 25, array['fish','milk']::text[], array['protein','classic','family']::text[], array['Le cabillaud peut être remplacé par du colin ou du merlu.','Ajoutez des carottes vapeur ou des épinards à la crème pour compléter l’assiette.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', 'Le poisson cuit se congèle jusqu’à 2 mois et la purée jusqu’à 1 mois ; décongelez au réfrigérateur et réchauffez jusqu’à ce que ce soit bien chaud.', array['Grossesse : poisson frais uniquement, jamais cru, mariné ni fumé ; il doit être cuit à cœur, avec une chair opaque jusqu’au centre.','Passez les doigts sur la chair avant de servir et retirez la moindre arête.','Lait, crème et fromages au lait pasteurisé uniquement.','Repères poisson : deux fois par semaine, dont un poisson gras, en variant les espèces au fil des semaines.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Le cabillaud est un poisson maigre, source de protéines et d’iode ; la purée apporte le féculent du repas.', 2, array[]::text[], 'hot', '{"baby":"Vers 6 à 8 mois : mixez 10 à 20 g de cabillaud sans arêtes avec un peu de purée, avant d’ajouter le sel."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-cabillaud-four-puree' and owner_id is null), 1, 'white_fish', 'filet de cabillaud ou de colin', 4, 'u', '4 dos de cabillaud d’environ 130 g', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-cabillaud-four-puree' and owner_id is null), 2, 'potato', 'pomme de terre', 1000, 'g', 'à chair farineuse', false) on conflict do nothing;
