insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-cabillaud-four-puree' and owner_id is null), 7, 'parsley', 'persil', 2, 'cs', 'ciselé', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-cabillaud-four-puree' and owner_id is null), 1, 'Épluchez les pommes de terre, coupez-les en morceaux et faites-les cuire 20 minutes dans une casserole d’eau bouillante.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-cabillaud-four-puree' and owner_id is null), 2, 'Préchauffez le four à 200 °C. Déposez les dos de cabillaud dans un plat, arrosez-les d’huile d’olive et du jus du citron, puis enfournez 12 à 15 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-cabillaud-four-puree' and owner_id is null), 3, 'Vérifiez la cuisson : la chair doit être opaque jusqu’au centre et s’effeuiller facilement. Retirez les éventuelles arêtes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-cabillaud-four-puree' and owner_id is null), 4, 'Égouttez les pommes de terre et écrasez-les avec le lait chaud et le beurre pour obtenir une purée bien lisse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-cabillaud-four-puree' and owner_id is null), 5, 'Servez le poisson parsemé de persil lavé et ciselé, avec la purée.') on conflict do nothing;
