insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-merlu-papillote-carottes', 'Merlu en papillote, carottes fondantes et riz', 'Un poisson tendre cuit dans son petit paquet, sur un lit de carottes, pour un dîner léger et sans odeur de cuisson.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 15, 25, array['fish']::text[], array['protein','vegetables','family']::text[], array['Remplacez les carottes par des courgettes ou des poireaux émincés.','Le merlu peut être remplacé par du cabillaud ou du colin.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud.', 'Le poisson cuit et les carottes se congèlent jusqu’à 2 mois, sans le riz ; décongelez au réfrigérateur et réchauffez jusqu’à ce que ce soit bien chaud.', array['Grossesse : poisson frais uniquement, jamais cru, mariné ni fumé ; il doit être cuit à cœur, avec une chair opaque jusqu’au centre.','Passez les doigts sur la chair avant de servir et retirez la moindre arête.','Riz cuit : refroidi en moins de 2 heures, gardé 24 h au réfrigérateur et réchauffé une seule fois, bien chaud.','Repères poisson : deux fois par semaine, dont un poisson gras, en variant les espèces au fil des semaines.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Le merlu, poisson maigre, apporte des protéines ; les carottes des légumes et le riz l’énergie du repas.', 2, array[]::text[], 'hot', '{"child":"Laissez l’enfant ouvrir sa papillote (une fois tiédie) et émiettez le poisson."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-merlu-papillote-carottes' and owner_id is null), 1, 'hake', 'filet de merlu', 4, 'u', '4 filets d’environ 130 g', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-merlu-papillote-carottes' and owner_id is null), 2, 'carrot', 'carotte', 4, 'u', null, false) on conflict do nothing;
