insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-merlu-papillote-carottes' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Épluchez les carottes, taillez-les en fines rondelles et faites-les cuire 10 minutes à la vapeur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-merlu-papillote-carottes' and owner_id is null), 2, 'Faites cuire le riz selon le temps indiqué sur le paquet.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-merlu-papillote-carottes' and owner_id is null), 3, 'Sur 4 feuilles de papier cuisson, répartissez les carottes, posez un filet de merlu, une rondelle de citron, un filet d’huile d’olive et un peu de thym. Fermez bien les papillotes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-merlu-papillote-carottes' and owner_id is null), 4, 'Enfournez 15 à 18 minutes. Ouvrez une papillote pour vérifier : la chair du merlu doit être opaque jusqu’au centre et se détacher facilement. Sinon, prolongez de quelques minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-merlu-papillote-carottes' and owner_id is null), 5, 'Servez les papillotes avec le riz, en retirant la rondelle de citron.') on conflict do nothing;
