insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-truite-fondue-poireaux', 'Truite à la fondue de poireaux, pommes de terre vapeur', 'Des filets de truite cuits doucement sur des poireaux fondants à la crème : un plat de poisson simple et raffiné.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 15, 30, array['fish','milk']::text[], array['protein','vegetables','family']::text[], array['Remplacez la truite par du saumon frais, cuit de la même façon.','Servez avec du riz à la place des pommes de terre.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud.', 'La fondue de poireaux se congèle jusqu’à 3 mois ; le poisson cuit jusqu’à 2 mois. Décongelez au réfrigérateur et réchauffez jusqu’à ce que ce soit bien chaud ; les pommes de terre vapeur ne se congèlent pas.', array['Grossesse : poisson frais uniquement, jamais cru, mariné ni fumé ; il doit être cuit à cœur, avec une chair opaque jusqu’au centre.','Passez les doigts sur la chair avant de servir et retirez la moindre arête.','Lait, crème et fromages au lait pasteurisé uniquement.','Repères poisson : deux fois par semaine, dont un poisson gras, en variant les espèces au fil des semaines.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'La truite apporte des protéines et des oméga 3, les poireaux des fibres et les pommes de terre le féculent du repas.', 2, array['autumn','winter','spring']::text[], 'hot', '{"child":"Retirez la peau, émiettez la truite et écrasez-la avec les pommes de terre et un peu de fondue."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
