insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-truite-fondue-poireaux' and owner_id is null), 1, 'Lavez soigneusement les poireaux entre les feuilles et émincez-les. Faites-les fondre 15 minutes à couvert dans le beurre, à feu doux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-truite-fondue-poireaux' and owner_id is null), 2, 'Pendant ce temps, épluchez les pommes de terre et faites-les cuire 20 minutes à la vapeur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-truite-fondue-poireaux' and owner_id is null), 3, 'Ajoutez la crème aux poireaux. Posez les filets de truite côté peau sur la fondue, couvrez et laissez cuire 8 à 10 minutes à feu doux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-truite-fondue-poireaux' and owner_id is null), 4, 'Vérifiez la cuisson : la chair de la truite doit être opaque jusqu’au centre et s’effeuiller facilement. Sinon, prolongez de quelques minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-truite-fondue-poireaux' and owner_id is null), 5, 'Servez avec les pommes de terre vapeur.') on conflict do nothing;
