insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-boeuf-carottes', 'Bœuf carottes mijoté comme chez mamie', 'Une viande fondante qui mijote longuement avec des carottes sucrées : le plat de famille par excellence.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 6, null, 20, 160, array['gluten']::text[], array['protein','iron','classic','family','batch','freezer']::text[], array['À l’autocuiseur : comptez environ 45 minutes après la mise en rotation de la soupape.','Ajoutez quelques champignons de Paris en fin de cuisson.']::text[], 'Réfrigérateur : 3 jours, dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', 'Se congèle très bien jusqu’à 3 mois ; décongelez une nuit au réfrigérateur et réchauffez doucement à couvert, jusqu’à frémissement.', array['Grossesse : après 2 h 30 de mijotage, la viande est cuite à cœur et fondante ; aucune partie ne doit rester rosée.','Utilisez une planche et un couteau réservés à la viande crue, puis lavez-les à l’eau chaude savonneuse avant de toucher aux légumes.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Le bœuf apporte des protéines et du fer, les carottes des fibres ; servez avec un féculent pour un repas complet.', 2, array['autumn','winter']::text[], 'hot', '{"child":"Effilochez la viande et écrasez les carottes avec un peu de sauce."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
