insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-boeuf-carottes' and owner_id is null), 10, 'parsley', 'persil', 1, 'cs', 'ciselé', true) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-boeuf-carottes' and owner_id is null), 1, 'Coupez le bœuf en gros cubes. Épluchez les oignons et l’ail et émincez-les ; épluchez les carottes et coupez-les en rondelles épaisses.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-boeuf-carottes' and owner_id is null), 2, 'Dans une cocotte, faites dorer la viande 10 minutes dans l’huile d’olive, sur toutes les faces, puis ajoutez les oignons et l’ail et laissez revenir 3 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-boeuf-carottes' and owner_id is null), 3, 'Saupoudrez de farine, mélangez, puis ajoutez le concentré de tomate, le laurier, le thym et 1 litre d’eau.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-boeuf-carottes' and owner_id is null), 4, 'Couvrez et laissez mijoter 1 h 30 à feu doux. Ajoutez les carottes et poursuivez 1 heure, jusqu’à ce que la viande soit fondante et cuite à cœur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-boeuf-carottes' and owner_id is null), 5, 'Retirez le laurier, parsemez de persil lavé et ciselé et servez bien chaud, avec des pommes de terre vapeur ou des pâtes.') on conflict do nothing;
