insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-poulet-basquaise', 'Poulet basquaise et riz', 'Des cuisses de poulet mijotées avec poivrons et tomates : un plat ensoleillé, coloré et très parfumé.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 20, 50, array[]::text[], array['protein','vegetables','classic','family','freezer']::text[], array['Hors saison, remplacez les tomates fraîches par 400 g de tomates concassées en conserve.','Servez avec des pommes de terre vapeur à la place du riz.']::text[], 'Réfrigérateur : 2 jours, dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', 'Le poulet et sa sauce, sans le riz, se congèlent jusqu’à 3 mois ; décongelez une nuit au réfrigérateur et réchauffez à couvert jusqu’à frémissement.', array['Grossesse : le poulet doit être cuit à cœur, sans trace rosée près de l’os.','Utilisez une planche et un couteau réservés à la viande crue, puis lavez-les à l’eau chaude savonneuse avant de toucher aux légumes.','Riz cuit : refroidi en moins de 2 heures, gardé 24 h au réfrigérateur et réchauffé une seule fois, bien chaud.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Volaille, légumes du soleil et riz : un plat complet, riche en légumes.', 2, array['summer','autumn']::text[], 'hot', '{"child":"Retirez la peau, effilochez la viande et mélangez-la au riz avec la sauce."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-poulet-basquaise' and owner_id is null), 1, 'chicken_thigh', 'cuisses de poulet', 4, 'u', 'environ 1 kg', false) on conflict do nothing;
