insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-basquaise' and owner_id is null), 1, 'Lavez les poivrons et les tomates. Épépinez les poivrons et coupez-les en lanières, coupez les tomates en morceaux, émincez les oignons et l’ail.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-basquaise' and owner_id is null), 2, 'Dans une cocotte, faites dorer les cuisses de poulet 10 minutes dans l’huile d’olive, sur toutes les faces, puis réservez-les.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-basquaise' and owner_id is null), 3, 'Faites revenir les oignons, l’ail et les poivrons 10 minutes dans la même cocotte, puis ajoutez les tomates et le paprika.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-basquaise' and owner_id is null), 4, 'Remettez le poulet, couvrez et laissez mijoter 30 minutes à feu doux. Vérifiez que la chair près de l’os est cuite à cœur, sans trace rosée.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-poulet-basquaise' and owner_id is null), 5, 'Pendant ce temps, faites cuire le riz selon le temps indiqué sur le paquet et servez-le avec le poulet et sa sauce.') on conflict do nothing;
