insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-lasagnes-bolognaise', 'Lasagnes à la bolognaise maison', 'Des couches de sauce tomate à la viande et de béchamel, gratinées au four : le plat que l’on partage en famille.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 6, null, 30, 75, array['gluten','eggs','milk']::text[], array['protein','calcium','classic','family','batch','freezer']::text[], array['Version végétarienne : remplacez la viande par des lentilles vertes cuites et des dés de courgette.','Préparez la sauce la veille : les lasagnes se montent ensuite en 10 minutes.']::text[], 'Réfrigérateur : 3 jours, couvertes ; réchauffez une seule fois au four, jusqu’à ce que le centre soit brûlant.', 'Se congèlent très bien, cuites, en plat ou en parts, jusqu’à 3 mois ; décongelez une nuit au réfrigérateur et réchauffez au four à 180 °C jusqu’à ce que le centre soit brûlant.', array['Grossesse : la viande hachée doit être cuite à cœur, sans aucune trace rosée.','Lait, crème et fromages au lait pasteurisé uniquement.','Utilisez une planche et un couteau réservés à la viande crue, puis lavez-les à l’eau chaude savonneuse avant de toucher aux légumes.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).']::text[], 'Un plat complet : pâtes, viande, légumes de la sauce et produits laitiers de la béchamel.', 2, array[]::text[], 'hot', '{"child":"Coupez une part en petits morceaux et laissez bien tiédir."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
