insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lasagnes-bolognaise' and owner_id is null), 1, 'Épluchez et hachez finement l’oignon et la carotte, puis faites-les revenir 5 minutes dans l’huile d’olive, dans une sauteuse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lasagnes-bolognaise' and owner_id is null), 2, 'Ajoutez le bœuf haché et faites-le cuire 8 minutes en l’émiettant, jusqu’à ce qu’il ne reste aucune partie rosée. Versez les tomates concassées et laissez mijoter 20 minutes à feu doux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lasagnes-bolognaise' and owner_id is null), 3, 'Préparez la béchamel : faites fondre le beurre dans une casserole, ajoutez la farine et remuez 1 minute, puis versez le lait petit à petit en fouettant. Laissez épaissir 5 minutes à feu doux et ajoutez la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lasagnes-bolognaise' and owner_id is null), 4, 'Préchauffez le four à 180 °C. Dans un plat, alternez sauce bolognaise, feuilles de lasagnes et béchamel, en terminant par la béchamel. Parsemez d’emmental.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-lasagnes-bolognaise' and owner_id is null), 5, 'Enfournez 35 minutes, jusqu’à ce que le dessus soit doré et que les lasagnes soient tendres sous la pointe d’un couteau.') on conflict do nothing;
