insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-veloute-potiron', 'Velouté de potiron à la muscade', 'Un velouté orange tout doux, onctueux et légèrement muscadé, pour les soirées d’automne.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 15, 25, array['milk']::text[], array['vegetarian','vegetables','budget','batch','freezer','classic','family']::text[], array['Le potiron peut être remplacé par du potimarron (inutile de l’éplucher) ou de la courge butternut.','Servez avec des croûtons de pain et un peu d’emmental râpé.']::text[], 'Réfrigérateur : 3 jours dans une boîte fermée ; réchauffez seulement la quantité nécessaire, jusqu’à ébullition.', 'Se congèle très bien jusqu’à 3 mois, de préférence sans la crème ; décongelez au réfrigérateur et portez à ébullition, puis ajoutez la crème.', array['Lait, crème et fromages au lait pasteurisé uniquement.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).','Restes : refroidis rapidement, couverts au réfrigérateur, puis réchauffés une seule fois jusqu’à être bien chauds à cœur (listériose).']::text[], 'Le potiron apporte des fibres et du bêta-carotène ; complétez avec du pain et un produit laitier.', 1, array['autumn','winter']::text[], 'hot', '{"baby":"Prélevez une portion avant d’ajouter la crème et la muscade, mixée très finement et sans sel."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
