insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-veloute-potiron' and owner_id is null), 1, 'Lavez le potiron, retirez les graines et la peau, puis coupez la chair en cubes. Épluchez la pomme de terre et l’oignon et coupez-les en morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-veloute-potiron' and owner_id is null), 2, 'Faites revenir l’oignon 3 minutes dans l’huile d’olive, dans une grande casserole.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-veloute-potiron' and owner_id is null), 3, 'Ajoutez le potiron et la pomme de terre, couvrez d’eau à hauteur et laissez cuire 20 minutes, jusqu’à ce que tout soit très tendre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-veloute-potiron' and owner_id is null), 4, 'Mixez finement avec la muscade et la crème, en ajoutant un peu d’eau chaude si le velouté est trop épais.') on conflict do nothing;
