insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-gratin-chou-fleur', 'Gratin de chou-fleur à la béchamel', 'Des bouquets de chou-fleur nappés d’une béchamel onctueuse et gratinés : même les moins fans de légumes se resservent.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 15, 35, array['gluten','milk']::text[], array['vegetarian','calcium','vegetables','classic','family']::text[], array['Mélangez chou-fleur et brocoli pour un gratin bicolore.','Servez avec une tranche de jambon ou un œuf dur bien cuit pour un repas complet.']::text[], 'Réfrigérateur : 2 jours, couvert ; réchauffez une seule fois au four, jusqu’à ce que ce soit bien chaud.', 'Se congèle moyennement (le chou-fleur rend un peu d’eau) : jusqu’à 2 mois ; décongelez au réfrigérateur et réchauffez au four jusqu’à ce que ce soit bien chaud.', array['Lait, crème et fromages au lait pasteurisé uniquement.','Lavez soigneusement les légumes, les fruits et les herbes aromatiques, puis lavez-vous les mains après les avoir épluchés (toxoplasmose).','Restes : refroidis rapidement, couverts au réfrigérateur, puis réchauffés une seule fois jusqu’à être bien chauds à cœur (listériose).']::text[], 'Le chou-fleur apporte des fibres et de la vitamine C, la béchamel et le fromage du calcium.', 1, array['autumn','winter','spring']::text[], 'hot', '{"child":"Écrasez les bouquets avec la sauce pour les plus petits."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
