insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-gratin-chou-fleur' and owner_id is null), 1, 'Lavez le chou-fleur, détaillez-le en bouquets et faites-le cuire 10 minutes à la vapeur : il doit rester légèrement ferme.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-gratin-chou-fleur' and owner_id is null), 2, 'Préparez la béchamel : faites fondre le beurre, ajoutez la farine et remuez 1 minute, puis versez le lait en fouettant et laissez épaissir 5 minutes à feu doux. Ajoutez la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-gratin-chou-fleur' and owner_id is null), 3, 'Préchauffez le four à 200 °C. Répartissez le chou-fleur dans un plat, nappez de béchamel et parsemez d’emmental.') on conflict do nothing;
