insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-dinde-creme-champignons', 'Escalopes de dinde à la crème et aux champignons', 'Des escalopes dorées dans une sauce crémeuse aux champignons, servies avec du riz : un classique rapide de semaine.', array['pregnancy','family']::text[], array['lunch','dinner']::text[], array[]::text[], null, null, array['regular']::text[], 4, null, 15, 25, array['milk']::text[], array['protein','quick','classic','family']::text[], array['Remplacez la dinde par des escalopes de poulet ou de veau.','Servez avec des pâtes fraîches ou des haricots verts.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud.', 'La dinde en sauce, sans le riz, se congèle jusqu’à 2 mois ; décongelez une nuit au réfrigérateur et réchauffez à feu doux jusqu’à frémissement.', array['Grossesse : les escalopes doivent être cuites à cœur, sans partie rosée au centre.','Lait, crème et fromages au lait pasteurisé uniquement.','Utilisez une planche et un couteau réservés à la viande crue, puis lavez-les à l’eau chaude savonneuse avant de toucher aux légumes.','Riz cuit : refroidi en moins de 2 heures, gardé 24 h au réfrigérateur et réchauffé une seule fois, bien chaud.']::text[], 'La dinde est une viande maigre riche en protéines ; avec le riz et les champignons, le repas est complet.', 2, array[]::text[], 'hot', '{"child":"Coupez la dinde en lamelles fines et mélangez-la au riz avec la sauce."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
