insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-dinde-creme-champignons' and owner_id is null), 1, 'Faites cuire le riz selon le temps indiqué sur le paquet.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-dinde-creme-champignons' and owner_id is null), 2, 'Nettoyez les champignons et émincez-les ; épluchez et hachez l’échalote.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-dinde-creme-champignons' and owner_id is null), 3, 'Faites dorer les escalopes de dinde 4 à 5 minutes de chaque côté dans le beurre, jusqu’à ce qu’elles soient cuites à cœur, sans partie rosée au centre. Réservez-les au chaud.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-dinde-creme-champignons' and owner_id is null), 4, 'Dans la même poêle, faites revenir l’échalote et les champignons 8 minutes, puis ajoutez la crème et laissez frémir 2 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-dinde-creme-champignons' and owner_id is null), 5, 'Remettez les escalopes dans la sauce 1 minute pour les réchauffer, parsemez de persil lavé et ciselé et servez avec le riz.') on conflict do nothing;
