insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gr-riz-au-lait-vanille', 'Riz au lait à la vanille', 'Le dessert de grand-mère, crémeux et vanillé, à déguster bien frais.', array['pregnancy','family']::text[], array['dessert','snack']::text[], array[]::text[], null, null, array['mashed']::text[], 6, null, 5, 40, array['milk']::text[], array['vegetarian','calcium','budget','classic','family']::text[], array['Servez avec une compote de fruits ou quelques fruits rouges.','Réduisez le sucre à 50 g : la vanille apporte déjà beaucoup de douceur.']::text[], 'Réfrigérateur : 2 jours, en ramequins couverts.', 'Ne se congèle pas : le riz durcit et la texture devient granuleuse. Conservez-le au réfrigérateur.', array['Grossesse : lait pasteurisé ou UHT uniquement ; refroidissez rapidement avant de mettre au réfrigérateur.','Dessert sucré : une petite portion suffit.']::text[], 'Un dessert lacté source de calcium, à servir en petite portion car il est sucré.', 1, array[]::text[], 'cold', '{"child":"Une petite portion, éventuellement avec moins de sucre."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-riz-au-lait-vanille' and owner_id is null), 1, 'round_rice', 'riz rond', 120, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-riz-au-lait-vanille' and owner_id is null), 2, 'milk', 'lait demi-écrémé (pasteurisé ou UHT)', 1000, 'ml', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-riz-au-lait-vanille' and owner_id is null), 3, 'sugar', 'sucre', 70, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gr-riz-au-lait-vanille' and owner_id is null), 4, 'vanilla', 'extrait de vanille', 1, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-riz-au-lait-vanille' and owner_id is null), 1, 'Rincez le riz rond, puis faites-le blanchir 2 minutes dans une casserole d’eau bouillante. Égouttez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-riz-au-lait-vanille' and owner_id is null), 2, 'Portez le lait à frémissement avec la vanille, ajoutez le riz et laissez cuire 35 minutes à feu très doux, en remuant souvent, jusqu’à ce que le riz soit fondant et crémeux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gr-riz-au-lait-vanille' and owner_id is null), 3, 'Ajoutez le sucre hors du feu, mélangez, puis répartissez dans des ramequins. Laissez refroidir avant de placer au réfrigérateur.') on conflict do nothing;
