insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-puree-courgette', 'Purée de courgette toute douce', 'Une première purée verte, fondante et délicate, idéale pour découvrir les légumes.', array['baby']::text[], array['lunch','dinner']::text[], array['start','m6_8']::text[], 4, 8, array['smooth']::text[], 4, 'portions bébé', 10, 12, array[]::text[], array['puree','vegetables','budget','batch','freezer']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.','Plus tard, laissez la peau d’une courgette bien lavée : elle apporte des fibres.']::text[], 'Réfrigérateur : 48 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, et jetez les restes de l’assiette.', 'Se congèle très bien en bacs à glaçons ou en petits pots : jusqu’à 1 mois. Décongelez au réfrigérateur la veille ou directement à feu doux en remuant ; ne recongelez jamais une purée décongelée.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.','Vérifiez la température avant de servir : la purée doit être tiède, jamais brûlante.']::text[], 'La courgette, douce et riche en eau, est un légume facile pour découvrir les premières saveurs.', 1, array['spring','summer','autumn']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-courgette' and owner_id is null), 1, 'zucchini', 'courgette', 300, 'g', 'environ 1 grosse courgette', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-courgette' and owner_id is null), 2, 'rapeseed_oil', 'huile de colza', 2, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-courgette' and owner_id is null), 1, 'Lavez la courgette, épluchez-la (la peau est parfois amère au début) et coupez-la en rondelles.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-courgette' and owner_id is null), 2, 'Faites-la cuire 12 minutes à la vapeur, jusqu’à ce qu’elle soit très tendre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-courgette' and owner_id is null), 3, 'Mixez très finement pour obtenir une purée bien lisse, selon ce que votre bébé accepte ; la courgette rend beaucoup d’eau, inutile d’en ajouter.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-courgette' and owner_id is null), 4, 'Au moment de servir, ajoutez une demi-cuillère à café d’huile de colza par portion.') on conflict do nothing;
insert into public.recipe_photos (recipe_id, kind, source, author, license, url, rights, generated, alt) values ((select id from public.recipes where slug = 'dd-puree-courgette' and owner_id is null), 'generated', 'Toi & Moi', 'Illustration générée par programme pour l’application Toi & Moi', 'Création propre de l’application (aucune œuvre de tiers)', null, 'Utilisation libre dans l’application, y compris commerciale', true, 'Illustration générée de « Purée de courgette toute douce » (ce n’est pas une photographie)') on conflict do nothing;
