insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-puree-haricots-verts', 'Purée de haricots verts bien lisse', 'Le grand classique des premières purées vertes, mixé finement et passé au tamis pour une texture toute douce.', array['baby']::text[], array['lunch','dinner']::text[], array['start','m6_8']::text[], 4, 8, array['smooth']::text[], 4, 'portions bébé', 10, 15, array[]::text[], array['puree','vegetables','budget','batch','freezer']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.','Si la purée paraît trop fibreuse, ajoutez une petite pomme de terre cuite avec les haricots.']::text[], 'Réfrigérateur : 48 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, et jetez les restes de l’assiette.', 'Se congèle très bien en bacs à glaçons ou en petits pots : jusqu’à 1 mois. Décongelez au réfrigérateur la veille ou directement à feu doux en remuant ; ne recongelez jamais une purée décongelée.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.','Vérifiez la température avant de servir : la purée doit être tiède, jamais brûlante.']::text[], 'Les haricots verts apportent des fibres et une saveur douce que les bébés acceptent facilement.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-haricots-verts' and owner_id is null), 1, 'green_beans', 'haricots verts', 300, 'g', 'frais ou surgelés, extra-fins', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-haricots-verts' and owner_id is null), 2, 'rapeseed_oil', 'huile de colza', 2, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-haricots-verts' and owner_id is null), 1, 'Équeutez et lavez les haricots verts (inutile si vous utilisez des surgelés).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-haricots-verts' and owner_id is null), 2, 'Faites-les cuire 15 minutes à la vapeur, jusqu’à ce qu’ils s’écrasent très facilement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-haricots-verts' and owner_id is null), 3, 'Mixez très longuement avec un peu d’eau de cuisson, puis passez au tamis pour retirer les fibres et obtenir une purée bien lisse.') on conflict do nothing;
