insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-puree-panais', 'Purée de panais veloutée', 'Un légume d’hiver à la saveur douce et légèrement sucrée, pour varier les découvertes.', array['baby']::text[], array['lunch','dinner']::text[], array['start','m6_8']::text[], 4, 8, array['smooth']::text[], 4, 'portions bébé', 10, 15, array[]::text[], array['puree','vegetables','budget','batch','freezer']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.','Mélangez-le avec de la carotte ou de la pomme de terre pour une saveur encore plus douce.']::text[], 'Réfrigérateur : 48 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, et jetez les restes de l’assiette.', 'Se congèle très bien en bacs à glaçons ou en petits pots : jusqu’à 1 mois. Décongelez au réfrigérateur la veille ou directement à feu doux en remuant ; ne recongelez jamais une purée décongelée.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.','Vérifiez la température avant de servir : la purée doit être tiède, jamais brûlante.']::text[], 'Le panais est une racine douce, source de fibres, qui fait découvrir un nouveau goût.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-panais' and owner_id is null), 1, 'parsnip', 'panais', 300, 'g', 'environ 2 panais', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-panais' and owner_id is null), 2, 'rapeseed_oil', 'huile de colza', 2, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-panais' and owner_id is null), 1, 'Lavez et épluchez les panais, retirez le cœur s’il est dur, puis coupez-les en rondelles.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-panais' and owner_id is null), 2, 'Faites cuire 15 minutes à la vapeur, jusqu’à ce qu’ils s’écrasent très facilement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-panais' and owner_id is null), 3, 'Mixez très finement avec un peu d’eau de cuisson pour obtenir une purée bien lisse.') on conflict do nothing;
