insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-puree-carotte', 'Purée de carotte fondante', 'Une purée orange vif, douce et sucrée, que presque tous les bébés adorent.', array['baby']::text[], array['lunch','dinner']::text[], array['start','m6_8']::text[], 4, 8, array['smooth']::text[], 4, 'portions bébé', 10, 20, array[]::text[], array['puree','vegetables','budget','batch','freezer']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.','Avec un peu de cumin plus tard, elle fera découvrir une nouvelle saveur.']::text[], 'Réfrigérateur : 48 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, et jetez les restes de l’assiette.', 'Se congèle très bien en bacs à glaçons ou en petits pots : jusqu’à 1 mois. Décongelez au réfrigérateur la veille ou directement à feu doux en remuant ; ne recongelez jamais une purée décongelée.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.','Vérifiez la température avant de servir : la purée doit être tiède, jamais brûlante.','Carottes crues : jamais en morceaux avant 4 ans ; ici, elles sont cuites et mixées.']::text[], 'La carotte, douce et sucrée, apporte des fibres et du bêta-carotène.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
