insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-brocoli-pomme-de-terre' and owner_id is null), 2, 'potato', 'pomme de terre', 150, 'g', '1 pomme de terre moyenne', false) on conflict do nothing;
