insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-brocoli-pomme-de-terre' and owner_id is null), 2, 'Faites cuire la pomme de terre 8 minutes à la vapeur, ajoutez le brocoli et poursuivez 10 minutes.') on conflict do nothing;
