insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-puree-butternut-carotte', 'Purée de butternut et carotte', 'Une purée orange, douce et légèrement sucrée, qui sent bon l’automne.', array['baby']::text[], array['lunch','dinner']::text[], array['start','m6_8']::text[], 4, 8, array['smooth']::text[], 4, 'portions bébé', 10, 18, array[]::text[], array['puree','vegetables','budget','batch','freezer']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.']::text[], 'Réfrigérateur : 48 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, et jetez les restes de l’assiette.', 'Se congèle très bien en bacs à glaçons ou en petits pots : jusqu’à 1 mois. Décongelez au réfrigérateur la veille ou directement à feu doux en remuant ; ne recongelez jamais une purée décongelée.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.','Vérifiez la température avant de servir : la purée doit être tiède, jamais brûlante.']::text[], 'Courge et carotte apportent des fibres et du bêta-carotène, dans une saveur douce que les bébés apprécient.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-butternut-carotte' and owner_id is null), 1, 'butternut', 'courge butternut', 200, 'g', 'chair sans peau ni graines', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-butternut-carotte' and owner_id is null), 2, 'carrot', 'carotte', 100, 'g', '1 carotte', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-puree-butternut-carotte' and owner_id is null), 3, 'rapeseed_oil', 'huile de colza', 2, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-butternut-carotte' and owner_id is null), 1, 'Épluchez la courge butternut, retirez les graines et coupez la chair en cubes ; lavez, épluchez et coupez la carotte en rondelles.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-butternut-carotte' and owner_id is null), 2, 'Faites cuire les légumes 18 minutes à la vapeur, jusqu’à ce qu’ils s’écrasent très facilement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-puree-butternut-carotte' and owner_id is null), 3, 'Mixez très finement pour obtenir une purée bien lisse, selon ce que votre bébé accepte.') on conflict do nothing;
