insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-avocat-ecrase', 'Avocat écrasé tout doux', 'Une purée crémeuse prête en deux minutes, sans cuisson, avec un avocat bien mûr.', array['baby']::text[], array['lunch','snack']::text[], array['start','m6_8']::text[], 4, 8, array['smooth']::text[], 2, 'portions bébé', 5, 0, array[]::text[], array['puree','quick']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.','Mélangez-le à une cuillère de purée de courgette ou de banane écrasée pour varier.']::text[], 'À préparer au dernier moment ; ne conservez pas les restes de la portion entamée. La moitié non utilisée, avec son noyau et filmée, se garde 24 h au réfrigérateur.', 'Ne se congèle pas : l’avocat noircit et devient aqueux. Préparez-le juste avant le repas.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.','Bébé mange assis bien droit, toujours sous la surveillance d’un adulte.']::text[], 'L’avocat apporte des matières grasses de bonne qualité, dans une texture naturellement onctueuse.', 2, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
