insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-avocat-ecrase' and owner_id is null), 1, 'Lavez l’avocat, coupez-le en deux, retirez le noyau et prélevez la chair à la cuillère.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-avocat-ecrase' and owner_id is null), 2, 'Écrasez-la finement à la fourchette ou mixez-la pour une texture parfaitement lisse, selon ce que votre bébé accepte.') on conflict do nothing;
