insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-compote-pomme', 'Compote de pomme toute lisse', 'La première compote, douce et parfumée, sans aucun sucre ajouté.', array['baby']::text[], array['dessert','snack']::text[], array['start','m6_8','m9_12']::text[], 4, 12, array['smooth']::text[], 4, 'portions bébé', 10, 15, array[]::text[], array['compote','batch','freezer','budget']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.','Choisissez des variétés douces : les pommes acidulées font parfois grimacer les bébés.']::text[], 'Réfrigérateur : 48 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, et jetez les restes de l’assiette.', 'Se congèle très bien en bacs à glaçons ou en petits pots : jusqu’à 1 mois. Décongelez au réfrigérateur la veille et consommez dans les 24 heures ; ne recongelez jamais une compote décongelée.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Pas de miel avant 1 an, même pour adoucir.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.']::text[], 'La pomme cuite est douce et facile à digérer ; une première découverte des fruits.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-compote-pomme' and owner_id is null), 1, 'apple', 'pomme', 400, 'g', 'environ 3 pommes douces (golden, gala)', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-pomme' and owner_id is null), 1, 'Lavez, épluchez et épépinez les pommes, puis coupez-les en morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-pomme' and owner_id is null), 2, 'Faites-les cuire 15 minutes à la vapeur ou à couvert avec 2 cuillères à soupe d’eau, jusqu’à ce qu’elles soient très tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-pomme' and owner_id is null), 3, 'Mixez finement pour obtenir une compote bien lisse, sans ajouter de sucre.') on conflict do nothing;
