insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-compote-pomme-banane', 'Compote pomme et banane', 'Une compote onctueuse et naturellement sucrée, où la banane mûre adoucit la pomme cuite.', array['baby']::text[], array['dessert','snack']::text[], array['start','m6_8','m9_12']::text[], 4, 12, array['smooth']::text[], 4, 'portions bébé', 10, 15, array[]::text[], array['compote','batch','freezer','budget']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.','Plus tard, écrasez simplement la banane à la fourchette dans la compote de pomme.']::text[], 'Réfrigérateur : 48 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, et jetez les restes de l’assiette.', 'Se congèle très bien en bacs à glaçons ou en petits pots : jusqu’à 1 mois. Décongelez au réfrigérateur la veille et consommez dans les 24 heures ; ne recongelez jamais une compote décongelée.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Pas de miel avant 1 an, même pour adoucir.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.']::text[], 'La banane apporte une texture crémeuse et de l’énergie ; la pomme cuite, sa douceur.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
