insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-pomme-banane' and owner_id is null), 2, 'Faites-les cuire 15 minutes à la vapeur ou à couvert avec 2 cuillères à soupe d’eau, jusqu’à ce qu’elles soient très tendres.') on conflict do nothing;
