insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-compote-peche', 'Compote de pêche d’été', 'Une compote parfumée comme un été au verger, avec des pêches bien mûres.', array['baby']::text[], array['dessert','snack']::text[], array['start','m6_8','m9_12']::text[], 4, 12, array['smooth']::text[], 4, 'portions bébé', 10, 12, array[]::text[], array['compote','batch','freezer','budget']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.','Mélangez-la à une compote de pomme si votre bébé la trouve trop parfumée.']::text[], 'Réfrigérateur : 48 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, et jetez les restes de l’assiette.', 'Se congèle très bien en bacs à glaçons ou en petits pots : jusqu’à 1 mois. Décongelez au réfrigérateur la veille et consommez dans les 24 heures ; ne recongelez jamais une compote décongelée.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Pas de miel avant 1 an, même pour adoucir.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.']::text[], 'La pêche est un fruit d’été juteux et parfumé, source de vitamine C.', 1, array['summer']::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-compote-peche' and owner_id is null), 1, 'peach', 'pêche', 400, 'g', '3 à 4 pêches bien mûres', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-peche' and owner_id is null), 1, 'Plongez les pêches 30 secondes dans l’eau bouillante, puis dans l’eau froide : la peau s’enlève toute seule. Coupez-les en morceaux en retirant le noyau.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-peche' and owner_id is null), 2, 'Faites cuire les morceaux 10 minutes à couvert, à feu doux, jusqu’à ce qu’ils soient très tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-peche' and owner_id is null), 3, 'Mixez finement pour obtenir une compote bien lisse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-peche' and owner_id is null), 4, 'Laissez tiédir avant de servir, ou gardez au frais.') on conflict do nothing;
