insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-compote-abricot', 'Compote d’abricot toute douce', 'Une compote orange et parfumée, adoucie en choisissant des abricots bien mûrs.', array['baby']::text[], array['dessert','snack']::text[], array['start','m6_8','m9_12']::text[], 4, 12, array['smooth']::text[], 4, 'portions bébé', 10, 10, array[]::text[], array['compote','batch','freezer','budget']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.','Si votre bébé fait la grimace, mélangez moitié abricot, moitié compote de pomme.']::text[], 'Réfrigérateur : 48 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, et jetez les restes de l’assiette.', 'Se congèle très bien en bacs à glaçons ou en petits pots : jusqu’à 1 mois. Décongelez au réfrigérateur la veille et consommez dans les 24 heures ; ne recongelez jamais une compote décongelée.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Pas de miel avant 1 an, même pour adoucir.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.']::text[], 'L’abricot apporte du bêta-carotène et des fibres ; son goût acidulé fait découvrir une nouvelle saveur.', 1, array['summer']::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
