insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-abricot' and owner_id is null), 1, 'Lavez les abricots, coupez-les en deux et retirez les noyaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-compote-abricot' and owner_id is null), 2, 'Faites-les cuire 10 minutes à couvert avec 1 cuillère à soupe d’eau, à feu doux, jusqu’à ce qu’ils soient très tendres.') on conflict do nothing;
