insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-patate-douce-courgette-poulet' and owner_id is null), 2, 'Faites cuire la patate douce, la courgette et le poulet 15 minutes à la vapeur : le poulet doit être cuit à cœur, blanc jusqu’au centre, sans partie rosée.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-patate-douce-courgette-poulet' and owner_id is null), 3, 'Mixez très finement le tout avec un peu d’eau de cuisson, jusqu’à obtenir une purée bien lisse, selon ce que votre bébé accepte.') on conflict do nothing;
