insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-saumon-carotte-pomme-de-terre' and owner_id is null), 1, 'Lavez et épluchez la carotte et la pomme de terre, puis coupez-les en dés.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-saumon-carotte-pomme-de-terre' and owner_id is null), 2, 'Faites cuire les légumes 15 minutes à la vapeur, ajoutez le saumon et poursuivez 8 à 10 minutes, jusqu’à ce que sa chair soit opaque jusqu’au centre.') on conflict do nothing;
