insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-boeuf-haricots-verts-pomme-de-terre', 'Bœuf, haricots verts et pomme de terre', 'Un petit repas complet et doux, avec une toute petite quantité de bœuf bien cuit et mixé.', array['baby']::text[], array['lunch']::text[], array['m6_8']::text[], 6, 9, array['smooth','mashed']::text[], 4, 'portions bébé', 10, 15, array[]::text[], array['puree','complete','protein','iron','freezer']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.']::text[], 'Réfrigérateur : 24 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, jusqu’à ce qu’elle soit bien chaude, puis laissez tiédir. Jetez les restes de l’assiette.', 'Se congèle en petits pots dès qu’elle a refroidi : jusqu’à 1 mois. Décongelez au réfrigérateur la veille, réchauffez jusqu’à ce que ce soit bien chaud puis laissez tiédir ; ne recongelez jamais.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Viande cuite à cœur, sans partie rosée, puis mixée très finement.','Lavez la planche et les ustensiles après avoir manipulé la viande crue.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.','Vérifiez la température avant de servir : la purée doit être tiède, jamais brûlante.']::text[], 'Le bœuf apporte du fer et des protéines en petite quantité ; les légumes complètent l’assiette.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-boeuf-haricots-verts-pomme-de-terre' and owner_id is null), 1, 'ground_beef', 'bœuf haché 5 % MG', 60, 'g', 'soit environ 15 g par portion', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-boeuf-haricots-verts-pomme-de-terre' and owner_id is null), 2, 'green_beans', 'haricots verts', 200, 'g', 'extra-fins', false) on conflict do nothing;
