insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-merlu-potiron-pomme-de-terre', 'Merlu, potiron et pomme de terre', 'Une purée orange et veloutée avec un peu de merlu, un poisson blanc très tendre.', array['baby']::text[], array['lunch']::text[], array['m6_8']::text[], 6, 9, array['smooth','mashed']::text[], 4, 'portions bébé', 10, 18, array['fish']::text[], array['puree','complete','protein','freezer']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.']::text[], 'Réfrigérateur : 24 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, jusqu’à ce qu’elle soit bien chaude, puis laissez tiédir. Jetez les restes de l’assiette.', 'Se congèle en petits pots dès qu’elle a refroidi : jusqu’à 1 mois. Décongelez au réfrigérateur la veille, réchauffez jusqu’à ce que ce soit bien chaud puis laissez tiédir ; ne recongelez jamais.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Poisson cuit à cœur : chair opaque jusqu’au centre, qui s’effeuille facilement.','Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.','Vérifiez la température avant de servir : la purée doit être tiède, jamais brûlante.']::text[], 'Le merlu, poisson maigre, apporte des protéines ; le potiron, sa douceur et du bêta-carotène.', 2, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-merlu-potiron-pomme-de-terre' and owner_id is null), 1, 'hake', 'filet de merlu', 60, 'g', 'sans arêtes, soit environ 15 g par portion', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-merlu-potiron-pomme-de-terre' and owner_id is null), 2, 'pumpkin', 'potiron', 200, 'g', 'chair sans peau ni graines', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-merlu-potiron-pomme-de-terre' and owner_id is null), 3, 'potato', 'pomme de terre', 100, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-merlu-potiron-pomme-de-terre' and owner_id is null), 4, 'rapeseed_oil', 'huile de colza', 2, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-merlu-potiron-pomme-de-terre' and owner_id is null), 1, 'Lavez le potiron, retirez la peau et les graines et coupez la chair en cubes ; épluchez la pomme de terre et coupez-la en dés.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-merlu-potiron-pomme-de-terre' and owner_id is null), 2, 'Faites cuire les légumes 10 minutes à la vapeur, ajoutez le merlu et poursuivez 8 minutes, jusqu’à ce que sa chair soit opaque jusqu’au centre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-merlu-potiron-pomme-de-terre' and owner_id is null), 3, 'Émiettez le poisson en retirant la moindre arête.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-merlu-potiron-pomme-de-terre' and owner_id is null), 4, 'Mixez finement le tout avec un peu d’eau de cuisson, selon ce que votre bébé accepte. Au moment de servir, ajoutez une demi-cuillère à café d’huile de colza par portion.') on conflict do nothing;
