insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('dd-dinde-brocoli-pomme-de-terre', 'Dinde, brocoli et pomme de terre', 'Une purée verte et douce, avec une petite quantité de dinde bien cuite pour un repas complet.', array['baby']::text[], array['lunch']::text[], array['m6_8']::text[], 6, 9, array['smooth','mashed']::text[], 4, 'portions bébé', 10, 18, array[]::text[], array['puree','complete','protein','freezer']::text[], array['En grandissant, mixez moins finement puis écrasez à la fourchette, selon ce que votre bébé accepte.']::text[], 'Réfrigérateur : 24 h au plus dans un petit pot fermé ; réchauffez seulement la portion du repas, une seule fois, jusqu’à ce qu’elle soit bien chaude, puis laissez tiédir. Jetez les restes de l’assiette.', 'Se congèle en petits pots dès qu’elle a refroidi : jusqu’à 1 mois. Décongelez au réfrigérateur la veille, réchauffez jusqu’à ce que ce soit bien chaud puis laissez tiédir ; ne recongelez jamais.', array['Sans sel ni sucre ajoutés avant 1 an : le goût naturel des aliments suffit.','Viande cuite à cœur, sans partie rosée, puis mixée très finement.','Lavez la planche et le couteau après avoir coupé la viande crue.','Proposez quelques cuillères au début, puis augmentez selon ce que votre bébé accepte ; en cas de question, parlez-en à son médecin.','Vérifiez la température avant de servir : la purée doit être tiède, jamais brûlante.']::text[], 'La dinde, viande maigre, apporte des protéines en petite quantité ; le brocoli, des fibres et de la vitamine C.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-dinde-brocoli-pomme-de-terre' and owner_id is null), 1, 'turkey', 'escalope de dinde', 60, 'g', 'soit environ 15 g par portion', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-dinde-brocoli-pomme-de-terre' and owner_id is null), 2, 'broccoli', 'brocoli', 150, 'g', 'en petits bouquets', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'dd-dinde-brocoli-pomme-de-terre' and owner_id is null), 3, 'potato', 'pomme de terre', 150, 'g', '1 pomme de terre moyenne', false) on conflict do nothing;
