insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-dinde-brocoli-pomme-de-terre' and owner_id is null), 1, 'Lavez le brocoli et détaillez-le en petits bouquets ; épluchez la pomme de terre et coupez-la en dés ; coupez l’escalope de dinde en petits morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'dd-dinde-brocoli-pomme-de-terre' and owner_id is null), 2, 'Faites cuire la pomme de terre et la dinde 8 minutes à la vapeur, ajoutez le brocoli et poursuivez 10 minutes : la dinde doit être cuite à cœur, sans partie rosée.') on conflict do nothing;
