insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-patate-douce-poulet', 'Écrasé de patate douce au poulet', 'Une assiette orangée toute douce, où le poulet se cache dans la patate douce fondante.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['mashed']::text[], 2, null, 10, 15, array[]::text[], array['puree','protein','freezer','classic']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','La dinde remplace très bien le poulet.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Se congèle très bien : jusqu’à 2 mois en petites portions (bacs à glaçons ou pots hermétiques). Décongelez au réfrigérateur la veille, réchauffez bien et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Viande bien cuite à cœur, sans trace rosée.']::text[], 'La patate douce apporte du bêta-carotène et le poulet des protéines : environ 15 g de poulet par portion, un repère à ajuster selon l’âge (une dizaine de grammes vers 7-8 mois, une vingtaine vers 12 mois).', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-patate-douce-poulet' and owner_id is null), 1, 'sweet_potato', 'patate douce', 150, 'g', 'épluchée', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-patate-douce-poulet' and owner_id is null), 2, 'chicken', 'blanc de poulet', 30, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-patate-douce-poulet' and owner_id is null), 3, 'rapeseed_oil', 'huile de colza', 2, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-patate-douce-poulet' and owner_id is null), 1, 'Épluchez la patate douce et coupez-la en cubes ; coupez le blanc de poulet en petits dés.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-patate-douce-poulet' and owner_id is null), 2, 'Faites cuire la patate douce à la vapeur 15 minutes en ajoutant le poulet pour les 10 dernières minutes : il doit être blanc et bien cuit à cœur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-patate-douce-poulet' and owner_id is null), 3, 'Mixez finement le poulet, puis écrasez la patate douce à la fourchette et mélangez le tout avec un peu d’eau de cuisson.') on conflict do nothing;
