insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-cabillaud-riz-courgette', 'Cabillaud, riz et courgette moulinés', 'Un petit plat de poisson tout doux, à la texture moulinée qui prépare aux premiers grains.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['ground']::text[], 2, null, 10, 15, array['fish']::text[], array['protein','classic','freezer']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Le colin ou le merlu remplacent le cabillaud.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Congélation possible jusqu’à 2 mois si le poisson n’avait pas déjà été congelé cru. Décongelez au réfrigérateur la veille, réchauffez bien à cœur et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Poisson bien cuit, opaque et qui se détache en lamelles ; vérifiez du bout des doigts qu’il ne reste aucune arête.']::text[], 'Le poisson blanc apporte des protéines légères et la courgette beaucoup d’eau et de douceur : environ 15 g de poisson par portion, un repère à ajuster selon l’âge (une dizaine de grammes vers 7-8 mois, une vingtaine vers 12 mois).', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-cabillaud-riz-courgette' and owner_id is null), 1, 'white_fish', 'filet de cabillaud ou de colin', 30, 'g', 'sans peau ni arêtes', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-cabillaud-riz-courgette' and owner_id is null), 2, 'rice', 'riz', 25, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-cabillaud-riz-courgette' and owner_id is null), 3, 'zucchini', 'courgette', 150, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-cabillaud-riz-courgette' and owner_id is null), 4, 'olive_oil', 'huile d''olive', 2, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-cabillaud-riz-courgette' and owner_id is null), 1, 'Faites cuire le riz 15 minutes dans une grande casserole d’eau, en le laissant un peu plus tendre que d’habitude, puis égouttez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-cabillaud-riz-courgette' and owner_id is null), 2, 'Pendant ce temps, lavez la courgette, coupez-la en rondelles et faites-la cuire à la vapeur 10 minutes ; ajoutez le cabillaud pour les 8 dernières minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-cabillaud-riz-courgette' and owner_id is null), 3, 'Effeuillez le poisson en vérifiant qu’il ne reste aucune arête, puis passez poisson, courgette et riz au moulin à légumes (ou mixez par à-coups) pour garder une texture moulinée.') on conflict do nothing;
