insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-merlu-brocoli', 'Merlu au brocoli et pomme de terre écrasés', 'Un écrasé vert tendre où le merlu, poisson très doux, se marie au brocoli.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['mashed']::text[], 2, null, 10, 20, array['fish']::text[], array['protein','vegetables','freezer']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Le chou-fleur remplace le brocoli pour un goût plus doux.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Congélation possible jusqu’à 2 mois si le poisson n’avait pas déjà été congelé cru. Décongelez au réfrigérateur la veille, réchauffez bien à cœur et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Poisson bien cuit, opaque et qui se détache en lamelles ; vérifiez du bout des doigts qu’il ne reste aucune arête.']::text[], 'Le brocoli apporte de la vitamine C et des fibres, le merlu des protéines maigres : environ 15 g de merlu par portion, un repère à ajuster selon l’âge (une dizaine de grammes vers 7-8 mois, une vingtaine vers 12 mois).', 2, array['autumn','winter','spring']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
