insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-poulet-haricots-verts', 'Poulet et haricots verts moulinés', 'Un grand classique des petits pots, fait maison en quelques minutes.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['ground']::text[], 2, null, 10, 18, array[]::text[], array['protein','classic','freezer','vegetables']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Hors saison, les haricots verts surgelés conviennent très bien.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Se congèle très bien : jusqu’à 2 mois en petites portions (bacs à glaçons ou pots hermétiques). Décongelez au réfrigérateur la veille, réchauffez bien et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Viande bien cuite à cœur, sans trace rosée.']::text[], 'Les haricots verts apportent des fibres douces et le poulet des protéines : environ 15 g de poulet par portion, un repère à ajuster selon l’âge (une dizaine de grammes vers 7-8 mois, une vingtaine vers 12 mois).', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
