insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-boeuf-carottes-mijote', 'Bœuf carottes mijoté et mixé', 'Le bœuf carottes du dimanche, mijoté longtemps puis mouliné pour les petits.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['ground']::text[], 4, null, 15, 75, array[]::text[], array['iron','protein','classic','batch','freezer']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Le reste de la cocotte fait un plat pour les grands : ils salent dans leur assiette.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Se congèle très bien : jusqu’à 2 mois en petites portions (bacs à glaçons ou pots hermétiques). Décongelez au réfrigérateur la veille, réchauffez bien et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Viande bien cuite à cœur, sans trace rosée.']::text[], 'Le bœuf apporte du fer bien assimilé et les carottes leur douceur : environ 20 g de bœuf par portion, un repère à ajuster selon l’âge (une dizaine de grammes vers 7-8 mois, une vingtaine vers 12 mois), en gardant le reste de viande pour un autre repas.', 2, array['autumn','winter','spring']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
