insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-boeuf-carottes-mijote' and owner_id is null), 1, 'Coupez le bœuf en petits cubes en retirant le gras et les nerfs ; épluchez les carottes, la pomme de terre et l’oignon, puis coupez-les en morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-boeuf-carottes-mijote' and owner_id is null), 2, 'Mettez le bœuf, les carottes, l’oignon, le thym et la feuille de laurier dans une cocotte, couvrez d’eau et laissez mijoter à couvert 75 minutes à petit feu.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-boeuf-carottes-mijote' and owner_id is null), 3, 'Ajoutez la pomme de terre pour les 20 dernières minutes et poursuivez la cuisson jusqu’à ce que la viande s’effiloche à la fourchette.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-boeuf-carottes-mijote' and owner_id is null), 4, 'Retirez la feuille de laurier, puis mixez par à-coups une part de viande avec une part de légumes et un peu de jus pour obtenir une texture moulinée.') on conflict do nothing;
