insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-dinde-petits-pois-carotte' and owner_id is null), 2, 'Faites cuire la carotte et les petits pois à la vapeur 15 minutes, en ajoutant la dinde pour les 10 dernières minutes : elle doit être bien cuite à cœur.') on conflict do nothing;
