insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-lentilles-corail-butternut', 'Lentilles corail et courge butternut', 'Un écrasé orange et velouté, végétarien et plein de douceur.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['mashed']::text[], 2, null, 10, 18, array[]::text[], array['vegetarian','fiber','iron','puree','budget','freezer']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Le potiron ou la patate douce remplacent la courge butternut.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Se congèle très bien : jusqu’à 2 mois en petites portions (bacs à glaçons ou pots hermétiques). Décongelez au réfrigérateur la veille, réchauffez bien et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Introduisez les légumineuses en petite quantité au début, selon ce que votre enfant accepte.']::text[], 'Les lentilles corail apportent des protéines végétales, du fer et des fibres ; la courge, du bêta-carotène. Avec environ 15 g de lentilles sèches par portion, ce repas peut remplacer la viande ou le poisson.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
