insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-lentilles-corail-butternut' and owner_id is null), 1, 'Rincez les lentilles corail ; épluchez la courge butternut, retirez les graines et coupez-la en cubes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-lentilles-corail-butternut' and owner_id is null), 2, 'Mettez la courge et les lentilles dans une casserole, couvrez juste d’eau et faites cuire à petit feu 18 minutes, jusqu’à ce que les lentilles se défassent.') on conflict do nothing;
