insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-petites-pates-legumes', 'Petites pâtes étoiles aux petits légumes', 'Des petites étoiles fondantes dans une sauce de légumes du soleil.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['mashed']::text[], 2, null, 10, 15, array['gluten']::text[], array['vegetarian','vegetables','budget','classic']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Ajoutez 15 g de poulet ou de poisson cuit et mixé pour un repas complet.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Se congèle très bien : jusqu’à 2 mois en petites portions (bacs à glaçons ou pots hermétiques). Décongelez au réfrigérateur la veille, réchauffez bien et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.']::text[], 'Les petites pâtes apportent l’énergie des féculents et les légumes des vitamines ; ajoutez une petite part de protéines au même repas ou à l’autre repas de la journée.', 1, array['summer','autumn']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
