insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-petites-pates-legumes' and owner_id is null), 2, 'Faites cuire les légumes à couvert avec un fond d’eau 15 minutes, jusqu’à ce qu’ils soient très tendres, puis écrasez-les à la fourchette.') on conflict do nothing;
