insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-compote-pomme-poire' and owner_id is null), 1, 'Épluchez la pomme et la poire, retirez le cœur et les pépins, puis coupez-les en morceaux.') on conflict do nothing;
