insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-yaourt-banane', 'Yaourt nature à la banane écrasée', 'Le dessert minute des premiers mois : un yaourt nature adouci par la banane.', array['baby']::text[], array['snack','dessert','breakfast']::text[], array['m6_8','m9_12']::text[], 7, 12, array['mashed']::text[], 1, null, 3, 0, array['milk']::text[], array['calcium','quick','vegetarian','classic']::text[], array['Remplacez la banane par une poire très mûre écrasée.','Pour un enfant qui découvre les laitages, commencez par quelques cuillères.']::text[], 'À servir aussitôt ; ne se conserve pas une fois préparé.', 'Ne se congèle pas : le laitage se sépare et le fruit noircit. Préparez au moment de servir.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Un yaourt nature au lait pasteurisé, sans sucre ajouté.']::text[], 'Le yaourt apporte du calcium et des protéines, la banane une douceur naturelle sans sucre ajouté.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
