insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-fromage-blanc-poire', 'Fromage blanc et poire fondante', 'Un dessert crémeux avec une poire juste compotée et écrasée.', array['baby']::text[], array['snack','dessert']::text[], array['m6_8','m9_12']::text[], 7, 12, array['mashed']::text[], 2, null, 5, 8, array['milk']::text[], array['calcium','vegetarian','quick']::text[], array['Une poire très mûre peut être simplement écrasée crue.','Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.']::text[], 'La poire écrasée se garde 48 h au réfrigérateur ; mélangez au moment de servir.', 'Seule la poire compotée se congèle (jusqu’à 3 mois) ; mélangez-la au fromage blanc après décongélation au réfrigérateur.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.']::text[], 'Le fromage blanc apporte du calcium et des protéines ; la poire, des fibres et une douceur naturelle.', 1, array['autumn','winter']::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-fromage-blanc-poire' and owner_id is null), 1, 'fromage_blanc', 'fromage blanc nature au lait pasteurisé', 100, 'g', null, false) on conflict do nothing;
