insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-petits-suisses-fraises', 'Petits-suisses aux fraises écrasées', 'Un dessert de printemps rose et frais, sans sucre ajouté.', array['baby']::text[], array['snack','dessert']::text[], array['m6_8','m9_12']::text[], 7, 12, array['mashed']::text[], 2, null, 5, 0, array['milk']::text[], array['calcium','quick','vegetarian']::text[], array['Hors saison, utilisez des fruits rouges surgelés compotés quelques minutes puis refroidis.','Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.']::text[], 'À servir aussitôt ; ne se conserve pas une fois préparé.', 'Ne se congèle pas : le laitage se sépare et le fruit noircit. Préparez au moment de servir.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.']::text[], 'Les petits-suisses apportent du calcium ; les fraises de la vitamine C et leur goût sucré naturel.', 2, array['spring','summer']::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
