insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-veau-panais-carotte', 'Veau mijoté, panais et carotte', 'Une viande tendre et des légumes racines au goût légèrement sucré.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['ground']::text[], 4, null, 15, 45, array[]::text[], array['protein','iron','batch','freezer']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Le panais peut être remplacé par de la pomme de terre.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Se congèle très bien : jusqu’à 2 mois en petites portions (bacs à glaçons ou pots hermétiques). Décongelez au réfrigérateur la veille, réchauffez bien et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Viande bien cuite à cœur, sans trace rosée.']::text[], 'Le veau apporte du fer et des protéines ; le panais et la carotte, des fibres douces : environ 20 g de veau par portion, un repère à ajuster selon l’âge (une dizaine de grammes vers 7-8 mois, une vingtaine vers 12 mois), le reste se congèle en portions.', 3, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
