insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-veau-panais-carotte' and owner_id is null), 2, 'parsnip', 'panais', 150, 'g', null, false) on conflict do nothing;
