insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-veau-panais-carotte' and owner_id is null), 4, 'rapeseed_oil', 'huile de colza', 3, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-veau-panais-carotte' and owner_id is null), 1, 'Coupez le veau en petits cubes en retirant le gras ; épluchez le panais et les carottes et coupez-les en rondelles.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-veau-panais-carotte' and owner_id is null), 2, 'Mettez le tout dans une casserole, couvrez d’eau et laissez mijoter à couvert 45 minutes, jusqu’à ce que la viande soit très tendre et bien cuite à cœur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-veau-panais-carotte' and owner_id is null), 3, 'Égouttez en gardant le jus, puis mixez par à-coups la viande avec les légumes et un peu de jus pour une texture moulinée.') on conflict do nothing;
