insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-truite-poireau-pomme-de-terre', 'Truite, poireau et pomme de terre écrasés', 'Une fondue de poireau toute douce avec une truite bien cuite.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['mashed']::text[], 2, null, 10, 20, array['fish','milk']::text[], array['protein','classic','freezer']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Le saumon remplace la truite.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Congélation possible jusqu’à 2 mois si le poisson n’avait pas déjà été congelé cru. Décongelez au réfrigérateur la veille, réchauffez bien à cœur et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Poisson bien cuit, opaque et qui se détache en lamelles ; vérifiez du bout des doigts qu’il ne reste aucune arête.']::text[], 'La truite apporte des oméga-3 et des protéines, le poireau des fibres douces : environ 15 g de truite par portion, un repère à ajuster selon l’âge (une dizaine de grammes vers 7-8 mois, une vingtaine vers 12 mois).', 2, array['autumn','winter','spring']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
