insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-truite-poireau-pomme-de-terre' and owner_id is null), 1, 'Lavez soigneusement le blanc de poireau et émincez-le finement ; épluchez la pomme de terre et coupez-la en cubes.') on conflict do nothing;
