insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-saumon-petits-pois-riz', 'Saumon, petits pois et riz moulinés', 'Une assiette printanière où le saumon et les petits pois s’accordent tout naturellement.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 7, 12, array['ground']::text[], 2, null, 5, 15, array['fish']::text[], array['protein','complete','freezer']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Le saumon étant naturellement gras, inutile d’ajouter de l’huile.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Congélation possible jusqu’à 2 mois si le poisson n’avait pas déjà été congelé cru. Décongelez au réfrigérateur la veille, réchauffez bien à cœur et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Poisson bien cuit, opaque et qui se détache en lamelles ; vérifiez du bout des doigts qu’il ne reste aucune arête.']::text[], 'Le saumon apporte des oméga-3, les petits pois des fibres et le riz de l’énergie : environ 15 g de saumon par portion, un repère à ajuster selon l’âge (une dizaine de grammes vers 7-8 mois, une vingtaine vers 12 mois).', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
