insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-pois-chiches-carotte-cumin', 'Écrasé de pois chiches et carottes au cumin', 'Une purée dorée, végétarienne et douce, à peine parfumée au cumin.', array['baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12']::text[], 8, 12, array['mashed']::text[], 2, null, 10, 15, array[]::text[], array['vegetarian','fiber','iron','budget']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Choisissez des pois chiches en conserve sans sel ajouté, ou faites-les cuire vous-même.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Se congèle très bien : jusqu’à 2 mois en petites portions (bacs à glaçons ou pots hermétiques). Décongelez au réfrigérateur la veille, réchauffez bien et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Pois chiches pelés et bien écrasés : entiers, ils sont à risque d’étouffement avant 4 ans.']::text[], 'Les pois chiches apportent des protéines végétales, du fer et des fibres ; environ 25 g de pois chiches cuits par portion pour commencer, selon ce que votre enfant accepte.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-pois-chiches-carotte-cumin' and owner_id is null), 1, 'chickpeas', 'pois chiches cuits', 50, 'g', 'cuits, rincés', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-pois-chiches-carotte-cumin' and owner_id is null), 2, 'carrot', 'carotte', 150, 'g', null, false) on conflict do nothing;
