insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-pomme-myrtilles-compotees', 'Pommes et myrtilles compotées', 'Une compote violette surprenante, douce et fruitée.', array['baby']::text[], array['snack','dessert']::text[], array['m6_8','m9_12']::text[], 7, 12, array['mashed']::text[], 2, null, 5, 12, array[]::text[], array['compote','vegetarian','freezer']::text[], array['Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.','Les myrtilles surgelées conviennent toute l’année.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Se congèle très bien : jusqu’à 3 mois en petites portions. Décongelez au réfrigérateur et consommez dans les 48 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Myrtilles toujours écrasées : entières, elles sont à risque d’étouffement avant 4 ans.']::text[], 'Les myrtilles apportent des antioxydants et de la vitamine C, la pomme des fibres, le tout sans sucre ajouté.', 2, array['summer','autumn']::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-pomme-myrtilles-compotees' and owner_id is null), 1, 'apple', 'pomme', 2, 'u', null, false) on conflict do nothing;
