insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-pomme-myrtilles-compotees' and owner_id is null), 2, 'Faites cuire les pommes et les myrtilles à couvert avec un fond d’eau 12 minutes, jusqu’à ce que les myrtilles éclatent.') on conflict do nothing;
