insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('me-porridge-avoine-pomme', 'Bouillie d’avoine à la pomme cuite', 'Un petit-déjeuner chaud et réconfortant, adouci par la pomme.', array['baby']::text[], array['breakfast','snack']::text[], array['m6_8','m9_12']::text[], 8, 12, array['mashed']::text[], 1, null, 3, 6, array['gluten']::text[], array['fiber','quick','vegetarian','budget']::text[], array['Préparez-la avec le lait habituel de votre enfant au lieu de l’eau.','Ajustez la texture selon ce que votre enfant accepte : plus fine au début, plus grumeleuse quand il est à l’aise.']::text[], 'À préparer au moment ; 24 h au réfrigérateur au maximum, à réchauffer avec un peu d’eau.', 'Congélation déconseillée : la bouillie devient pâteuse. Elle se prépare en quelques minutes.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Pomme râpée puis cuite jusqu’à être tendre.']::text[], 'L’avoine apporte des fibres et de l’énergie qui dure ; la pomme, sa douceur naturelle sans sucre ajouté.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'me-porridge-avoine-pomme' and owner_id is null), 1, 'oats', 'flocons d''avoine', 15, 'g', null, false) on conflict do nothing;
