insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-porridge-avoine-pomme' and owner_id is null), 1, 'Épluchez la demi-pomme et râpez-la finement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'me-porridge-avoine-pomme' and owner_id is null), 2, 'Mettez les flocons d’avoine, la pomme râpée et 120 ml d’eau dans une petite casserole et faites cuire à feu doux 6 minutes en remuant, jusqu’à obtenir une bouillie épaisse.') on conflict do nothing;
