insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-boulettes-cabillaud-puree-carotte', 'Boulettes de cabillaud et purée de carotte', 'De petites boulettes de poisson moelleuses à attraper, avec une purée de carotte toute douce.', array['baby']::text[], array['lunch','dinner']::text[], array['m9_12','m12_18','m18_24','y2_3']::text[], 10, 36, array['pieces']::text[], 2, null, 15, 28, array['fish','eggs','milk']::text[], array['finger','protein','freezer']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Le merlu ou le colin remplacent le cabillaud.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Congélation possible jusqu’à 2 mois si le poisson n’avait pas déjà été congelé cru. Décongelez au réfrigérateur la veille, réchauffez bien à cœur et consommez dans les 24 h, sans recongeler.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Poisson bien cuit, opaque et qui se détache en lamelles ; vérifiez du bout des doigts qu’il ne reste aucune arête.','Œuf toujours bien cuit : blanc et jaune fermes.','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Le poisson apporte des protéines et de l’iode, la carotte du bêta-carotène : environ 20 g de poisson par portion pour l’enfant, un repère à ajuster selon l’âge (une vingtaine de grammes vers 1 an, une trentaine vers 2 ans).', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-boulettes-cabillaud-puree-carotte' and owner_id is null), 1, 'white_fish', 'filet de cabillaud ou de colin', 80, 'g', 'sans peau ni arêtes', false) on conflict do nothing;
