insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-gratin-coquillettes-brocoli', 'Gratin de coquillettes au brocoli', 'Le gratin de pâtes familial, avec du brocoli fondant caché dans la béchamel.', array['baby','family']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 4, null, 15, 30, array['gluten','milk']::text[], array['family','classic','vegetarian','calcium','batch']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Ajoutez des dés de jambon ou de poulet cuit dans la part des grands.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Se congèle bien : jusqu’à 2 mois en portions individuelles. Décongelez au réfrigérateur la veille et réchauffez bien à cœur ; ne recongelez pas.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Fromage à pâte pressée cuite, fondu dans le plat (pas de fromage au lait cru avant 5 ans).','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Les pâtes apportent l’énergie, la béchamel du calcium et le brocoli de la vitamine C ; ajoutez une petite part de protéines à l’autre repas de la journée.', 1, array['autumn','winter','spring']::text[], 'hot', '{"baby":"Servez la part de l’enfant avant de saler, avec des coquillettes bien cuites et un brocoli écrasé.","child":"Laissez-le parsemer lui-même le fromage avant de passer au four."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-gratin-coquillettes-brocoli' and owner_id is null), 1, 'pasta', 'pâtes', 250, 'g', 'coquillettes', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-gratin-coquillettes-brocoli' and owner_id is null), 2, 'broccoli', 'brocoli', 300, 'g', null, false) on conflict do nothing;
