insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-gratin-coquillettes-brocoli' and owner_id is null), 1, 'Faites cuire les coquillettes dans l’eau bouillante 10 minutes ; ajoutez le brocoli en petits bouquets pour les 6 dernières minutes, puis égouttez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-gratin-coquillettes-brocoli' and owner_id is null), 2, 'Pour la béchamel, faites fondre le beurre, ajoutez la farine et remuez 1 minute, puis versez le lait petit à petit en fouettant jusqu’à ce que la sauce épaississe ; ajoutez la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-gratin-coquillettes-brocoli' and owner_id is null), 3, 'Mélangez pâtes, brocoli et béchamel dans un plat, parsemez d’emmental et faites gratiner au four à 200 °C 15 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-gratin-coquillettes-brocoli' and owner_id is null), 4, 'Pour l’enfant, écrasez légèrement les bouquets de brocoli et laissez bien tiédir.') on conflict do nothing;
