insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-omelette-courgette-lanieres', 'Omelette à la courgette en lanières', 'Une omelette bien cuite, coupée en lanières faciles à attraper avec les doigts.', array['baby']::text[], array['lunch','dinner']::text[], array['m9_12','m12_18','m18_24']::text[], 9, 24, array['pieces']::text[], 2, null, 5, 8, array['eggs']::text[], array['finger','protein','quick','vegetarian']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Remplacez la courgette par des épinards hachés bien égouttés.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Congélation déconseillée : l’œuf cuit devient caoutchouteux. Préparez au moment du repas.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Œuf toujours bien cuit : blanc et jaune fermes.','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'L’œuf est une protéine complète : environ un demi-œuf par portion, une part qui remplace la viande ou le poisson du repas, selon ce que votre enfant accepte.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
