insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poulet-legumes-des-fondants' and owner_id is null), 1, 'Épluchez la carotte et la pomme de terre, lavez la courgette et coupez tous les légumes en dés d’environ 1 cm ; coupez le poulet en petits dés.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poulet-legumes-des-fondants' and owner_id is null), 2, 'Faites cuire la carotte et la pomme de terre à la vapeur 10 minutes, puis ajoutez la courgette et le poulet et poursuivez 10 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poulet-legumes-des-fondants' and owner_id is null), 3, 'Vérifiez que le poulet est bien cuit à cœur et que chaque dé de légume s’écrase facilement entre deux doigts.') on conflict do nothing;
