insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-risotto-petits-legumes', 'Risotto crémeux aux petits légumes', 'Un risotto onctueux aux courgettes et petits pois, à partager en famille.', array['baby','family']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 4, null, 10, 25, array['milk']::text[], array['family','vegetarian','vegetables','classic']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Les petits pois peuvent être légèrement écrasés dans la part de l’enfant.']::text[], '24 h au réfrigérateur, à réchauffer une seule fois avec un peu d’eau.', 'Congélation déconseillée : le riz devient farineux. Les restes se gardent 24 h au réfrigérateur et se réchauffent avec un peu d’eau.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Fromage à pâte pressée cuite, fondu dans le plat (pas de fromage au lait cru avant 5 ans).','Petits pois bien cuits et écrasés pour les plus jeunes.']::text[], 'Le riz apporte l’énergie, les petits pois des protéines végétales et des fibres, le parmesan du calcium ; complétez avec une petite part de protéines.', 2, array['spring','summer']::text[], 'hot', '{"baby":"Prélevez la part de l’enfant avant de saler ; écrasez légèrement les petits pois.","child":"Laissez-le ajouter le parmesan et remuer lui-même son assiette."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
