insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-risotto-petits-legumes' and owner_id is null), 6, 'parmesan', 'parmesan en bloc (râpé à la maison)', 40, 'g', 'râpé', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-risotto-petits-legumes' and owner_id is null), 1, 'Épluchez et hachez finement l’oignon ; lavez la courgette et coupez-la en petits dés. Faites chauffer un litre d’eau dans une casserole.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-risotto-petits-legumes' and owner_id is null), 2, 'Faites revenir l’oignon dans l’huile d’olive 3 minutes, ajoutez le riz et remuez jusqu’à ce qu’il devienne translucide.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-risotto-petits-legumes' and owner_id is null), 3, 'Versez l’eau chaude louche par louche en remuant, en attendant qu’elle soit absorbée avant d’en ajouter ; au bout de 10 minutes, ajoutez la courgette et les petits pois.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-risotto-petits-legumes' and owner_id is null), 4, 'Poursuivez la cuisson 10 minutes, jusqu’à ce que le riz soit très tendre et crémeux, puis ajoutez le parmesan hors du feu.') on conflict do nothing;
