insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-galettes-legumes-moelleuses', 'Galettes de légumes moelleuses', 'Des petites galettes dorées de courgette et carotte, à manger avec les doigts.', array['baby']::text[], array['lunch','dinner']::text[], array['m9_12','m12_18','m18_24','y2_3']::text[], 10, 36, array['pieces']::text[], 3, '10 petites galettes', 15, 10, array['eggs','gluten','milk']::text[], array['finger','vegetarian','vegetables','freezer','lunchbox']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Remplacez la carotte par de la patate douce râpée.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Se congèlent bien : jusqu’à 2 mois, séparées par du papier cuisson. Décongelez au réfrigérateur et réchauffez à la poêle ou au four.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Œuf toujours bien cuit : blanc et jaune fermes.','Fromage à pâte pressée cuite, fondu dans le plat (pas de fromage au lait cru avant 5 ans).','Carotte râpée finement et cuite jusqu’à être tendre. Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Une façon ludique de manger des légumes ; l’œuf et le fromage apportent un peu de protéines et de calcium.', 1, array['spring','summer','autumn']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
