insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-galettes-legumes-moelleuses' and owner_id is null), 1, 'Râpez finement la courgette et la carotte, puis pressez la courgette dans un torchon pour retirer l’eau.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-galettes-legumes-moelleuses' and owner_id is null), 2, 'Mélangez les légumes râpés avec l’œuf, la farine et l’emmental.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-galettes-legumes-moelleuses' and owner_id is null), 3, 'Faites chauffer l’huile d’olive dans une poêle, déposez de petites cuillerées de pâte en les aplatissant et faites cuire 5 minutes de chaque côté à feu moyen, jusqu’à ce qu’elles soient bien cuites au centre.') on conflict do nothing;
