insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-petits-flans-carotte', 'Petits flans de carotte au fromage frais', 'Des flans orangés et fondants, qui se mangent à la cuillère ou en petits cubes.', array['baby']::text[], array['lunch','dinner']::text[], array['m9_12','m12_18','m18_24','y2_3']::text[], 10, 36, array['pieces']::text[], 4, null, 10, 40, array['eggs','milk']::text[], array['vegetarian','vegetables','protein']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Le potiron ou le brocoli remplacent la carotte.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Congélation déconseillée : les flans rendent de l’eau en décongelant. Ils se gardent 48 h au réfrigérateur.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Œuf toujours bien cuit : blanc et jaune fermes.']::text[], 'La carotte apporte du bêta-carotène et l’œuf des protéines : un demi-œuf environ par flan, une part adaptée vers 1 an.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
