insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-crepes-compote', 'Crêpes moelleuses et compote de pommes', 'Des crêpes sans sucre roulées autour d’une compote, pour un goûter de fête simple.', array['baby']::text[], array['snack','breakfast','dessert']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces']::text[], 4, '8 crêpes', 10, 20, array['gluten','eggs','milk']::text[], array['finger','classic','vegetarian']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Remplacez la compote par une banane écrasée.']::text[], '48 h au réfrigérateur, filmées ; garnissez au moment de servir.', 'Les crêpes nature se congèlent jusqu’à 2 mois, séparées par du papier cuisson ; décongelez au réfrigérateur et garnissez au moment.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Œuf toujours bien cuit : blanc et jaune fermes.','Installez l’enfant assis bien droit et restez à côté de lui pendant tout le repas.']::text[], 'Un goûter qui associe féculent, laitage et fruit, sans sucre ajouté : la compote suffit à adoucir.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
