insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-crepes-compote' and owner_id is null), 1, 'Versez la farine dans un saladier, creusez un puits, ajoutez l’œuf et le lait petit à petit en fouettant, puis le beurre fondu.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-crepes-compote' and owner_id is null), 2, 'Laissez reposer la pâte 30 minutes si vous avez le temps.') on conflict do nothing;
