insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-biscuits-banane-avoine', 'Biscuits banane-avoine sans sucre ajouté', 'Des biscuits tendres à deux ingrédients principaux, sucrés seulement par la banane.', array['baby']::text[], array['snack','breakfast']::text[], array['m9_12','m12_18','m18_24','y2_3']::text[], 10, 36, array['pieces']::text[], 4, '12 biscuits', 10, 15, array['gluten']::text[], array['finger','vegetarian','budget','lunchbox','freezer']::text[], array['Ajoutez une cuillerée de compote si la pâte est trop sèche.','Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.']::text[], '3 jours dans une boîte hermétique au réfrigérateur.', 'Se congèlent bien : jusqu’à 2 mois dans une boîte. Décongelez à température ambiante en une heure.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Biscuits tendres qui fondent en bouche ; Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'L’avoine apporte des fibres et la banane de l’énergie : un goûter sans sucre ajouté, adapté dès que votre enfant mâche les morceaux fondants.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
