insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-biscuits-banane-avoine' and owner_id is null), 2, 'Ajoutez les flocons d’avoine, l’huile de colza et la cannelle si vous le souhaitez, puis laissez gonfler 5 minutes.') on conflict do nothing;
