insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-mini-pancakes-banane', 'Mini-pancakes à la banane', 'Des petits pancakes moelleux, faciles à tenir dans la main.', array['baby']::text[], array['breakfast','snack']::text[], array['m9_12','m12_18','m18_24','y2_3']::text[], 10, 36, array['pieces']::text[], 2, '10 mini-pancakes', 5, 10, array['gluten','eggs']::text[], array['finger','quick','vegetarian']::text[], array['La farine d’avoine (flocons mixés) remplace la farine de blé.','Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.']::text[], '24 h au réfrigérateur.', 'Se congèlent bien : jusqu’à 2 mois. Réchauffez quelques secondes à la poêle après décongélation au réfrigérateur.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Œuf toujours bien cuit : blanc et jaune fermes.','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'La banane remplace le sucre et l’œuf apporte des protéines : un petit-déjeuner ou un goûter complet avec un laitage.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-mini-pancakes-banane' and owner_id is null), 1, 'banana', 'banane', 1, 'u', 'bien mûre', false) on conflict do nothing;
