insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-mini-pancakes-banane' and owner_id is null), 4, 'rapeseed_oil', 'huile de colza', 1, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-mini-pancakes-banane' and owner_id is null), 1, 'Écrasez la banane en purée, puis ajoutez l’œuf et la farine en fouettant pour obtenir une pâte épaisse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-mini-pancakes-banane' and owner_id is null), 2, 'Huilez légèrement une poêle antiadhésive avec l’huile de colza et faites-la chauffer à feu moyen.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-mini-pancakes-banane' and owner_id is null), 3, 'Versez de petites cuillerées de pâte et faites cuire 2 minutes de chaque côté, jusqu’à ce que les pancakes soient bien cuits au centre.') on conflict do nothing;
