insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-hachis-parmentier-carottes', 'Hachis parmentier aux carottes fondantes', 'Le hachis parmentier de toujours, avec des carottes glissées dans la viande pour tous.', array['baby','family']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 5, null, 20, 40, array['milk']::text[], array['family','classic','iron','batch','freezer']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Une partie de la purée peut être faite avec de la patate douce.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Se congèle bien : jusqu’à 2 mois en portions individuelles. Décongelez au réfrigérateur la veille et réchauffez bien à cœur ; ne recongelez pas.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Viande bien cuite à cœur, sans trace rosée.','Fromage à pâte pressée cuite, fondu dans le plat (pas de fromage au lait cru avant 5 ans).']::text[], 'Le bœuf apporte du fer bien assimilé et la purée l’énergie : environ 25 g de bœuf par portion pour l’enfant, un repère à ajuster selon l’âge (une vingtaine de grammes vers 1 an, une trentaine vers 2 ans).', 2, array['autumn','winter']::text[], 'hot', '{"baby":"Prélevez sa part avant de saler et écrasez bien la viande dans la purée.","child":"Servez-le dans un petit ramequin individuel, comme un « vrai » parmentier."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
