insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-hachis-parmentier-carottes' and owner_id is null), 1, 'Épluchez les pommes de terre et faites-les cuire à l’eau 20 minutes ; pendant ce temps, épluchez l’oignon et les carottes et hachez-les finement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-hachis-parmentier-carottes' and owner_id is null), 2, 'Faites cuire l’oignon et les carottes dans une poêle avec un fond d’eau 8 minutes, puis ajoutez le bœuf haché et faites cuire 8 minutes en l’émiettant, jusqu’à ce qu’il ne reste aucune trace rosée.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-hachis-parmentier-carottes' and owner_id is null), 3, 'Écrasez les pommes de terre avec le lait chaud, le beurre et la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-hachis-parmentier-carottes' and owner_id is null), 4, 'Étalez la viande dans un plat, couvrez de purée, parsemez d’emmental et faites gratiner au four à 200 °C 15 minutes.') on conflict do nothing;
