insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-dinde-semoule-legumes', 'Dinde, semoule et légumes fondants', 'Une assiette façon couscous doux, avec de petits morceaux tendres.', array['baby']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces']::text[], 2, null, 10, 20, array['gluten']::text[], array['protein','complete','world']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Le poulet remplace la dinde.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'La dinde et les légumes se congèlent jusqu’à 2 mois (décongélation au réfrigérateur, réchauffage à cœur) ; la semoule se prépare au moment.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Viande bien cuite à cœur, sans trace rosée.','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Un repas complet et doux : environ 25 g de dinde par portion pour l’enfant, un repère à ajuster selon l’âge (une vingtaine de grammes vers 1 an, une trentaine vers 2 ans).', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
