insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-dinde-semoule-legumes' and owner_id is null), 1, 'Épluchez la carotte, lavez la courgette et coupez-les en petits dés ; coupez la dinde en petits morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-dinde-semoule-legumes' and owner_id is null), 2, 'Faites cuire la carotte dans une casserole d’eau 10 minutes, ajoutez la courgette, la dinde et une pincée de cumin si vous le souhaitez, puis poursuivez 10 minutes.') on conflict do nothing;
