insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-boeuf-carottes-fondant', 'Bœuf carottes fondant en famille', 'Le plat mijoté du dimanche, si tendre qu’il s’effiloche pour les petits.', array['baby','family']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 6, null, 20, 130, array[]::text[], array['family','classic','iron','batch','freezer']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Servez avec des pommes de terre vapeur ou des pâtes.']::text[], '48 h au réfrigérateur ; c’est encore meilleur réchauffé.', 'Se congèle bien : jusqu’à 2 mois en portions individuelles. Décongelez au réfrigérateur la veille et réchauffez bien à cœur ; ne recongelez pas.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Viande bien cuite à cœur, sans trace rosée.','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Le bœuf apporte du fer bien assimilé : environ 25 g de bœuf par portion pour l’enfant, un repère à ajuster selon l’âge (une vingtaine de grammes vers 1 an, une trentaine vers 2 ans).', 2, array['autumn','winter']::text[], 'hot', '{"baby":"Effilochez la viande très finement et écrasez les carottes ; ne salez pas sa part.","child":"Coupez la viande en petits morceaux et servez avec des pâtes."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
