insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-boeuf-carottes-fondant' and owner_id is null), 3, 'Ajoutez les carottes, le thym, la feuille de laurier et de l’eau à hauteur, couvrez et laissez mijoter à petit feu 120 minutes, jusqu’à ce que la viande s’effiloche à la fourchette.') on conflict do nothing;
