insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-frites-polenta-four', 'Frites de polenta au four', 'Des bâtonnets dorés dehors, fondants dedans, parfaits à attraper.', array['baby']::text[], array['lunch','dinner','snack']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces']::text[], 3, null, 10, 25, array['milk']::text[], array['finger','vegetarian','lunchbox']::text[], array['Servez avec une sauce tomate maison ou un écrasé de légumes.','Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Les bâtonnets cuits se congèlent jusqu’à 2 mois ; réchauffez-les directement au four après décongélation au réfrigérateur.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Fromage à pâte pressée cuite, fondu dans le plat (pas de fromage au lait cru avant 5 ans).','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'La polenta, sans gluten, apporte l’énergie des céréales ; associez-la à des légumes et à une petite part de protéines.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-frites-polenta-four' and owner_id is null), 1, 'polenta', 'polenta (semoule de maïs)', 100, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-frites-polenta-four' and owner_id is null), 2, 'parmesan', 'parmesan en bloc (râpé à la maison)', 20, 'g', 'râpé', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-frites-polenta-four' and owner_id is null), 3, 'olive_oil', 'huile d''olive', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-frites-polenta-four' and owner_id is null), 1, 'Versez la polenta en pluie dans 400 ml d’eau frémissante et faites cuire 5 minutes en remuant, puis ajoutez le parmesan.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-frites-polenta-four' and owner_id is null), 2, 'Étalez la polenta sur 1,5 cm d’épaisseur dans un plat recouvert de papier cuisson et laissez prendre au réfrigérateur (repos d’au moins 60 minutes).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-frites-polenta-four' and owner_id is null), 3, 'Préchauffez le four à 200 °C, coupez la polenta en bâtonnets de la taille d’un doigt d’adulte et badigeonnez-les d’huile d’olive.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-frites-polenta-four' and owner_id is null), 4, 'Faites cuire 20 minutes en les retournant à mi-cuisson, puis laissez tiédir.') on conflict do nothing;
