insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-poisson-pane-maison', 'Poisson pané maison au four', 'Des bâtonnets de poisson croustillants, faits maison et cuits au four, pour toute la famille.', array['baby','family']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 4, null, 15, 15, array['fish','gluten','eggs']::text[], array['family','finger','classic','protein']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Servez avec une purée maison ou des légumes vapeur.']::text[], '24 h au réfrigérateur dans un récipient fermé, à réchauffer une seule fois.', 'Congelez les bâtonnets panés crus (si le poisson était frais) jusqu’à 2 mois et faites-les cuire directement au four sans décongeler, 5 minutes de plus ; cuits, ils se gardent 24 h au réfrigérateur.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Poisson bien cuit, opaque et qui se détache en lamelles ; vérifiez du bout des doigts qu’il ne reste aucune arête.','Œuf toujours bien cuit : blanc et jaune fermes.','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Le poisson blanc apporte des protéines et de l’iode : environ 30 g de poisson par portion pour l’enfant, un repère à ajuster selon l’âge (une vingtaine de grammes vers 1 an, une trentaine vers 2 ans).', 2, array[]::text[], 'hot', '{"baby":"Retirez la panure si elle est trop croustillante pour lui et effeuillez le poisson.","child":"Laissez-le paner lui-même quelques bâtonnets."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-poisson-pane-maison' and owner_id is null), 1, 'white_fish', 'filet de cabillaud ou de colin', 400, 'g', 'cabillaud ou colin, sans arêtes', false) on conflict do nothing;
