insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-poisson-pane-maison' and owner_id is null), 4, 'breadcrumbs', 'chapelure (vérifiez l’étiquette : lait ou sésame possibles)', 60, 'g', null, false) on conflict do nothing;
