insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-poisson-pane-maison' and owner_id is null), 6, 'lemon', 'citron', 0.5, 'u', 'facultatif', true) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poisson-pane-maison' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Coupez le poisson en bâtonnets épais en vérifiant du bout des doigts qu’il ne reste aucune arête.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poisson-pane-maison' and owner_id is null), 2, 'Passez chaque bâtonnet dans la farine, puis dans l’œuf battu, puis dans la chapelure.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poisson-pane-maison' and owner_id is null), 3, 'Posez-les sur une plaque recouverte de papier cuisson, arrosez d’un filet d’huile de colza et faites cuire 15 minutes, jusqu’à ce que le poisson soit opaque à cœur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poisson-pane-maison' and owner_id is null), 4, 'Servez avec un quartier de citron pour les grands ; pour l’enfant, coupez en petits morceaux.') on conflict do nothing;
