insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-truite-riz-haricots-verts' and owner_id is null), 2, 'rice', 'riz', 50, 'g', null, false) on conflict do nothing;
