insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-truite-riz-haricots-verts' and owner_id is null), 1, 'Faites cuire le riz dans l’eau bouillante 15 minutes en le laissant bien tendre, puis égouttez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-truite-riz-haricots-verts' and owner_id is null), 2, 'Équeutez les haricots verts, coupez-les en tronçons de 1 cm et faites-les cuire à la vapeur 15 minutes ; ajoutez la truite pour les 8 dernières minutes.') on conflict do nothing;
