insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-gratin-chou-fleur-pommes-de-terre', 'Gratin de chou-fleur et pommes de terre', 'Un gratin crémeux et doux, où le chou-fleur se fait tout petit.', array['baby','family']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 4, null, 15, 35, array['gluten','milk']::text[], array['family','vegetarian','calcium','vegetables','classic']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Ajoutez des dés de jambon dans la part des grands.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Se congèle bien : jusqu’à 2 mois en portions individuelles. Décongelez au réfrigérateur la veille et réchauffez bien à cœur ; ne recongelez pas.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Fromage à pâte pressée cuite, fondu dans le plat (pas de fromage au lait cru avant 5 ans).','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Le chou-fleur apporte de la vitamine C et la béchamel du calcium ; associez une petite part de protéines au repas.', 1, array['autumn','winter']::text[], 'hot', '{"baby":"Écrasez légèrement sa part à la fourchette, avant de saler celle des grands.","child":"Servez-le avec un œuf dur ou une tranche de jambon pour un repas complet."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
