insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-gratin-chou-fleur-pommes-de-terre' and owner_id is null), 2, 'Pour la béchamel, faites fondre le beurre, ajoutez la farine, puis le lait petit à petit en fouettant jusqu’à épaississement ; ajoutez la muscade.') on conflict do nothing;
