insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-dahl-lentilles-corail-coco', 'Dahl doux de lentilles corail au lait de coco', 'Un plat végétarien doré et fondant, servi avec du riz, que les petits adorent.', array['baby','family']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 5, null, 10, 25, array[]::text[], array['family','vegetarian','iron','fiber','world','budget','batch']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Les grands ajoutent un peu de piment ou de coriandre dans leur assiette.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Le dahl se congèle jusqu’à 3 mois (décongélation au réfrigérateur, réchauffage avec un peu d’eau) ; le riz se cuit au moment.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Carotte râpée et bien cuite dans la sauce.']::text[], 'Les lentilles corail associées au riz apportent des protéines végétales complètes, du fer et des fibres ; environ 25 g de lentilles sèches par portion pour l’enfant.', 1, array[]::text[], 'hot', '{"baby":"Mélangez le dahl et le riz et écrasez légèrement ; ne salez pas sa part.","child":"Servez avec un pain pita pour tremper."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
