insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-dahl-lentilles-corail-coco' and owner_id is null), 1, 'Émincez finement l’oignon et râpez la carotte ; faites-les cuire dans une casserole avec un fond d’eau 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-dahl-lentilles-corail-coco' and owner_id is null), 2, 'Ajoutez les lentilles, les tomates concassées, le lait de coco, le curcuma, le cumin et 400 ml d’eau, puis laissez mijoter 20 minutes en remuant, jusqu’à ce que les lentilles se défassent.') on conflict do nothing;
