insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-muffins-pomme-avoine', 'Muffins pomme-avoine sans sucre ajouté', 'Des muffins moelleux et fruités pour les goûters, sucrés seulement par la pomme.', array['baby']::text[], array['snack','breakfast']::text[], array['m9_12','m12_18','m18_24','y2_3']::text[], 10, 36, array['pieces']::text[], 6, '18 mini-muffins', 15, 20, array['gluten','eggs','milk']::text[], array['finger','vegetarian','lunchbox','freezer','batch']::text[], array['Remplacez une pomme par une poire bien mûre.','Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.']::text[], '3 jours dans une boîte hermétique.', 'Se congèlent très bien : jusqu’à 3 mois. Décongelez à température ambiante en une heure ou quelques secondes au four.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Pomme râpée finement et cuite dans la pâte. Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Un goûter qui associe céréales, laitage et fruit, sans sucre ajouté.', 1, array['autumn','winter']::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
