insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-clafoutis-abricots', 'Clafoutis aux abricots sans sucre ajouté', 'Un dessert d’été moelleux où les abricots bien mûrs font toute la douceur.', array['baby','family']::text[], array['dessert','snack']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 6, null, 10, 35, array['eggs','gluten','milk']::text[], array['family','classic','vegetarian','calcium']::text[], array['Les pêches ou les prunes remplacent les abricots.','Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Congélation déconseillée : le clafoutis rend de l’eau. Il se garde 48 h au réfrigérateur.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Œuf toujours bien cuit : blanc et jaune fermes.','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Les abricots apportent du bêta-carotène, l’œuf et le lait des protéines et du calcium.', 2, array['summer']::text[], 'cold', '{"baby":"Choisissez des abricots très mûrs et coupez sa part en petits carrés.","child":"Les grands peuvent ajouter un peu de sucre dans leur part au moment de servir."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
