insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-clafoutis-abricots' and owner_id is null), 5, 'butter', 'beurre', 5, 'g', 'pour le moule', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-clafoutis-abricots' and owner_id is null), 1, 'Préchauffez le four à 180 °C. Beurrez un moule ; lavez les abricots, ouvrez-les, retirez les noyaux et coupez-les en quartiers.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-clafoutis-abricots' and owner_id is null), 2, 'Fouettez les œufs avec la farine, puis ajoutez le lait petit à petit pour obtenir une pâte lisse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-clafoutis-abricots' and owner_id is null), 3, 'Disposez les abricots dans le moule, versez la pâte et faites cuire 35 minutes, jusqu’à ce que le centre soit bien pris.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-clafoutis-abricots' and owner_id is null), 4, 'Laissez tiédir et coupez en petits carrés fondants pour l’enfant.') on conflict do nothing;
