insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-batonnets-poire-pomme-vapeur', 'Bâtonnets de poire et pomme fondants', 'Des fruits cuits juste ce qu’il faut pour être tendres, à attraper avec les doigts.', array['baby']::text[], array['snack','dessert']::text[], array['m9_12','m12_18','m18_24']::text[], 9, 24, array['pieces']::text[], 2, null, 5, 10, array[]::text[], array['finger','vegetarian','budget','quick']::text[], array['Une poire très mûre peut se servir crue, épluchée, en bâtonnets.','Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.']::text[], '24 h au réfrigérateur dans une boîte fermée.', 'Congélation déconseillée : les bâtonnets deviennent mous. Ils se gardent 24 h au réfrigérateur.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Pomme toujours cuite jusqu’à être tendre : crue et dure, elle est à risque d’étouffement avant 4 ans. Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Des fruits pour les fibres et la vitamine C, et un bon exercice pour apprendre à porter les aliments à la bouche.', 1, array['autumn','winter']::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-batonnets-poire-pomme-vapeur' and owner_id is null), 1, 'pear', 'poire', 1, 'u', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-batonnets-poire-pomme-vapeur' and owner_id is null), 2, 'apple', 'pomme', 1, 'u', null, false) on conflict do nothing;
