insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-batonnets-poire-pomme-vapeur' and owner_id is null), 1, 'Épluchez la poire et la pomme, retirez le cœur et coupez-les en bâtonnets épais de la taille d’un doigt d’adulte.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-batonnets-poire-pomme-vapeur' and owner_id is null), 2, 'Faites-les cuire à la vapeur 10 minutes, jusqu’à ce qu’ils s’écrasent facilement entre le pouce et l’index.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-batonnets-poire-pomme-vapeur' and owner_id is null), 3, 'Saupoudrez d’une pincée de cannelle si vous le souhaitez et laissez tiédir.') on conflict do nothing;
