insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-poulet-basquaise-doux', 'Poulet basquaise tout doux', 'Le poulet aux poivrons et tomates, sans piment, mijoté jusqu’à être fondant.', array['baby','family']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 5, null, 20, 50, array[]::text[], array['family','classic','protein','vegetables']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','Hors saison, remplacez les tomates fraîches par des tomates concassées en conserve.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Se congèle bien : jusqu’à 2 mois en portions individuelles. Décongelez au réfrigérateur la veille et réchauffez bien à cœur ; ne recongelez pas.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Viande bien cuite à cœur, sans trace rosée.','Vérifiez qu’il ne reste aucun os ni morceau de peau dans la part de l’enfant. Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Les poivrons apportent de la vitamine C et le poulet des protéines : environ 25 g de poulet par portion pour l’enfant, un repère à ajuster selon l’âge (une vingtaine de grammes vers 1 an, une trentaine vers 2 ans).', 2, array['summer','autumn']::text[], 'hot', '{"baby":"Effilochez le poulet, écrasez les légumes et mélangez avec le riz ; ne salez pas sa part.","child":"Servez la sauce à côté du riz s’il préfère."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-poulet-basquaise-doux' and owner_id is null), 1, 'chicken_thigh', 'cuisses de poulet', 800, 'g', 'sans peau', false) on conflict do nothing;
