insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-poulet-basquaise-doux' and owner_id is null), 7, 'thyme', 'thym', 1, 'pincee', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-poulet-basquaise-doux' and owner_id is null), 8, 'rice', 'riz', 250, 'g', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poulet-basquaise-doux' and owner_id is null), 1, 'Épluchez l’oignon et la gousse d’ail ; émincez l’oignon, épépinez les poivrons et coupez-les en lanières, puis coupez les tomates en morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poulet-basquaise-doux' and owner_id is null), 2, 'Faites dorer le poulet dans l’huile d’olive en cocotte, ajoutez l’oignon, l’ail écrasé et les poivrons, et laissez revenir 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poulet-basquaise-doux' and owner_id is null), 3, 'Ajoutez les tomates et le thym, couvrez et laissez mijoter 40 minutes, jusqu’à ce que le poulet soit bien cuit et se détache de l’os ; pendant ce temps, faites cuire le riz 15 minutes dans l’eau bouillante.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-poulet-basquaise-doux' and owner_id is null), 4, 'Pour l’enfant, retirez les os, effilochez le poulet, retirez la peau des poivrons si elle se détache et servez avec le riz.') on conflict do nothing;
insert into public.recipe_photos (recipe_id, kind, source, author, license, url, rights, generated, alt) values ((select id from public.recipes where slug = 'mo-poulet-basquaise-doux' and owner_id is null), 'generated', 'Toi & Moi', 'Illustration générée par programme pour l’application Toi & Moi', 'Création propre de l’application (aucune œuvre de tiers)', null, 'Utilisation libre dans l’application, y compris commerciale', true, 'Illustration générée de « Poulet basquaise tout doux » (ce n’est pas une photographie)') on conflict do nothing;
