insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('mo-boulettes-boeuf-tomate-coquillettes', 'Boulettes de bœuf à la tomate et coquillettes', 'Des boulettes tendres mijotées dans une sauce tomate, avec des coquillettes : le repas qui met tout le monde d’accord.', array['baby','family']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, 36, array['pieces','regular']::text[], 5, null, 20, 25, array['gluten','eggs']::text[], array['family','classic','iron','batch','freezer']::text[], array['Coupez plus ou moins finement selon ce que votre enfant accepte et sa façon de mâcher.','La dinde hachée remplace le bœuf.']::text[], '48 h au réfrigérateur dans un récipient fermé.', 'Les boulettes en sauce se congèlent jusqu’à 2 mois (décongélation au réfrigérateur, réchauffage à cœur) ; les coquillettes se cuisent au moment.', array['Pas de sel ni de sucre dans la part de l’enfant : les adultes salent dans leur assiette.','Viande bien cuite à cœur, sans trace rosée.','Œuf toujours bien cuit : blanc et jaune fermes.','Morceaux fondants qui s’écrasent facilement entre le pouce et l’index ; restez toujours à côté de l’enfant pendant le repas (risque d’étouffement à surveiller jusqu’à 4 ans).']::text[], 'Le bœuf apporte du fer bien assimilé et les pâtes l’énergie : environ 25 g de bœuf par portion pour l’enfant, un repère à ajuster selon l’âge (une vingtaine de grammes vers 1 an, une trentaine vers 2 ans).', 2, array[]::text[], 'hot', '{"baby":"Écrasez les boulettes coupées dans la sauce et servez avec des coquillettes bien cuites ; ne salez pas sa part.","child":"Laissez-le piquer les boulettes avec une fourchette adaptée."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'mo-boulettes-boeuf-tomate-coquillettes' and owner_id is null), 1, 'ground_beef', 'bœuf haché 5 % MG', 400, 'g', null, false) on conflict do nothing;
