insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-boulettes-boeuf-tomate-coquillettes' and owner_id is null), 1, 'Épluchez et hachez très finement l’oignon. Mélangez la moitié avec le bœuf haché, la chapelure et l’œuf, puis formez de petites boulettes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-boulettes-boeuf-tomate-coquillettes' and owner_id is null), 2, 'Faites revenir le reste de l’oignon dans l’huile d’olive 3 minutes, ajoutez les tomates concassées et le basilic, puis déposez les boulettes dans la sauce.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-boulettes-boeuf-tomate-coquillettes' and owner_id is null), 3, 'Couvrez et laissez mijoter 20 minutes à feu doux, jusqu’à ce que les boulettes soient bien cuites à cœur, sans trace rosée ; pendant ce temps, faites cuire les pâtes (coquillettes) 10 minutes dans l’eau bouillante.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'mo-boulettes-boeuf-tomate-coquillettes' and owner_id is null), 4, 'Pour l’enfant, coupez les boulettes en quatre et mélangez-les aux coquillettes et à la sauce.') on conflict do nothing;
