insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-parmentier-de-cabillaud', 'Parmentier de cabillaud gratiné', 'Un poisson tout doux caché sous une purée maison dorée, pour réconcilier les petits avec le poisson.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['mashed','regular']::text[], 4, null, 25, 35, array['fish','milk']::text[], array['classic','protein','complete','batch','family']::text[], array['Remplacez le cabillaud par du merlu ou du colin selon l’arrivage.','Ajoutez une carotte cuite écrasée dans la purée pour plus de couleur.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle très bien en portions, jusqu’à 2 mois. Décongelez une nuit au réfrigérateur, puis réchauffez au four ou au micro-ondes jusqu’à ce que ce soit bien chaud à cœur.', array['Poisson cuit à cœur (chair opaque qui s’effeuille) ; retirez soigneusement toutes les arêtes.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).','Choisissez des fromages au lait pasteurisé : pas de fromage au lait cru avant 5 ans.']::text[], 'Un poisson maigre riche en protéines, une purée de pommes de terre et un peu de fromage pour le calcium.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 1, 'white_fish', 'filet de cabillaud ou de colin', 400, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 2, 'potato', 'pomme de terre', 800, 'g', null, false) on conflict do nothing;
