insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 5, 'emmental', 'emmental en bloc (râpé à la maison)', 40, 'g', 'râpé', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 6, 'parsley', 'persil', 1, 'cs', 'ciselé', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 1, 'Épluchez les pommes de terre, coupez-les en morceaux et faites-les cuire 20 minutes dans une grande casserole d’eau frémissante, jusqu’à ce qu’elles soient très tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 2, 'Pendant ce temps, posez le cabillaud dans une sauteuse, couvrez d’eau froide et portez à petits frémissements 8 minutes : la chair doit être opaque et s’effeuiller facilement. Égouttez, puis émiettez le poisson en vérifiant qu’il ne reste aucune arête.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 3, 'Écrasez les pommes de terre avec le lait chaud et le beurre pour obtenir une purée souple.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 4, 'Préchauffez le four à 200 °C. Mélangez le poisson émietté avec le persil, étalez-le dans un plat à gratin, recouvrez de purée et parsemez d’emmental.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 5, 'Faites gratiner 15 minutes, jusqu’à ce que le dessus soit bien doré.') on conflict do nothing;
insert into public.recipe_photos (recipe_id, kind, source, author, license, url, rights, generated, alt) values ((select id from public.recipes where slug = 'en-parmentier-de-cabillaud' and owner_id is null), 'generated', 'Toi & Moi', 'Illustration générée par programme pour l’application Toi & Moi', 'Création propre de l’application (aucune œuvre de tiers)', null, 'Utilisation libre dans l’application, y compris commerciale', true, 'Illustration générée de « Parmentier de cabillaud gratiné » (ce n’est pas une photographie)') on conflict do nothing;
