insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-boulettes-merlu-puree-carottes', 'Boulettes de merlu et purée de carottes', 'De petites boulettes moelleuses à attraper à la main, servies sur une purée orange toute douce.', array['child']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 72, array['mashed','pieces']::text[], 4, null, 25, 25, array['gluten','eggs','fish','milk']::text[], array['classic','protein','finger','picky','vegetables']::text[], array['Pour des boulettes encore plus tendres, ajoutez 1 cuillerée à soupe de fromage frais dans la farce.','Le cabillaud ou le colin conviennent aussi.']::text[], '24 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Les boulettes cuites se congèlent 2 mois, la purée aussi. Décongelez au réfrigérateur, puis réchauffez à la poêle ou au micro-ondes jusqu’à ce que ce soit bien chaud.', array['Poisson cuit à cœur (chair opaque qui s’effeuille) ; retirez soigneusement toutes les arêtes.','Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Du poisson, des légumes et des pommes de terre dans une même assiette.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
