insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-boulettes-merlu-puree-carottes' and owner_id is null), 1, 'Épluchez les pommes de terre et les carottes, coupez-les en morceaux et faites-les cuire 20 minutes à l’eau, jusqu’à ce qu’elles soient très tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-boulettes-merlu-puree-carottes' and owner_id is null), 2, 'Vérifiez qu’il ne reste aucune arête dans le merlu, puis hachez-le finement au couteau ou au mixeur. Ajoutez l’œuf, la chapelure et le persil, mélangez et formez une vingtaine de petites boulettes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-boulettes-merlu-puree-carottes' and owner_id is null), 3, 'Faites chauffer l’huile dans une poêle et faites dorer les boulettes 10 minutes à feu moyen en les retournant souvent : elles doivent être fermes et bien cuites au centre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-boulettes-merlu-puree-carottes' and owner_id is null), 4, 'Écrasez les légumes avec le lait chaud et servez les boulettes sur la purée.') on conflict do nothing;
