insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-poulet-haricots-verts-riz', 'Émincé de poulet, haricots verts et riz', 'Un poulet tendre en petits morceaux, des haricots fondants et du riz : l’assiette simple qui plaît à coup sûr.', array['child']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 72, array['pieces']::text[], 4, null, 10, 20, array['milk']::text[], array['classic','protein','vegetables','complete','quick']::text[], array['Remplacez les haricots verts par des petits pois ou des brocolis.','Un filet de jus de citron réveille le plat pour les grands.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle 2 mois en portions (le riz devient un peu plus ferme). Décongelez au réfrigérateur et réchauffez avec une cuillerée d’eau jusqu’à ce que ce soit bien chaud.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).','Coupez les haricots verts en petits tronçons bien cuits pour les plus jeunes.']::text[], 'Une volaille maigre, un légume vert et un féculent pour un repas équilibré.', 2, array['summer','autumn']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
