insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-poulet-haricots-verts-riz' and owner_id is null), 3, 'Coupez le poulet en petites lamelles. Faites-les dorer 8 minutes dans l’huile avec la gousse d’ail écrasée : aucune trace rosée ne doit rester au centre.') on conflict do nothing;
