insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-gratin-courgettes-fondant', 'Gratin de courgettes fondant', 'Des courgettes moelleuses prises dans une crème dorée au fromage, comme chez mamie.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 35, array['eggs','milk']::text[], array['classic','vegetables','calcium','budget','vegetarian','family']::text[], array['Ajoutez 100 g de riz cuit pour en faire un plat complet.','Servez en accompagnement d’une viande ou d’un poisson.']::text[], '48 h au réfrigérateur, filmé ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Congélation possible 1 mois, mais la texture devient plus aqueuse. Décongelez au réfrigérateur et réchauffez au four.', array['Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.','Choisissez des fromages au lait pasteurisé : pas de fromage au lait cru avant 5 ans.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un légume d’été doux, des œufs et du fromage pour les protéines et le calcium.', 1, array['summer']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
