insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-gratin-chou-fleur-bechamel', 'Gratin de chou-fleur doré au fromage', 'Le chou-fleur nappé d’une béchamel onctueuse et gratiné, la recette qui convertit les plus méfiants.', array['child']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 72, array['regular']::text[], 4, null, 15, 40, array['gluten','milk']::text[], array['classic','vegetables','calcium','picky','budget','vegetarian']::text[], array['Mélangez moitié chou-fleur, moitié brocoli pour varier les couleurs.','Ajoutez des dés de jambon pour un plat unique.']::text[], '48 h au réfrigérateur, filmé ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle 2 mois en portions. Décongelez une nuit au réfrigérateur, puis réchauffez au four à 180 °C.', array['Choisissez des fromages au lait pasteurisé : pas de fromage au lait cru avant 5 ans.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un légume de la famille des choux, du lait et du fromage pour le calcium.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
