insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-gratin-chou-fleur-bechamel' and owner_id is null), 2, 'Préparez la béchamel : faites fondre le beurre, ajoutez la farine et remuez 1 minute, puis versez le lait petit à petit en fouettant. Laissez épaissir 8 minutes à feu doux, ajoutez la muscade.') on conflict do nothing;
