insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-omelette-pommes-de-terre', 'Omelette moelleuse aux pommes de terre', 'Une grosse omelette dorée garnie de pommes de terre fondantes, à couper en parts comme un gâteau.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['pieces','regular']::text[], 4, null, 10, 25, array['eggs','milk']::text[], array['classic','protein','complete','quick','budget','vegetarian','family']::text[], array['Ajoutez des dés de courgette ou des épinards avec les pommes de terre.','Servez froide en parts, pour un pique-nique.']::text[], '24 h au réfrigérateur, filmée ; à manger froide ou réchauffée une seule fois.', 'Congélation déconseillée : les œufs deviennent caoutchouteux et les pommes de terre farineuses.', array['Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Des œufs pour les protéines et des pommes de terre pour l’énergie.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
