insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-soupe-legumes-du-marche', 'Soupe de légumes du marché', 'Une soupe veloutée et réconfortante, à boire au bol les soirs d’hiver.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['smooth']::text[], 4, 'bols', 15, 30, array['milk']::text[], array['classic','vegetables','batch','freezer','fiber','budget','vegetarian','family']::text[], array['Ajoutez une poignée de vermicelles pour une soupe plus nourrissante.','Servez avec un morceau de fromage et du pain pour un dîner complet.']::text[], '48 h au réfrigérateur dans un récipient fermé ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle très bien, jusqu’à 3 mois, en portions. Décongelez au réfrigérateur ou directement à feu doux dans une casserole.', array['Vérifiez la température avant de servir : une soupe trop chaude brûle facilement la bouche des petits.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un bol de légumes variés, riche en fibres et en eau.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
