insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-veloute-potiron-doux', 'Velouté de potiron tout doux', 'Un velouté orange, sucré naturellement et onctueux, qui sent bon l’automne.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['smooth']::text[], 4, 'bols', 15, 25, array['milk']::text[], array['classic','vegetables','batch','freezer','budget','vegetarian','family']::text[], array['Le potimarron peut se cuire avec la peau : il suffit de bien le laver.','Ajoutez un carré de fromage frais au moment de mixer pour plus d’onctuosité.']::text[], '48 h au réfrigérateur dans un récipient fermé ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle 3 mois. Décongelez au réfrigérateur, réchauffez doucement en remuant et mixez de nouveau si besoin.', array['Vérifiez la température avant de servir.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un légume orange riche en bêta-carotène, avec un peu de lait pour le calcium.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
