insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-croque-monsieur-maison', 'Croque-monsieur maison au four', 'Le croque-monsieur doré et filant, préparé à la maison en quelques minutes.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 10, 10, array['gluten','milk']::text[], array['classic','quick','picky','budget','family']::text[], array['Version végétarienne : remplacez le jambon par de fines rondelles de tomate.','Choisissez un jambon cuit de qualité, découenné et réduit en sel.']::text[], 'À déguster tout de suite ; les restes se gardent 24 h au réfrigérateur et se réchauffent au four.', 'Se congèle cru, avant cuisson, jusqu’à 1 mois. Faites-le cuire sans décongeler, en ajoutant 5 minutes au four.', array['Choisissez des fromages au lait pasteurisé : pas de fromage au lait cru avant 5 ans.','Laissez tiédir : le fromage fondu reste très chaud.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un plat plaisir à compléter par une crudité ou une soupe et un fruit.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
