insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-croque-monsieur-maison' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Beurrez légèrement les tranches de pain de mie sur une face.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-croque-monsieur-maison' and owner_id is null), 2, 'Posez 4 tranches sur une plaque, face beurrée en dessous. Garnissez chacune d’une tranche de jambon et de la moitié de l’emmental, puis refermez avec les autres tranches, face beurrée au-dessus.') on conflict do nothing;
