insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-hachis-parmentier-familial', 'Hachis parmentier familial', 'Le grand classique du dimanche : une viande mijotée et une purée maison bien dorée.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['mashed','regular']::text[], 6, null, 25, 45, array['milk']::text[], array['classic','protein','iron','batch','freezer','complete','budget','family']::text[], array['Remplacez la moitié des pommes de terre par de la patate douce.','Une version végétarienne se prépare avec des lentilles cuites à la place de la viande.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle très bien, jusqu’à 3 mois, en portions. Décongelez une nuit au réfrigérateur, puis réchauffez au four jusqu’à ce que ce soit bien chaud à cœur.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Choisissez des fromages au lait pasteurisé : pas de fromage au lait cru avant 5 ans.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Une viande riche en fer, des légumes cachés dans la sauce et une purée pour l’énergie.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
