insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-hachis-parmentier-familial' and owner_id is null), 1, 'Épluchez les pommes de terre, coupez-les en morceaux et faites-les cuire 20 minutes à l’eau frémissante. Écrasez-les avec le lait chaud et le beurre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-hachis-parmentier-familial' and owner_id is null), 2, 'Pendant ce temps, hachez l’oignon et râpez finement les carottes. Faites-les revenir 5 minutes dans une poêle, ajoutez le bœuf et le thym et faites cuire 10 minutes en émiettant la viande : elle ne doit plus être rosée.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-hachis-parmentier-familial' and owner_id is null), 3, 'Préchauffez le four à 200 °C. Étalez la viande dans un plat, recouvrez de purée et parsemez d’emmental.') on conflict do nothing;
