insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-lasagnes-legumes-ricotta', 'Lasagnes aux légumes et à la ricotta', 'Des couches fondantes de légumes du soleil, de sauce tomate et de ricotta, pour un plat végétarien généreux.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 6, null, 30, 50, array['gluten','eggs','milk']::text[], array['classic','vegetables','batch','freezer','calcium','vegetarian','family']::text[], array['Glissez une couche d’épinards hachés pour encore plus de vert.','Mixez la sauce si votre enfant trie les légumes.']::text[], '48 h au réfrigérateur, filmées ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèlent 3 mois, cuites et en portions. Décongelez au réfrigérateur et réchauffez au four à 180 °C en couvrant de papier aluminium.', array['Choisissez des fromages au lait pasteurisé : pas de fromage au lait cru avant 5 ans.','Laissez tiédir avant de servir : la sauce et le fromage gardent la chaleur.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Des légumes variés, des pâtes et des fromages frais pour un plat complet sans viande.', 2, array['summer','autumn']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
