insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-lasagnes-legumes-ricotta' and owner_id is null), 1, 'Coupez la courgette et l’aubergine en petits dés, émincez l’oignon et l’ail.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-lasagnes-legumes-ricotta' and owner_id is null), 2, 'Faites revenir l’oignon et l’ail dans l’huile, ajoutez les légumes et laissez cuire 10 minutes. Versez les tomates concassées et le basilic ciselé, puis laissez mijoter 15 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-lasagnes-legumes-ricotta' and owner_id is null), 3, 'Préchauffez le four à 180 °C. Dans un plat, alternez sauce aux légumes, feuilles de lasagne et cuillerées de ricotta, en terminant par la sauce.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-lasagnes-legumes-ricotta' and owner_id is null), 4, 'Couvrez de mozzarella coupée en tranches et enfournez 35 minutes : les lasagnes doivent être tendres sous la pointe d’un couteau.') on conflict do nothing;
