insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-riz-au-lait-vanille', 'Riz au lait crémeux de grand-mère', 'Le dessert de grand-mère, crémeux et parfumé, qui embaume toute la cuisine.', array['child']::text[], array['dessert','snack']::text[], array[]::text[], 24, 72, array['mashed']::text[], 6, 'ramequins', 5, 40, array['milk']::text[], array['classic','calcium','make_ahead','budget','vegetarian']::text[], array['Ajoutez un peu de zeste de citron ou de cannelle.','Réduisez le sucre à 30 g : la vanille apporte déjà de la douceur.']::text[], '3 jours au réfrigérateur, ramequins filmés.', 'Congélation déconseillée : le riz durcit et le lait se sépare à la décongélation.', array['Dessert sucré : à proposer de temps en temps, en fin de repas.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un dessert lacté qui apporte du calcium et de l’énergie.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
