insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-riz-au-lait-vanille' and owner_id is null), 2, 'Portez le lait à frémissement avec la vanille dans une casserole à fond épais.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-riz-au-lait-vanille' and owner_id is null), 3, 'Versez le riz en pluie et laissez cuire 35 minutes à feu très doux, en remuant souvent pour qu’il n’attache pas, jusqu’à ce qu’il soit très fondant.') on conflict do nothing;
