insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-compote-pommes-poires-cannelle', 'Compote maison pommes-poires à la cannelle', 'Une compote sans sucre ajouté, douce et parfumée, à préparer en grande quantité.', array['child']::text[], array['dessert','snack']::text[], array[]::text[], 24, 72, array['smooth','mashed']::text[], 6, 'pots', 15, 20, array[]::text[], array['classic','compote','batch','freezer','fiber','budget','vegetarian']::text[], array['Remplacez les poires par des coings, des prunes ou de la rhubarbe selon la saison.','Choisissez des pommes sucrées (golden, gala) : aucun sucre n’est nécessaire.']::text[], '4 jours au réfrigérateur dans un bocal fermé.', 'Se congèle très bien, jusqu’à 3 mois, en petits pots. Décongelez une nuit au réfrigérateur.', array['Fruits crus avant 4 ans : préférez-les cuits en compote ou râpés finement (risque d’étouffement).']::text[], 'Des fruits cuits, riches en fibres, sans sucre ajouté.', 1, array['autumn','winter']::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-compote-pommes-poires-cannelle' and owner_id is null), 1, 'apple', 'pomme', 4, 'u', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-compote-pommes-poires-cannelle' and owner_id is null), 2, 'pear', 'poire', 2, 'u', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-compote-pommes-poires-cannelle' and owner_id is null), 3, 'cinnamon', 'cannelle', 1, 'pincee', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-compote-pommes-poires-cannelle' and owner_id is null), 1, 'Épluchez les pommes et les poires, retirez le cœur et les pépins, puis coupez-les en morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-compote-pommes-poires-cannelle' and owner_id is null), 2, 'Mettez les fruits dans une casserole avec un fond d’eau et la cannelle. Couvrez et laissez cuire 20 minutes à feu doux, jusqu’à ce qu’ils soient très tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-compote-pommes-poires-cannelle' and owner_id is null), 3, 'Écrasez à la fourchette pour une compote rustique ou mixez pour une texture lisse. Laissez refroidir.') on conflict do nothing;
