insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-crepes-du-gouter', 'Crêpes fines du goûter', 'Des crêpes légères et dorées, à rouler avec de la compote ou un peu de confiture.', array['child','family']::text[], array['snack','breakfast','dessert']::text[], array[]::text[], 24, 120, array['regular']::text[], 12, 'crêpes', 10, 25, array['gluten','eggs','milk']::text[], array['classic','make_ahead','budget','vegetarian','family']::text[], array['Garnissez de compote sans sucre ajouté, de banane écrasée ou d’un peu de fromage blanc.','Remplacez un quart de la farine par de la farine de sarrasin.']::text[], '48 h au réfrigérateur, filmées ; réchauffez à la poêle.', 'Se congèlent 2 mois, séparées par du papier cuisson. Décongelez à température ambiante 30 minutes ou directement à la poêle.', array['Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.','Laissez tiédir avant de garnir pour l’enfant.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un goûter à base de farine, d’œufs et de lait, à garnir de fruits.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
