insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-crepes-du-gouter' and owner_id is null), 6, 'vanilla', 'extrait de vanille', 1, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-crepes-du-gouter' and owner_id is null), 1, 'Versez la farine et le sucre dans un saladier, creusez un puits et cassez-y les œufs.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-crepes-du-gouter' and owner_id is null), 2, 'Ajoutez le lait petit à petit en fouettant pour éviter les grumeaux, puis le beurre fondu et la vanille. Laissez reposer la pâte 30 minutes si vous avez le temps.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-crepes-du-gouter' and owner_id is null), 3, 'Faites chauffer une poêle légèrement graissée, versez une petite louche de pâte et étalez-la. Faites cuire environ 1 minute de chaque côté : la crêpe doit être dorée et la pâte bien cuite.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-crepes-du-gouter' and owner_id is null), 4, 'Gardez les crêpes au chaud sous un torchon jusqu’au goûter.') on conflict do nothing;
