insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-quatre-quarts-citron', 'Quatre-quarts au citron', 'Le gâteau tout simple au bon goût de beurre, parfumé d’un zeste de citron.', array['child','family']::text[], array['snack','dessert']::text[], array[]::text[], 24, 120, array['regular']::text[], 8, 'parts', 15, 40, array['gluten','eggs','milk']::text[], array['classic','make_ahead','budget','vegetarian','family']::text[], array['Version moins sucrée : le gâteau reste moelleux avec 100 g de sucre.','Ajoutez des pépites de chocolat pour les grands.']::text[], '4 jours à température ambiante, emballé dans un torchon ou une boîte.', 'Se congèle 2 mois, en tranches emballées. Décongelez 1 heure à température ambiante.', array['Gâteau sucré : une part au goûter, avec un fruit et un produit laitier.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un gâteau maison simple, sans additifs, à servir en part raisonnable.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
