insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-quatre-quarts-citron' and owner_id is null), 6, 'lemon', 'citron', 1, 'u', 'zeste', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-quatre-quarts-citron' and owner_id is null), 1, 'Préchauffez le four à 170 °C et beurrez un moule à cake.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-quatre-quarts-citron' and owner_id is null), 2, 'Fouettez le beurre mou avec le sucre jusqu’à ce que le mélange blanchisse, puis ajoutez les œufs un à un et le zeste de citron.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-quatre-quarts-citron' and owner_id is null), 3, 'Incorporez la farine et la levure, mélangez juste ce qu’il faut pour obtenir une pâte lisse.') on conflict do nothing;
