insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-muffins-banane-cannelle', 'Muffins moelleux à la banane', 'Des muffins très moelleux sucrés surtout par la banane, parfaits pour le goûter ou la boîte à goûter.', array['child','family']::text[], array['snack','breakfast']::text[], array[]::text[], 24, 120, array['regular']::text[], 12, 'muffins', 15, 20, array['gluten','eggs','milk']::text[], array['classic','lunchbox','freezer','budget','vegetarian','family']::text[], array['Ajoutez une poignée de myrtilles ou des flocons d’avoine.','Plus les bananes sont mûres, moins le sucre est utile.']::text[], '3 jours dans une boîte hermétique à température ambiante.', 'Se congèlent 2 mois. Décongelez 1 heure à température ambiante ou quelques secondes au micro-ondes.', array['Pour les plus jeunes, coupez le muffin en morceaux et restez près de l’enfant (risque d’étouffement).']::text[], 'Un goûter à base de fruit, de farine et d’œufs, moins sucré qu’un gâteau classique.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
