insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-pain-perdu-cannelle', 'Pain perdu doré à la cannelle', 'La recette anti-gaspi qui transforme le pain rassis en goûter doré et fondant.', array['child','family']::text[], array['snack','breakfast']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 10, array['gluten','eggs','milk']::text[], array['classic','quick','budget','vegetarian','family']::text[], array['Le pain de mie ou la brioche rassise conviennent aussi.','Servez sans sucre ajouté, avec une banane écrasée.']::text[], 'À déguster tout de suite ; se garde 24 h au réfrigérateur et se réchauffe à la poêle.', 'Se congèle 1 mois une fois cuit. Réchauffez sans décongeler au grille-pain ou à la poêle.', array['Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un goûter nourrissant à base de pain, de lait et d’œufs.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
