insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-pain-perdu-cannelle' and owner_id is null), 1, 'Coupez la baguette en tranches épaisses d’environ 2 cm.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-pain-perdu-cannelle' and owner_id is null), 2, 'Battez les œufs avec le lait, le sucre et la cannelle dans une assiette creuse. Trempez-y les tranches de pain quelques secondes de chaque côté.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-pain-perdu-cannelle' and owner_id is null), 3, 'Faites fondre le beurre dans une poêle et faites dorer les tranches 3 à 4 minutes de chaque côté, à feu moyen : l’intérieur doit être pris, sans œuf coulant.') on conflict do nothing;
