insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-gateau-au-yaourt', 'Gâteau au yaourt de mon enfance', 'Le gâteau qu’on mesure avec le pot de yaourt : idéal pour cuisiner avec les enfants.', array['child','family']::text[], array['snack','dessert']::text[], array[]::text[], 24, 120, array['regular']::text[], 8, 'parts', 15, 35, array['gluten','eggs','milk']::text[], array['classic','budget','make_ahead','vegetarian','family']::text[], array['Ajoutez des dés de pomme ou de poire dans la pâte.','Remplacez la vanille par un zeste d’orange.']::text[], '4 jours dans une boîte à température ambiante.', 'Se congèle 2 mois, en parts emballées. Décongelez 1 heure à température ambiante.', array['Une part au goûter, accompagnée d’un fruit.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un gâteau familial simple, avec un produit laitier dans la pâte.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
