insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-gateau-au-yaourt' and owner_id is null), 1, 'Préchauffez le four à 180 °C et huilez un moule rond.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-gateau-au-yaourt' and owner_id is null), 2, 'Videz le yaourt dans un saladier et gardez le pot pour mesurer. Ajoutez le sucre, les œufs, l’huile et la vanille, puis mélangez.') on conflict do nothing;
