insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-sables-vanille', 'Petits sablés à la vanille', 'Des biscuits croustillants à découper à l’emporte-pièce, pour un goûter fait maison.', array['child']::text[], array['snack']::text[], array[]::text[], 36, 72, array['regular']::text[], 25, 'sablés', 20, 12, array['gluten','eggs','milk']::text[], array['classic','make_ahead','lunchbox','budget','vegetarian']::text[], array['Remplacez 30 g de farine par du cacao non sucré.','Laissez les enfants découper et décorer les sablés.']::text[], '1 semaine dans une boîte en métal, à l’abri de l’humidité.', 'La pâte crue se congèle 2 mois en boule filmée ; décongelez-la une nuit au réfrigérateur avant de l’étaler. Les sablés cuits se congèlent aussi 2 mois.', array['Ne laissez pas goûter la pâte crue (œuf cru, farine crue).','Surveillez l’enfant pendant qu’il mange : biscuit sec et friable avant 4 ans.']::text[], 'Un biscuit maison à proposer avec un fruit et un verre de lait.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'en-sables-vanille' and owner_id is null), 1, 'flour', 'farine de blé', 200, 'g', null, false) on conflict do nothing;
