insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-sables-vanille' and owner_id is null), 1, 'Mélangez du bout des doigts la farine et le beurre mou jusqu’à obtenir un sable grossier.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-sables-vanille' and owner_id is null), 2, 'Ajoutez le sucre, l’œuf et la vanille, puis rassemblez la pâte en boule sans trop la travailler. Laissez-la reposer 30 minutes au réfrigérateur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-sables-vanille' and owner_id is null), 3, 'Préchauffez le four à 180 °C. Étalez la pâte sur 5 mm d’épaisseur et découpez des formes à l’emporte-pièce.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-sables-vanille' and owner_id is null), 4, 'Disposez les sablés sur une plaque recouverte de papier cuisson et enfournez 12 minutes, jusqu’à ce que les bords soient juste dorés.') on conflict do nothing;
