insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-boulettes-boeuf-tomate-coquillettes', 'Petites boulettes de bœuf en sauce tomate et coquillettes', 'Des boulettes tendres mijotées dans une sauce tomate douce, avec des coquillettes pour saucer.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['pieces']::text[], 4, null, 20, 25, array['gluten','eggs']::text[], array['classic','protein','iron','batch','complete','budget','family']::text[], array['Mixez la sauce si votre enfant n’aime pas les morceaux d’oignon.','Les boulettes peuvent se préparer avec moitié bœuf, moitié veau.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Les boulettes en sauce se congèlent 3 mois. Décongelez une nuit au réfrigérateur et réchauffez à feu doux jusqu’à ce que ce soit bien chaud à cœur.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Une viande riche en fer, une sauce tomate et des pâtes pour un repas complet.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
