insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-petits-flans-carottes', 'Petits flans de carottes au fromage', 'Des flans orange tout doux, servis en ramequins, pour faire aimer les carottes.', array['child']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 72, array['mashed']::text[], 4, 'ramequins', 15, 40, array['eggs','milk']::text[], array['vegetables','calcium','picky','budget','vegetarian']::text[], array['Servez avec du riz ou une purée pour un repas complet.','Remplacez les carottes par du potiron ou des brocolis.']::text[], '48 h au réfrigérateur, filmés ; à servir tièdes ou réchauffés une seule fois.', 'Congélation déconseillée : les flans deviennent granuleux et rendent de l’eau.', array['Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.','Choisissez des fromages au lait pasteurisé : pas de fromage au lait cru avant 5 ans.','Carottes bien cuites et mixées : aucun risque de morceau dur (étouffement).']::text[], 'Un légume orange, des œufs et du fromage dans une texture fondante.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
