insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-petits-flans-carottes' and owner_id is null), 1, 'Épluchez les carottes, coupez-les en rondelles et faites-les cuire 15 minutes à l’eau ou à la vapeur, jusqu’à ce qu’elles soient très tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-petits-flans-carottes' and owner_id is null), 2, 'Préchauffez le four à 170 °C. Mixez les carottes avec les œufs, le lait, l’emmental et éventuellement le cumin.') on conflict do nothing;
