insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-truite-puree-patate-douce', 'Truite au four et purée de patate douce', 'Une truite délicate et une purée orangée légèrement sucrée, pour un repas de poisson qui change.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['mashed','pieces']::text[], 4, null, 15, 25, array['fish','milk']::text[], array['protein','complete','family']::text[], array['Le saumon ou le merlu remplacent la truite.','Mélangez moitié patate douce, moitié pomme de terre si le goût sucré déplaît.']::text[], '24 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'La purée se congèle 3 mois ; le poisson cuit se congèle 1 mois. Décongelez au réfrigérateur et réchauffez jusqu’à ce que ce soit bien chaud.', array['Poisson cuit à cœur (chair opaque qui s’effeuille) ; retirez soigneusement toutes les arêtes.','Variez les espèces de poisson au fil des semaines et alternez poissons gras et maigres, deux fois par semaine.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un poisson gras riche en oméga-3 et une purée riche en bêta-carotène.', 2, array['autumn','winter','spring']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
