insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-truite-puree-patate-douce' and owner_id is null), 1, 'Épluchez les patates douces, coupez-les en cubes et faites-les cuire 20 minutes à la vapeur ou à l’eau, jusqu’à ce qu’elles soient fondantes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-truite-puree-patate-douce' and owner_id is null), 2, 'Préchauffez le four à 190 °C. Posez la truite sur une plaque, arrosez d’huile et de quelques gouttes de citron, puis enfournez 15 minutes : la chair doit être opaque et se détacher en lamelles.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-truite-puree-patate-douce' and owner_id is null), 3, 'Écrasez les patates douces avec le beurre et le lait chaud.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-truite-puree-patate-douce' and owner_id is null), 4, 'Effeuillez la truite en retirant la peau et toutes les arêtes, puis servez-la sur la purée.') on conflict do nothing;
