insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-mini-pizzas-jambon-mozzarella', 'Mini-pizzas jambon-mozzarella', 'De petites pizzas à garnir soi-même : le repas du samedi soir que les enfants préparent avec plaisir.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 20, 15, array['gluten','milk']::text[], array['classic','quick','picky','budget','family']::text[], array['Ajoutez des dés de courgette, de poivron ou de champignons.','Version végétarienne : remplacez le jambon par des légumes.']::text[], '24 h au réfrigérateur ; réchauffez au four pour garder le croustillant.', 'Se congèlent 2 mois une fois cuites. Réchauffez sans décongeler 10 minutes au four à 200 °C.', array['Choisissez des fromages au lait pasteurisé : pas de fromage au lait cru avant 5 ans.','Laissez tiédir : le fromage fondu reste brûlant.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un repas plaisir à compléter par une crudité et un fruit.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
