insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('en-dinde-petits-pois-carottes', 'Dinde aux petits pois et carottes', 'Une escalope tendre mijotée avec des petits pois et des carottes, comme une jardinière d’autrefois.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['pieces']::text[], 4, null, 15, 25, array['milk']::text[], array['classic','protein','vegetables','complete','budget','family']::text[], array['Remplacez la dinde par du poulet.','Écrasez légèrement les petits pois pour les plus jeunes.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle 3 mois en portions. Décongelez au réfrigérateur et réchauffez à feu doux avec un peu d’eau.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Une volaille maigre et trois légumes dans une même cocotte.', 1, array['spring','summer']::text[], 'hot', '{}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
