insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-dinde-petits-pois-carottes' and owner_id is null), 1, 'Épluchez les carottes et les pommes de terre, coupez-les en petits dés. Émincez l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-dinde-petits-pois-carottes' and owner_id is null), 2, 'Coupez la dinde en petits morceaux et faites-les dorer 5 minutes dans le beurre avec l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'en-dinde-petits-pois-carottes' and owner_id is null), 3, 'Ajoutez les carottes, les pommes de terre, les petits pois et le thym, puis un grand verre d’eau. Couvrez et laissez mijoter 20 minutes, jusqu’à ce que les légumes soient tendres.') on conflict do nothing;
