insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-cuisses-poulet-roties-pommes-de-terre', 'Poulet rôti du dimanche et pommes de terre fondantes', 'Des cuisses de poulet dorées et des pommes de terre confites dans le jus : le repas de famille par excellence.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['mashed','pieces','regular']::text[], 4, null, 15, 50, array[]::text[], array['classic','protein','complete','family']::text[], array['Ajoutez des carottes en tronçons dans le plat.','Un poulet entier de 1,5 kg demande environ 1 h 15 de cuisson.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'La viande désossée se congèle 3 mois ; les pommes de terre se congèlent mal. Décongelez au réfrigérateur et réchauffez jusqu’à ce que ce soit bien chaud.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Retirez la peau, les os et les cartilages de la part des enfants.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Une volaille et des pommes de terre, à compléter par un légume vert.', 2, array[]::text[], 'hot', '{"baby":"Avant tout salage, prélevez un peu de poulet sans peau et de pomme de terre : mixez finement vers 8 mois, écrasez à la fourchette vers 10 mois, puis proposez de petits morceaux tendres après 1 an.","child":"Viande détachée de l’os et coupée en morceaux ; pommes de terre servies avec un peu de jus."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'fa-cuisses-poulet-roties-pommes-de-terre' and owner_id is null), 1, 'chicken_thigh', 'cuisses de poulet', 4, 'u', null, false) on conflict do nothing;
