insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-cuisses-poulet-roties-pommes-de-terre' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Lavez les pommes de terre et coupez les plus grosses en deux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-cuisses-poulet-roties-pommes-de-terre' and owner_id is null), 2, 'Disposez les cuisses de poulet et les pommes de terre dans un grand plat, ajoutez les gousses d’ail, le thym et l’huile, puis mélangez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-cuisses-poulet-roties-pommes-de-terre' and owner_id is null), 3, 'Enfournez 50 minutes en arrosant de jus à mi-cuisson : la peau doit être dorée, le jus qui s’écoule de la viande doit être clair, sans trace rosée près de l’os.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-cuisses-poulet-roties-pommes-de-terre' and owner_id is null), 4, 'Prélevez la part du bébé avant de saler, puis salez légèrement le reste du plat à votre goût.') on conflict do nothing;
