insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-boeuf-carottes-mijote', 'Bœuf carottes mijoté comme autrefois', 'Un bœuf fondant qui mijote doucement avec des carottes sucrées, encore meilleur réchauffé le lendemain.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['mashed','pieces','regular']::text[], 6, null, 20, 150, array['gluten']::text[], array['classic','iron','protein','batch','freezer','family']::text[], array['Servez avec des pommes de terre vapeur, des pâtes fraîches ou une purée.','À l’autocuiseur, comptez environ 50 minutes.']::text[], '3 jours au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle très bien, jusqu’à 3 mois, avec sa sauce. Décongelez une nuit au réfrigérateur, puis réchauffez à feu doux jusqu’à ce que ce soit bien chaud à cœur.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Retirez la feuille de laurier avant de servir.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Une viande rouge riche en fer et des carottes en quantité.', 2, array['autumn','winter']::text[], 'hot', '{"baby":"Avant de saler, prélevez de la viande très fondante et des carottes : mixez avec un peu de jus de cuisson vers 8 mois, puis effilochez finement et écrasez les carottes en grandissant.","child":"Viande effilochée en petits morceaux et carottes fondantes, avec de la sauce."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
