insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-boeuf-carottes-mijote' and owner_id is null), 1, 'Coupez le bœuf en gros cubes, émincez les oignons et l’ail, épluchez les carottes et coupez-les en rondelles épaisses.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-boeuf-carottes-mijote' and owner_id is null), 2, 'Faites dorer la viande 10 minutes dans l’huile, dans une cocotte, puis ajoutez les oignons et l’ail. Saupoudrez de farine et mélangez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-boeuf-carottes-mijote' and owner_id is null), 3, 'Ajoutez les carottes, le thym et le laurier, puis couvrez d’eau à hauteur. Laissez mijoter 2 h 15 à couvert, à feu très doux, jusqu’à ce que la viande se défasse à la fourchette.') on conflict do nothing;
