insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-blanquette-de-veau' and owner_id is null), 1, 'Mettez le veau dans une cocotte, couvrez d’eau froide, portez à ébullition et écumez. Ajoutez les carottes en rondelles, l’oignon, le laurier et le thym, puis laissez cuire 1 h 15 à petits frémissements.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-blanquette-de-veau' and owner_id is null), 2, 'Faites revenir les champignons émincés 5 minutes dans une noix de beurre. Épluchez les pommes de terre et faites-les cuire 25 minutes à la vapeur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-blanquette-de-veau' and owner_id is null), 3, 'Égouttez la viande et les carottes en gardant le bouillon. Faites fondre le reste du beurre, ajoutez la farine, puis versez 60 cl de bouillon en fouettant et laissez épaissir 10 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-blanquette-de-veau' and owner_id is null), 4, 'Remettez la viande, les carottes et les champignons dans la sauce, ajoutez la crème et quelques gouttes de citron, puis réchauffez 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-blanquette-de-veau' and owner_id is null), 5, 'Prélevez la part du bébé avant de saler, puis salez légèrement le reste du plat à votre goût.') on conflict do nothing;
