insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-gratin-dauphinois', 'Gratin dauphinois crémeux', 'Des pommes de terre fondantes cuites lentement dans le lait et la crème, avec une croûte dorée.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m12_18','m18_24','y2_3']::text[], 12, null, array['mashed','pieces','regular']::text[], 6, null, 20, 75, array['milk']::text[], array['classic','calcium','budget','vegetarian','family']::text[], array['Servez avec une viande grillée ou une salade verte.','Ajoutez une couche de poireaux fondus pour une version plus végétale.']::text[], '48 h au réfrigérateur, filmé ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle 2 mois en portions, avec une texture un peu moins fondante. Décongelez au réfrigérateur et réchauffez au four à 170 °C.', array['Le lait de vache en quantité, cuit dans un plat, se propose à partir de 1 an.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un féculent onctueux qui apporte du calcium, à associer à un légume.', 1, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 1 an, prélevez une part avant de saler et écrasez-la à la fourchette ; proposez-la avec un légume vert écrasé.","child":"Une part avec une viande ou un œuf et des haricots verts."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
