insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-gratin-dauphinois' and owner_id is null), 1, 'Préchauffez le four à 160 °C. Frottez un plat à gratin avec la gousse d’ail coupée en deux, puis beurrez-le.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-gratin-dauphinois' and owner_id is null), 2, 'Épluchez les pommes de terre et coupez-les en fines rondelles, sans les rincer.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-gratin-dauphinois' and owner_id is null), 3, 'Faites chauffer le lait avec la crème, la muscade et la feuille de laurier, ajoutez les pommes de terre et laissez cuire 10 minutes en remuant délicatement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-gratin-dauphinois' and owner_id is null), 4, 'Retirez le laurier, versez le tout dans le plat et enfournez 1 h 05 : le dessus doit être doré et la pointe d’un couteau doit traverser les pommes de terre sans résistance.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-gratin-dauphinois' and owner_id is null), 5, 'Prélevez la part du bébé avant de saler, puis salez légèrement le reste du plat à votre goût.') on conflict do nothing;
