insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-pates-bolognaise-maison', 'Pâtes à la bolognaise maison', 'Une sauce qui mijote longtemps avec des légumes cachés, pour des spaghettis comme en Italie.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['mashed','pieces','regular']::text[], 6, null, 15, 45, array['gluten']::text[], array['classic','iron','batch','freezer','complete','budget','family']::text[], array['Ajoutez une courgette râpée dans la sauce.','Servez avec un peu d’emmental râpé.']::text[], '3 jours au réfrigérateur pour la sauce ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'La sauce se congèle très bien, 3 mois, en portions. Décongelez une nuit au réfrigérateur et réchauffez à feu doux jusqu’à ébullition.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Une viande riche en fer, des légumes et des pâtes : un plat complet.', 1, array[]::text[], 'hot', '{"baby":"Avant de saler, prélevez de la sauce et mixez-la avec quelques petites pâtes bien cuites vers 8 mois ; après 1 an, proposez des pâtes courtes nappées de sauce.","child":"Pâtes courtes plus faciles à piquer que les spaghettis, sauce bien mélangée."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
