insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-pates-bolognaise-maison' and owner_id is null), 2, 'Faites revenir les légumes 5 minutes dans l’huile, puis ajoutez le bœuf et faites-le cuire en l’émiettant jusqu’à ce qu’il ne soit plus rosé.') on conflict do nothing;
