insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-chili-doux-familial', 'Chili doux familial', 'Un chili tout en douceur, sans piment, aux haricots rouges et aux épices parfumées.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['mashed','pieces','regular']::text[], 6, null, 15, 40, array[]::text[], array['classic','iron','fiber','batch','freezer','complete','budget','family']::text[], array['Version végétarienne : remplacez le bœuf par des lentilles vertes cuites.','Servez dans des galettes de blé pour changer.']::text[], '3 jours au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle 3 mois sans le riz. Décongelez une nuit au réfrigérateur et réchauffez à feu doux jusqu’à ce que ce soit bien chaud à cœur.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Avant 4 ans, écrasez les grains de maïs et les haricots rouges (risque d’étouffement).','Aucun piment dans la marmite : chacun en ajoute dans son assiette.']::text[], 'Des légumineuses riches en fibres, une viande riche en fer et du riz.', 1, array['autumn','winter']::text[], 'hot', '{"baby":"Prélevez une part avant de saler, sans maïs, et mixez-la avec un peu de riz vers 8 mois ; en grandissant, écrasez bien les haricots et le maïs à la fourchette.","child":"Servi avec le riz et un peu de fromage blanc pour adoucir."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
