insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-chili-doux-familial' and owner_id is null), 1, 'Émincez l’oignon et coupez le poivron en petits dés. Faites-les revenir 5 minutes dans l’huile.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-chili-doux-familial' and owner_id is null), 2, 'Ajoutez le bœuf et faites-le cuire en l’émiettant jusqu’à ce qu’il ne soit plus rosé, puis ajoutez le cumin et le paprika.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-chili-doux-familial' and owner_id is null), 3, 'Versez les tomates concassées, les haricots rouges rincés et le maïs, puis laissez mijoter 30 minutes à couvert.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-chili-doux-familial' and owner_id is null), 4, 'Faites cuire le riz selon le temps indiqué sur le paquet.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-chili-doux-familial' and owner_id is null), 5, 'Prélevez la part du bébé avant de saler, puis salez légèrement le reste du plat à votre goût. Les grands peuvent ajouter du piment dans leur assiette.') on conflict do nothing;
