insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-couscous-poulet-legumes', 'Couscous au poulet et aux légumes', 'Un couscous généreux, doux et parfumé, avec des légumes fondants et un bouillon à verser sur la semoule.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['mashed','pieces','regular']::text[], 6, null, 25, 50, array['gluten']::text[], array['classic','world','vegetables','complete','protein','family']::text[], array['Ajoutez des raisins secs gonflés dans le bouillon pour les grands.','Version végétarienne : doublez les pois chiches et retirez le poulet.']::text[], '48 h au réfrigérateur, semoule et bouillon séparés ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Le bouillon avec la viande et les légumes se congèle 3 mois ; la semoule se prépare au moment. Décongelez au réfrigérateur et portez à ébullition.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Retirez la peau et les os de la part des enfants.','Avant 4 ans, écrasez les pois chiches (risque d’étouffement).']::text[], 'Une volaille, cinq légumes et des légumineuses : un plat très complet.', 2, array['autumn','winter','spring']::text[], 'hot', '{"baby":"Avant de saler, prélevez des légumes, des pois chiches et du poulet sans peau : mixez avec un peu de bouillon et de semoule vers 8 mois, puis écrasez à la fourchette en grandissant.","child":"Semoule bien arrosée de bouillon, légumes et viande coupés en morceaux."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
