insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-couscous-poulet-legumes' and owner_id is null), 1, 'Faites dorer les cuisses de poulet 10 minutes dans l’huile, dans un grand faitout, avec l’oignon émincé et le ras-el-hanout.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-couscous-poulet-legumes' and owner_id is null), 2, 'Ajoutez les carottes et les navets coupés en tronçons, les tomates concassées et 1,5 litre d’eau. Laissez mijoter 25 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-couscous-poulet-legumes' and owner_id is null), 3, 'Ajoutez les courgettes en tronçons et les pois chiches, puis poursuivez la cuisson 15 minutes : le poulet doit se détacher de l’os, sans trace rosée.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-couscous-poulet-legumes' and owner_id is null), 4, 'Préparez la semoule : versez dessus le même volume d’eau bouillante, couvrez 5 minutes, puis égrainez à la fourchette avec un filet d’huile.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-couscous-poulet-legumes' and owner_id is null), 5, 'Prélevez la part du bébé avant de saler, puis salez légèrement le reste du plat à votre goût. Servez la semoule arrosée de bouillon, avec la viande et les légumes.') on conflict do nothing;
