insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-minestrone-legumes', 'Soupe minestrone aux petites pâtes', 'Une grande soupe italienne pleine de légumes, de haricots et de petites pâtes, presque un plat complet.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['smooth','mashed','pieces','regular']::text[], 6, 'bols', 20, 35, array['gluten']::text[], array['classic','world','vegetables','fiber','batch','budget','vegetarian','family']::text[], array['Ajoutez un peu d’emmental râpé dans les bols des grands.','Toutes les saisons conviennent : utilisez les légumes du moment.']::text[], '3 jours au réfrigérateur dans un récipient fermé ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle 3 mois, de préférence sans les pâtes, à ajouter au réchauffage. Décongelez au réfrigérateur et portez à ébullition.', array['Avant 4 ans, écrasez les haricots blancs et vérifiez que les légumes sont bien tendres (risque d’étouffement).','Vérifiez la température avant de servir.']::text[], 'Des légumes variés, des légumineuses et des pâtes pour un repas riche en fibres.', 1, array['summer','autumn']::text[], 'hot', '{"baby":"Avant de saler, prélevez une louche et mixez-la finement vers 8 mois ; à partir de 10 mois, écrasez simplement à la fourchette.","child":"Un grand bol avec du pain, puis un fromage et un fruit."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
