insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'fa-minestrone-legumes' and owner_id is null), 11, 'basil', 'basilic', 6, 'u', 'feuilles', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-minestrone-legumes' and owner_id is null), 1, 'Coupez la carotte, la courgette et les pommes de terre en petits dés, les haricots verts en tronçons. Émincez l’oignon et l’ail.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-minestrone-legumes' and owner_id is null), 2, 'Faites revenir l’oignon et l’ail 3 minutes dans l’huile, ajoutez les légumes et les tomates concassées, puis 1,5 litre d’eau. Laissez cuire 20 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-minestrone-legumes' and owner_id is null), 3, 'Ajoutez les haricots blancs et les petites pâtes, puis poursuivez la cuisson 10 minutes, jusqu’à ce que les pâtes soient tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-minestrone-legumes' and owner_id is null), 4, 'Prélevez la part du bébé avant de saler, puis salez légèrement le reste du plat à votre goût. Parsemez de basilic ciselé au moment de servir.') on conflict do nothing;
