insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-poulet-basquaise', 'Poulet basquaise aux poivrons', 'Un poulet mijoté dans une sauce tomate et poivrons pleine de soleil, servi avec du riz.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['mashed','pieces','regular']::text[], 6, null, 20, 50, array[]::text[], array['classic','protein','vegetables','complete','family']::text[], array['Hors saison, utilisez 800 g de tomates concassées en conserve.','Les grands peuvent relever leur assiette de piment d’Espelette.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle 3 mois sans le riz. Décongelez une nuit au réfrigérateur et réchauffez à feu doux jusqu’à ce que ce soit bien chaud à cœur.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Retirez la peau, les os et la feuille de laurier avant de servir les enfants.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Une volaille et beaucoup de légumes du soleil, avec du riz.', 2, array['summer','autumn']::text[], 'hot', '{"baby":"Avant de saler, prélevez du poulet sans peau et des légumes bien cuits, retirez la peau des poivrons et mixez avec un peu de riz vers 8 mois ; écrasez à la fourchette en grandissant.","child":"Poulet désossé en petits morceaux, sauce sur le riz."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
