insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-poulet-basquaise' and owner_id is null), 1, 'Faites dorer les cuisses de poulet 10 minutes dans l’huile, dans une cocotte, puis réservez-les.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-poulet-basquaise' and owner_id is null), 2, 'Dans la même cocotte, faites revenir les oignons émincés, l’ail et les poivrons en lanières pendant 10 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-poulet-basquaise' and owner_id is null), 3, 'Ajoutez les tomates coupées en dés, le paprika, le thym et le laurier, remettez le poulet, couvrez et laissez mijoter 30 minutes : la viande doit se détacher de l’os, sans trace rosée.') on conflict do nothing;
