insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-saumon-papillote-fondue-poireaux', 'Saumon en papillote et fondue de poireaux', 'Un saumon tout moelleux cuit en papillote sur un lit de poireaux fondants, avec du riz.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['mashed','pieces','regular']::text[], 4, null, 15, 25, array['fish','milk']::text[], array['protein','vegetables','complete','family']::text[], array['La truite ou le cabillaud conviennent aussi.','Remplacez le riz par des pommes de terre vapeur.']::text[], '24 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Congélation possible 1 mois pour le saumon cuit et les poireaux, mais la texture devient plus sèche. Décongelez au réfrigérateur et réchauffez doucement.', array['Poisson cuit à cœur (chair opaque qui s’effeuille) ; retirez soigneusement toutes les arêtes.','Variez les espèces de poisson au fil des semaines et alternez poissons gras et maigres, deux fois par semaine.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un poisson gras riche en oméga-3, un légume doux et du riz.', 3, array['autumn','winter','spring']::text[], 'hot', '{"baby":"Prélevez une part de saumon sans arêtes et de poireaux avant de saler et sans citron : mixez avec du riz vers 8 mois, puis émiettez finement en grandissant.","child":"Saumon émietté sans arêtes, poireaux et riz mélangés."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
