insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-saumon-papillote-fondue-poireaux' and owner_id is null), 1, 'Émincez finement les poireaux et faites-les fondre 15 minutes dans le beurre, à couvert et à feu doux, puis ajoutez la crème.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-saumon-papillote-fondue-poireaux' and owner_id is null), 2, 'Préchauffez le four à 200 °C. Faites cuire le riz selon le temps indiqué sur le paquet.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-saumon-papillote-fondue-poireaux' and owner_id is null), 3, 'Répartissez la fondue de poireaux sur 4 feuilles de papier cuisson, posez un pavé de saumon sur chacune, ajoutez la ciboulette et refermez en papillotes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-saumon-papillote-fondue-poireaux' and owner_id is null), 4, 'Enfournez 15 minutes : la chair doit être opaque à cœur et s’effeuiller facilement. Prélevez la part du bébé avant de saler, puis salez légèrement le reste du plat à votre goût. Les adultes ajoutent un filet de jus de citron.') on conflict do nothing;
