insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-navarin-agneau-printanier', 'Navarin d’agneau printanier', 'Un ragoût d’agneau tendre aux légumes nouveaux, pour fêter l’arrivée du printemps en famille.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['mashed','pieces','regular']::text[], 6, null, 25, 100, array['gluten']::text[], array['classic','iron','protein','vegetables','complete','family']::text[], array['Remplacez l’agneau par du veau pour un goût plus doux.','Ajoutez des haricots verts avec les petits pois.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèle 3 mois. Décongelez une nuit au réfrigérateur et réchauffez à feu doux jusqu’à ce que ce soit bien chaud à cœur.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Retirez la feuille de laurier et les petits os éventuels.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Une viande riche en fer et quatre légumes dans la même cocotte.', 3, array['spring']::text[], 'hot', '{"baby":"Avant de saler, prélevez de la viande très tendre et des légumes : mixez avec un peu de jus vers 8 mois, puis effilochez et écrasez en grandissant.","child":"Viande coupée en petits morceaux, légumes avec la sauce."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
