insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-navarin-agneau-printanier' and owner_id is null), 1, 'Coupez l’agneau en morceaux en retirant l’excès de gras. Faites-le dorer 10 minutes dans l’huile, dans une cocotte, avec l’oignon émincé.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-navarin-agneau-printanier' and owner_id is null), 2, 'Saupoudrez de farine, ajoutez le concentré de tomate, le thym et le laurier, puis couvrez d’eau à hauteur. Laissez mijoter 50 minutes à couvert.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-navarin-agneau-printanier' and owner_id is null), 3, 'Ajoutez les carottes, les navets et les pommes de terre coupés en morceaux, puis poursuivez la cuisson 30 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-navarin-agneau-printanier' and owner_id is null), 4, 'Ajoutez les petits pois 10 minutes avant la fin : la viande doit être fondante et les légumes tendres.') on conflict do nothing;
