insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-ratatouille-mijotee', 'Ratatouille mijotée', 'Les légumes du soleil cuits longuement jusqu’à devenir fondants : un plat qui se partage chaud ou froid.', array['family','baby']::text[], array['lunch','dinner']::text[], array['m6_8','m9_12','m12_18','m18_24','y2_3']::text[], 8, null, array['smooth','mashed','pieces','regular']::text[], 6, null, 25, 50, array[]::text[], array['classic','vegetables','fiber','batch','freezer','budget','vegetarian','family']::text[], array['Servez avec du riz, de la semoule, des pâtes ou un œuf au plat bien cuit.','Encore meilleure le lendemain, froide ou réchauffée.']::text[], '3 jours au réfrigérateur dans un récipient fermé ; se mange froide ou réchauffée une seule fois.', 'Se congèle très bien, 3 mois, en portions. Décongelez au réfrigérateur et réchauffez à feu doux.', array['Retirez les peaux de poivron et de tomate pour les plus jeunes ; légumes bien fondants avant 4 ans (risque d’étouffement).']::text[], 'Cinq légumes d’été riches en fibres et en vitamines.', 1, array['summer']::text[], 'hot', '{"baby":"Avant de saler, prélevez une part et mixez-la finement vers 8 mois (retirez les peaux de poivron) ; à partir de 10 mois, écrasez à la fourchette et ajoutez du riz.","child":"Avec des pâtes ou du riz, et un peu de fromage râpé."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
