insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-ratatouille-mijotee' and owner_id is null), 1, 'Coupez l’aubergine, les courgettes et les poivrons en dés, les tomates en morceaux. Émincez les oignons et l’ail.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-ratatouille-mijotee' and owner_id is null), 2, 'Faites revenir les oignons et les poivrons 10 minutes dans l’huile, dans une cocotte.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-ratatouille-mijotee' and owner_id is null), 3, 'Ajoutez l’aubergine, les courgettes, l’ail, les tomates et le thym. Couvrez et laissez mijoter 40 minutes à feu doux, en remuant de temps en temps, jusqu’à ce que tout soit fondant.') on conflict do nothing;
