insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-filet-mignon-pommes-fondantes' and owner_id is null), 1, 'Épluchez les pommes de terre et faites-les cuire 20 minutes à la vapeur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-filet-mignon-pommes-fondantes' and owner_id is null), 2, 'Faites dorer le filet mignon de porc 8 minutes de tous côtés dans le beurre, dans une cocotte, avec l’oignon émincé.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-filet-mignon-pommes-fondantes' and owner_id is null), 3, 'Ajoutez les pommes épluchées et coupées en quartiers, le thym et un demi-verre d’eau. Couvrez et laissez cuire 25 minutes à feu doux : la viande doit être cuite à cœur, sans partie rosée.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-filet-mignon-pommes-fondantes' and owner_id is null), 4, 'Tranchez la viande et servez-la avec les pommes, les pommes de terre et le jus. Prélevez la part du bébé avant de saler, puis salez légèrement le reste du plat à votre goût.') on conflict do nothing;
