insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-cabillaud-four-tomates-pommes-de-terre' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Coupez les pommes de terre en fines rondelles, mélangez-les avec 2 cuillerées d’huile, l’ail écrasé et les herbes, puis étalez-les dans un plat.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-cabillaud-four-tomates-pommes-de-terre' and owner_id is null), 2, 'Enfournez 25 minutes, jusqu’à ce que les pommes de terre soient presque tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-cabillaud-four-tomates-pommes-de-terre' and owner_id is null), 3, 'Posez le cabillaud sur les pommes de terre, entourez-le de tomates en rondelles, arrosez du reste d’huile et enfournez 15 minutes : la chair doit être opaque et s’effeuiller.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-cabillaud-four-tomates-pommes-de-terre' and owner_id is null), 4, 'Prélevez la part du bébé avant de saler, puis salez légèrement le reste du plat à votre goût. Les adultes ajoutent un filet de jus de citron.') on conflict do nothing;
