insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-tarte-aux-pommes-normande', 'Tarte aux pommes à la compote', 'Une pâte croustillante, une couche de compote et des pommes en rosace : la tarte du goûter familial.', array['family','baby']::text[], array['dessert','snack']::text[], array['m12_18','m18_24','y2_3']::text[], 12, null, array['mashed','regular']::text[], 8, 'parts', 20, 40, array['gluten','milk']::text[], array['classic','make_ahead','budget','vegetarian','family']::text[], array['Remplacez la moitié des pommes par des poires.','Pour les plus jeunes, servez une part sans la croûte la plus dure.']::text[], '3 jours à température ambiante, sous une cloche, ou au réfrigérateur.', 'Se congèle 2 mois une fois cuite, en parts. Décongelez à température ambiante, puis repassez 10 minutes au four pour la rendre croustillante.', array['Le sucre ajouté n’est pas proposé avant 1 an ; ensuite, une petite part de temps en temps.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un dessert à base de fruits, peu sucré grâce à la compote.', 1, array['autumn','winter']::text[], 'cold', '{"baby":"Avant 1 an, proposez seulement des pommes cuites et de la compote sans sucre ; dès 1 an, une petite part de garniture écrasée, sans la croûte dure.","child":"Une part au goûter avec un verre de lait."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
