insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-tarte-aux-pommes-normande' and owner_id is null), 1, 'Préchauffez le four à 190 °C. Déroulez la pâte brisée dans un moule et piquez le fond à la fourchette.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-tarte-aux-pommes-normande' and owner_id is null), 2, 'Étalez la compote sur le fond de tarte.') on conflict do nothing;
