insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-crumble-pommes-poires', 'Crumble pommes-poires', 'Des fruits fondants sous une pâte sablée croustillante : le dessert réconfortant de l’automne.', array['family','baby']::text[], array['dessert','snack']::text[], array['m12_18','m18_24','y2_3']::text[], 12, null, array['mashed','regular']::text[], 6, null, 15, 35, array['gluten','milk']::text[], array['classic','fiber','make_ahead','budget','vegetarian','family']::text[], array['Changez de fruits selon la saison : prunes, rhubarbe, fruits rouges.','Réduisez le sucre à 30 g avec des fruits bien mûrs.']::text[], '3 jours au réfrigérateur, filmé ; réchauffez au four pour retrouver le croustillant.', 'Se congèle 3 mois, cuit ou cru. Faites cuire le crumble cru sans décongeler en ajoutant 10 minutes ; décongelez le crumble cuit au réfrigérateur avant de le réchauffer.', array['Le sucre ajouté n’est pas proposé avant 1 an ; ensuite, une petite part de temps en temps.','Avant 4 ans : coupez les aliments en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas (risque d’étouffement).']::text[], 'Un dessert riche en fruits, avec des flocons d’avoine pour les fibres.', 1, array['autumn','winter']::text[], 'hot', '{"baby":"Avant 1 an, prélevez des fruits cuits sans pâte et écrasez-les ; après 1 an, une petite part avec un peu de pâte ramollie.","child":"Une part tiède, avec un yaourt nature."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
