insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-crumble-pommes-poires' and owner_id is null), 1, 'Préchauffez le four à 180 °C. Épluchez les pommes et les poires, coupez-les en dés et répartissez-les dans un plat avec la cannelle.') on conflict do nothing;
