insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-quiche-poireaux-courgettes', 'Quiche poireaux et courgettes', 'Une quiche dorée et généreuse, garnie de légumes fondants : à servir chaude avec une salade.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 72, 120, array['regular']::text[], 6, null, 20, 50, array['gluten','eggs','milk']::text[], array['classic','vegetables','lunchbox','budget','vegetarian','family']::text[], array['Ajoutez des dés de jambon ou de saumon.','Remplacez les légumes par des épinards et du chèvre au lait pasteurisé.']::text[], '48 h au réfrigérateur ; se mange froide ou réchauffée une seule fois.', 'Se congèle 2 mois en parts. Décongelez au réfrigérateur et réchauffez 15 minutes au four à 180 °C.', array['Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.']::text[], 'Des légumes, des œufs et du fromage, à compléter par une salade verte.', 1, array['autumn','winter','spring']::text[], 'hot', '{"child":"Une part avec une salade de tomates ou de carottes râpées, puis un fruit."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
