insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-poisson-pane-maison-potatoes', 'Poisson pané maison et potatoes au four', 'Des bâtonnets de poisson croustillants faits maison, bien meilleurs que ceux du commerce.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 72, 120, array['regular']::text[], 4, null, 20, 30, array['gluten','eggs','fish']::text[], array['classic','protein','picky','family']::text[], array['Ajoutez un peu d’emmental râpé dans la chapelure.','Servez avec une sauce au fromage blanc et à la ciboulette.']::text[], '24 h au réfrigérateur ; réchauffez au four pour garder le croustillant.', 'Les bâtonnets panés crus se congèlent 2 mois à plat ; faites-les cuire sans décongeler, 2 minutes de plus par face. Les potatoes se congèlent mal.', array['Poisson cuit à cœur (chair opaque qui s’effeuille) ; retirez soigneusement toutes les arêtes.','Variez les espèces de poisson au fil des semaines et alternez poissons gras et maigres, deux fois par semaine.','Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.']::text[], 'Un poisson maigre, des pommes de terre et une cuisson à la poêle peu grasse.', 2, array[]::text[], 'hot', '{"child":"Avec une salade de carottes râpées ou des haricots verts pour compléter."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
