insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'fa-poisson-pane-maison-potatoes' and owner_id is null), 8, 'lemon', 'citron', 1, 'u', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-poisson-pane-maison-potatoes' and owner_id is null), 1, 'Préchauffez le four à 210 °C. Coupez les pommes de terre en quartiers, mélangez-les avec 2 cuillerées d’huile et le paprika, puis enfournez 30 minutes en les retournant à mi-cuisson.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-poisson-pane-maison-potatoes' and owner_id is null), 2, 'Coupez le cabillaud en bâtonnets en retirant les arêtes. Passez-les dans la farine, puis dans l’œuf battu, puis dans la chapelure.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-poisson-pane-maison-potatoes' and owner_id is null), 3, 'Faites dorer les bâtonnets 3 à 4 minutes de chaque côté dans le reste d’huile : le poisson doit être opaque et s’effeuiller au centre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-poisson-pane-maison-potatoes' and owner_id is null), 4, 'Servez avec les potatoes et des quartiers de citron.') on conflict do nothing;
