insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-gaufres-maison', 'Gaufres maison croustillantes', 'Des gaufres dorées et légères pour un goûter de fête ou un dimanche pluvieux.', array['child','family']::text[], array['snack','breakfast']::text[], array[]::text[], 72, 120, array['regular']::text[], 10, 'gaufres', 15, 25, array['gluten','eggs','milk']::text[], array['classic','make_ahead','budget','vegetarian','family']::text[], array['Remplacez 50 g de farine par de la farine de sarrasin.','Garnissez de fruits rouges et de fromage blanc plutôt que de pâte à tartiner.']::text[], '48 h dans une boîte hermétique ; réchauffez au grille-pain.', 'Se congèlent 2 mois, séparées par du papier cuisson. Réchauffez sans décongeler au grille-pain ou au four.', array['Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.','Gardez les enfants à distance du gaufrier chaud.']::text[], 'Un goûter festif, à accompagner d’un fruit plutôt que de garnitures très sucrées.', 1, array[]::text[], 'hot', '{"child":"Les enfants peuvent verser la pâte avec l’aide d’un adulte et choisir leurs fruits."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
