insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-gaufres-maison' and owner_id is null), 1, 'Mélangez la farine, la levure et le sucre dans un saladier. Ajoutez les œufs, puis le lait petit à petit en fouettant.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-gaufres-maison' and owner_id is null), 2, 'Incorporez le beurre fondu et la vanille. Laissez reposer la pâte 30 minutes si possible.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-gaufres-maison' and owner_id is null), 3, 'Faites chauffer le gaufrier et graissez-le légèrement. Versez une louche de pâte et faites cuire 3 à 4 minutes, jusqu’à ce que la gaufre soit bien dorée.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-gaufres-maison' and owner_id is null), 4, 'Servez aussitôt avec des fruits frais, une compote ou un peu de sucre glace.') on conflict do nothing;
