insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-salade-pates-thon-crudites', 'Salade de pâtes au thon et crudités', 'Une salade fraîche et colorée, parfaite pour les pique-niques et les soirs d’été.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 72, 120, array['regular']::text[], 4, null, 15, 10, array['gluten','fish']::text[], array['classic','lunchbox','complete','quick','budget','family']::text[], array['Remplacez le thon par des sardines, du maquereau ou des œufs durs pour varier.','Ajoutez des dés de fromage ou des olives pour les grands.']::text[], '24 h au réfrigérateur dans une boîte fermée ; en pique-nique, transportez-la dans un sac isotherme.', 'Congélation impossible : les crudités et les pâtes deviennent molles et aqueuses.', array['Le thon est un poisson prédateur : à proposer de temps en temps seulement et en variant les espèces de poisson d’une semaine à l’autre.','Variez les espèces de poisson au fil des semaines et alternez poissons gras et maigres, deux fois par semaine.','Ne laissez pas la salade plus de 2 heures hors du frais.']::text[], 'Un plat froid complet : féculents, poisson et crudités.', 1, array['summer']::text[], 'cold', '{"child":"Les enfants peuvent choisir et couper les crudités avec un couteau adapté."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
