insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-salade-pates-thon-crudites' and owner_id is null), 2, 'Coupez les tomates cerises en deux et le concombre en petits dés.') on conflict do nothing;
