insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-wraps-poulet-crudites', 'Wraps au poulet et crudités', 'Des galettes roulées garnies de poulet doré, de crudités et d’une sauce au fromage frais.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 72, 120, array['regular']::text[], 4, null, 20, 10, array['gluten','milk']::text[], array['quick','lunchbox','protein','vegetables','family']::text[], array['Remplacez le poulet par des restes de poulet rôti ou des pois chiches écrasés.','Ajoutez de l’avocat en lamelles.']::text[], '12 h au réfrigérateur, filmés ; à transporter au frais.', 'Congélation déconseillée une fois garnis ; le poulet cuit seul se congèle 3 mois et se décongèle au réfrigérateur.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Lavez soigneusement les crudités.']::text[], 'Une volaille, des crudités et un féculent dans un repas à manger avec les mains.', 2, array['spring','summer']::text[], 'cold', '{"child":"Chacun compose son wrap : posez les garnitures au centre de la table."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
