insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-tomates-farcies-riz', 'Tomates farcies et leur riz', 'Des tomates gorgées de soleil farcies de viande, avec un riz qui cuit dans leur jus.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 72, 120, array['regular']::text[], 6, null, 25, 50, array['gluten','eggs']::text[], array['classic','iron','protein','complete','family']::text[], array['Mélangez moitié bœuf, moitié chair à saucisse pour la version traditionnelle.','Farcissez aussi des courgettes rondes ou des poivrons.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Se congèlent 2 mois une fois cuites, avec leur riz. Décongelez une nuit au réfrigérateur et réchauffez au four jusqu’à ce que ce soit bien chaud à cœur.', array['Viande cuite à cœur : aucune trace rosée, jus clair.','Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.']::text[], 'Une viande riche en fer, des tomates et du riz dans le même plat.', 2, array['summer']::text[], 'hot', '{"child":"Une tomate par enfant, coupée en deux, avec beaucoup de riz."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
