insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-tomates-farcies-riz' and owner_id is null), 1, 'Préchauffez le four à 180 °C. Coupez un chapeau sur chaque tomate et videz-les à la cuillère en gardant la pulpe.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-tomates-farcies-riz' and owner_id is null), 2, 'Mélangez le bœuf, l’oignon et l’ail hachés, le persil, la chapelure et l’œuf. Remplissez les tomates de farce et replacez les chapeaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-tomates-farcies-riz' and owner_id is null), 3, 'Versez le riz cru et la pulpe hachée au fond d’un plat, ajoutez 30 cl d’eau et l’huile, puis posez les tomates dessus.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'fa-tomates-farcies-riz' and owner_id is null), 4, 'Enfournez 50 minutes : la farce doit être bien cuite à cœur, sans trace rosée, et le riz tendre.') on conflict do nothing;
