insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-gnocchis-gratines-tomate-mozzarella', 'Gnocchis gratinés à la tomate et mozzarella', 'Des gnocchis moelleux dans une sauce tomate au basilic, gratinés sous la mozzarella fondante.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 72, 120, array['regular']::text[], 4, null, 10, 25, array['gluten','milk']::text[], array['quick','picky','world','budget','vegetarian','family']::text[], array['Ajoutez des dés de courgette ou d’aubergine dans la sauce.','Remplacez les gnocchis par des pâtes courtes cuites.']::text[], '24 h au réfrigérateur ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', 'Congélation possible 1 mois, mais les gnocchis deviennent plus mous. Décongelez au réfrigérateur et réchauffez au four.', array['Laissez tiédir : la mozzarella fondue reste brûlante.']::text[], 'Un plat végétarien à compléter par une salade verte et un fruit.', 1, array[]::text[], 'hot', '{"child":"Coupez les gnocchis en deux et servez avec une salade de concombre."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
