insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-gateau-chocolat-fondant', 'Gâteau au chocolat fondant', 'Le gâteau d’anniversaire préféré des enfants, fondant au cœur et facile à réussir.', array['child','family']::text[], array['dessert','snack']::text[], array[]::text[], 72, 120, array['regular']::text[], 8, 'parts', 15, 25, array['gluten','eggs','milk']::text[], array['classic','quick','make_ahead','vegetarian','family']::text[], array['Ajoutez 50 g de poudre d’amande pour un gâteau encore plus moelleux.','Réduisez le sucre à 70 g avec un chocolat à 52 %.']::text[], '4 jours sous une cloche à température ambiante.', 'Se congèle 3 mois, entier ou en parts. Décongelez 2 heures à température ambiante.', array['Œufs bien cuits : prolongez la cuisson de quelques minutes si le centre reste liquide.','Gâteau très sucré : une part pour les grandes occasions.']::text[], 'Un dessert plaisir à réserver aux anniversaires et aux goûters de fête.', 2, array[]::text[], 'cold', '{"child":"Les enfants peuvent casser le chocolat et mélanger la pâte."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
