insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, freezing, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('fa-clafoutis-cerises', 'Clafoutis aux cerises', 'Le dessert du début de l’été : des cerises juteuses prises dans un flan doré à la vanille.', array['child','family']::text[], array['dessert','snack']::text[], array[]::text[], 72, 120, array['regular']::text[], 6, null, 20, 40, array['gluten','eggs','milk']::text[], array['classic','make_ahead','vegetarian','family']::text[], array['Hors saison, utilisez des pommes, des poires ou des abricots.','Réduisez le sucre à 50 g avec des cerises bien mûres.']::text[], '48 h au réfrigérateur, filmé.', 'Congélation déconseillée : le flan devient spongieux et les fruits rendent leur jus.', array['Dénoyautez toutes les cerises et vérifiez qu’il ne reste aucun noyau dans la part des enfants.','Œufs bien cuits : le jaune et le blanc doivent être fermes, sans partie coulante.']::text[], 'Un dessert aux fruits de saison, avec des œufs et du lait.', 2, array['summer']::text[], 'cold', '{"child":"Les enfants peuvent dénoyauter les cerises avec un dénoyauteur, sous surveillance."}'::jsonb, '2026-10-21', 'to_review') on conflict (slug) do nothing;
